# TTL длинный намеренно: справочники правят руками, и после каждого сохранения кеш сбрасывается явно
# (`st.cache_data.clear()`); загрузчики пишут утром. При 120 с каждая третья минута начиналась с 44 запросов.
@st.cache_data(ttl=600, show_spinner=False)
def q(sql: str) -> pd.DataFrame:
    conn = get_connection()
    try:
        return pd.read_sql(sql, conn)
    finally:
        conn.close()


# Связка «склад ↔ площадки» появилась позже остальной схемы: пока
# sql/warehouse_marketplaces.sql не выполнен, таблицы в базе нет, и вкладка
# должна открываться без неё, а не падать на «relation does not exist».
WH_MP = "kabinet_data.warehouse_marketplaces"


@st.cache_data(ttl=300)
def has_table(qualified: str) -> bool:
    return bool(pd.notna(q(f"SELECT to_regclass('{qualified}') AS t").iloc[0]["t"]))


def num_text(v, nd: int = 0) -> str:
    """Число для показа в таблице. Пусто — пустая строка, а не «None».

    Проверено на Streamlit 1.64.0 (24.09.2026): в `st.data_editor` и `st.dataframe` пустое ЧИСЛО
    рисуется словом «None» при любом типе — Int64 и Float64 с pd.NA, float64 с NaN, object с None.
    Приём «nullable-тип с pd.NA» здесь не работает, поэтому числовые колонки, где бывает пусто,
    показываем текстом, а при сохранении разбираем обратно."""
    if v is None or (isinstance(v, float) and pd.isna(v)) or bool(pd.isna(v)):
        return ""
    try:
        f = float(v)
    except (TypeError, ValueError):
        return str(v)
    return str(int(round(f))) if nd == 0 else f"{f:.{nd}f}".rstrip("0").rstrip(".")


def text_num(v, as_int: bool = False):
    """Обратное преобразование. Пусто — None; мусор — тоже None, о нём скажет вызывающий код."""
    s_ = str(v or "").strip().replace(",", ".").replace(" ", "")
    if not s_:
        return None
    try:
        f = float(s_)
    except ValueError:
        return None
    return int(round(f)) if as_int else f


def _int0(v) -> int:
    """Число или ноль. NULL из базы доезжает то None, то NaN, и `v or 0`
    на NaN не спасает: NaN истинен, а int(NaN) бросает ValueError."""
    return 0 if pd.isna(v) else int(v)


@st.cache_data(ttl=600, show_spinner=False)
def q1(sql: str, params: tuple) -> pd.DataFrame:
    """Запрос с параметрами.

    Не через q(): та кэшируется по тексту запроса, а параметры в текст не
    попадают — на второй SKU кэш вернул бы ответ по первому. И не через
    склейку строки: апостроф в артикуле роняет запрос. Здесь параметры —
    часть ключа кеша, поэтому кешировать можно: без этого каждая перерисовка
    страницы открывала 12 соединений ради карточек других вкладок (21.09.2026).
    """
    conn = get_connection()
    try:
        return pd.read_sql(sql, conn, params=params)
    finally:
        conn.close()


def _py(v):
    if v is None or (isinstance(v, float) and pd.isna(v)):
        return None
    if isinstance(v, pd.Timestamp):
        return None if pd.isna(v) else v.date()
    if hasattr(v, "item"):
        try:
            return v.item()
        except Exception:
            return v
    if isinstance(v, str) and v.strip() == "":
        return None
    return v


def q_now(sql: str, params: tuple) -> pd.DataFrame:
    """Чтение БЕЗ кеша — для проверок непосредственно перед записью.

    `q1` кеширует на 600 с, и для показа это правильно, но проверка «можно ли сохранить»
    на кеше десятиминутной давности разрешила бы то, что уже нельзя. Здесь кеш не нужен:
    запрос один на нажатие кнопки.
    """
    conn = get_connection()
    try:
        return pd.read_sql(sql, conn, params=params)
    finally:
        conn.close()


def exec_sql(statements):
    # Единственный путь записи на этой странице — двадцать шесть вызовов из всех
    # разделов. Проверку ставим здесь, а не у каждой из двадцати семи кнопок: так
    # пропущенная кнопка не становится дырой, и правило одно на всю страницу.
    # Два места пишут мимо (реестр нормативов — там своя транзакция с порядком
    # «сначала закрыть, потом вставить»), и у них проверка стоит своя.
    auth.demand("dict.edit", None, "dictionaries", None)
    conn = get_connection()
    try:
        cur = conn.cursor()
        for sql, params in statements:
            cur.execute(sql, params)
        conn.commit()
    finally:
        conn.close()


def _same(a, b) -> bool:
    a, b = _py(a), _py(b)
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    if isinstance(a, float) or isinstance(b, float):
        try:
            return abs(float(a) - float(b)) < 1e-9
        except Exception:
            return str(a) == str(b)
    return str(a) == str(b)


def confirm_delete(key: str, what: str) -> bool:
    """Удаление в два шага: кнопка ставит флаг, второе нажатие — «Да, удалить».

    Одно нажатие, которое сносит справочник, у нас уже было (пулы, 18.09.2026).
    Возвращает True ровно один раз — когда подтверждение получено; вызывающий
    код после этого сам делает запрос и сбрасывает состояние через rerun."""
    flag = f"confirm_{key}"
    if not st.session_state.get(flag):
        if st.button(f"🗑 {_tr('del_col')}", key=f"ask_{key}"):
            st.session_state[flag] = True
            st.rerun()
        return False
    st.warning(_trf("del_confirm_q", what=what))
    c1, c2 = st.columns(2)
    yes = c1.button(_tr("del_confirm_yes"), key=f"yes_{key}", type="primary")
    if c2.button(_tr("del_confirm_no"), key=f"no_{key}"):
        st.session_state.pop(flag, None)
        st.rerun()
    if yes:
        st.session_state.pop(flag, None)
    return yes


def build_updates(orig, edited, table, pk, cols):
    o, e = orig.set_index(pk), edited.set_index(pk)
    out = []
    for idx in e.index:
        if pd.isna(idx) or idx not in o.index:
            continue
        changed = {c: _py(e.at[idx, c]) for c in cols
                   if not _same(e.at[idx, c], o.at[idx, c])}
        if changed:
            sets = ", ".join(f"{c} = %s" for c in changed)
            out.append((f"UPDATE {table} SET {sets} WHERE {pk} = %s",
                        list(changed.values()) + [_py(idx)]))
    return out


def save_block(orig, edited, table, pk, cols):
    ups = build_updates(orig, edited, table, pk, cols)
    if not ups:
        st.info(_tr("nochange"))
        return
    try:
        exec_sql(ups)
        st.cache_data.clear()
        st.success(_tr("saved").format(n=len(ups)))
        st.rerun()
    except Exception as e:
        st.error(_tr("err").format(e=e))


