def fmt_d(v) -> str:
    """Дата текстом. Пустая ячейка в сетке Streamlit рисуется словом «None» при ЛЮБОМ
    типе — это рендер, а не тип данных, поэтому даты показываем строкой."""
    return "—" if (v is None or pd.isna(v)) else pd.Timestamp(v).strftime("%d.%m.%Y")


# ------------------------------------------------------------- категории ---
def _section_cat():
    """Категории по общему приёму справочников (07.10.2026): инструкция → выбор части (связи SKU, дерево, жизненный
    цикл) → список с поиском и фильтрами → карточка по клику. Три части в одном разделе, потому что это один вопрос:
    к какой категории относится товар и в каком он состоянии. Части переключаются сегментами, а не вкладками:
    вкладки Streamlit исполняются все разом при каждом действии.

    Что не менялось: дерево и его ключи приходят из ERP (SKU Master Loader), своя подпись главнее перевода ERP,
    ручную связь и ручной статус загрузчик не перетирает, дата действия статуса соблюдается."""
    dict_kit.instruction(i18n_t("cat.about"), i18n_t("cat.hint"))

    # Читаем вью, а не таблицу: правило «что человек видит на своём языке» живёт одним
    # написанием в базе, иначе страницы разойдутся с загрузчиком и между собой.
    дерево = q("""
        SELECT t.category_key, t.parent_key, t.depth, t.level1, t.level2, t.level3, t.title,
               t.title_en, t.en_ambiguous, t.label_ru, t.label_uk, t.label_en, t.label_en_source,
               t.name_ru, t.name_uk, t.name_en,
               (SELECT count(*) FROM kabinet_data.sku_category_links l
                 WHERE l.category_key = t.category_key)::int AS own_skus
          FROM kabinet_data.v_sku_category_tree t
         -- Порядок дерева: узел первого уровня, затем КАЖДАЯ его ветка целиком — второй уровень и сразу его
         -- третий. Сортировка по глубине раньше ветки ставила потомка не под своим родителем.
         ORDER BY t.level1, COALESCE(t.level2, ''), t.depth, COALESCE(t.level3, '')
    """)
    # Путь и название товара — на языке интерфейса; где перевода ERP ещё нет, остаётся оригинал. Выражения колонок
    # собираются строками, а не f-строкой с кавычками: на Python 3.9 обратный слеш в подстановке — ошибка компиляции.
    _имя_кол = "m.name"
    _ур_кол = ["t.level1", "t.level2", "t.level3"]
    if get_lang() == "en":
        _имя_кол = "NULLIF(m.name_en, ''), m.name"
        _ур_кол = ["t.level1_en, t.level1", "t.level2_en, t.level2", "t.level3_en, t.level3"]
    связи = q("""
        SELECT m.sku, COALESCE(""" + _имя_кол + """, '') AS name,
               l.category_key, COALESCE(l.key_source, '') AS key_source, l.updated_by, l.updated_at,
               COALESCE(""" + _ур_кол[0] + """, '') AS level1,
               COALESCE(""" + _ур_кол[1] + """, '') AS level2,
               COALESCE(""" + _ур_кол[2] + """, '') AS level3
          FROM kabinet_data.sku_master m
          LEFT JOIN kabinet_data.sku_category_links l ON l.sku = m.sku
          LEFT JOIN kabinet_data.sku_category_tree t ON t.category_key = l.category_key
         ORDER BY m.sku
    """)
    if дерево.empty:
        st.info(i18n_t("cat.empty"))
        return

    _без = int(связи["category_key"].isna().sum())
    k1, k2, k3, k4 = st.columns(4)
    k1.metric(i18n_t("cat.k_nodes"), len(дерево))
    k2.metric(i18n_t("cat.k_linked"), len(связи) - _без)
    k3.metric(i18n_t("cat.k_nocat"), _без)
    k4.metric(i18n_t("cat.k_manual"), int((связи["key_source"] == "manual").sum()))
    # Откуда у связи категория: унаследованная не должна выглядеть заявленной
    _ист = связи[связи["category_key"].notna()]["key_source"].value_counts().to_dict()
    if _ист:
        st.caption(" · ".join(f"{i18n_t('cat.src.' + k)}: {v}" for k, v in sorted(_ист.items())))

    PARTS = ["links", "tree", "life"]
    part = st.segmented_control(i18n_t("cat.part"), PARTS, key="cat_part",
                                format_func=lambda p: i18n_t({"links": "cat.tab_links", "tree": "cat.tab_tree",
                                                              "life": "cat.tab_life"}[p]))
    # повторный клик по выбранному сегменту снимает выбор (Streamlit) — возвращаем последний
    if part is None:
        part = st.session_state.get("cat_part_last", "links")
    st.session_state["cat_part_last"] = part

    # путь категории на языке интерфейса — общий для списка связей и выбора категории
    _поле = {"ru": "label_ru", "uk": "label_uk"}.get(get_lang(), "label_en")
    _подпись = dict(zip(дерево["category_key"], [as_text(v) for v in дерево[_поле]]))
    _родитель = dict(zip(дерево["category_key"], дерево["parent_key"]))

    def путь(ключ) -> str:
        части, узел = [], ключ
        while узел and узел in _подпись:
            части.append(_подпись[узел]); узел = _родитель.get(узел)
        return " / ".join(reversed(части))

    if part == "links":
        _cat_links(дерево, связи, путь)
    elif part == "tree":
        _cat_tree(дерево)
    else:
        _cat_life(связи)


def _cat_links(дерево, связи, путь):
    """Связь SKU с деревом: список → карточка SKU, где категорию ставят вручную или возвращают автоматическую."""
    st.caption(i18n_t("cat.links_hint"))
    SRC = ["all", "erp", "erp:base", "erp:kit", "manual", "none"]
    f1, f2, f3 = st.columns([2, 1.4, 1.2])
    поиск = dict_kit.search_input(i18n_t("cat.f_search"), "cat_f_search", _tr, "41324000, Amoladora…", where=f1).lower()
    _l1 = sorted({as_text(v) for v in связи["level1"] if as_text(v)})
    ур1 = f2.selectbox(i18n_t("cat.f_level1"), ["all"] + _l1, key="cat_f_l1",
                       format_func=lambda x: i18n_t("cat.f_all") if x == "all" else x)
    ист = f3.selectbox(i18n_t("cat.col_source"), SRC, key="cat_f_src",
                       format_func=lambda x: i18n_t("cat.f_all") if x == "all"
                       else (i18n_t("cat.src_none") if x == "none" else i18n_t("cat.src." + x)))
    сито = связи
    if поиск:
        сито = сито[[поиск in as_text(a).lower() or поиск in as_text(b).lower()
                     for a, b in zip(сито["sku"], сито["name"])]]
    if ур1 != "all":
        сито = сито[сито["level1"] == ур1]
    if ист == "none":
        сито = сито[сито["category_key"].isna()]
    elif ист != "all":
        сито = сито[сито["key_source"] == ист]
    st.caption(i18n_t("cat.shown", n=len(сито), all=len(связи)))

    lst = pd.DataFrame({
        "sku": сито["sku"],
        "name": [as_text(v)[:70] for v in сито["name"]],
        "category": [" / ".join(x for x in (as_text(a), as_text(b), as_text(c)) if x) or "—"
                     for a, b, c in zip(сито["level1"], сито["level2"], сито["level3"])],
        "source": [i18n_t("cat.src." + as_text(v)) if as_text(v) else i18n_t("cat.src_none")
                   for v in сито["key_source"]],
    })
    options = list(сито["sku"])
    picked = dict_kit.table_pick(lst, options, "cat_links", (поиск, ур1, ист), column_config={
        "sku": st.column_config.TextColumn("SKU", width=130),
        "name": st.column_config.TextColumn(i18n_t("cat.col_name"), width="large"),
        "category": st.column_config.TextColumn(i18n_t("cat.col_category"), width="large"),
        "source": st.column_config.TextColumn(i18n_t("cat.col_source"), width=160, help=i18n_t("cat.src_help")),
    })
    st.caption(i18n_t("cat.filtered_empty") if not options else i18n_t("cat.list_hint"))
    if not options:
        return
    labels = {s: f"{s} — {as_text(n)[:60]}" for s, n in zip(сито["sku"], сито["name"])}
    st.markdown("#### " + i18n_t("cat.link_card"))
    sel = dict_kit.card_pick("SKU", options, labels, "cat_link_card", picked)
    r = связи.set_index("sku").loc[sel]
    can_edit = auth.can("dict.edit")
    with st.container(border=True):
        st.markdown(f"**{sel}** · {as_text(r['name'])}")
        if pd.notna(r["category_key"]):
            st.caption(i18n_t("cat.link_now", path=путь(r["category_key"]) or "—",
                              src=i18n_t("cat.src." + as_text(r["key_source"]))))
        else:
            st.caption(i18n_t("cat.link_none"))
        _ключи = list(дерево["category_key"])
        _пути = {k: путь(k) for k in _ключи}
        _cur = r["category_key"] if pd.notna(r["category_key"]) and r["category_key"] in _пути else None
        new_key = st.selectbox(i18n_t("cat.manual_cat"), [None] + _ключи,
                               index=0 if _cur is None else _ключи.index(_cur) + 1,
                               format_func=lambda k: i18n_t("cat.pick_cat") if k is None else _пути.get(k, k),
                               key=f"cat_link_sel_{sel}", disabled=not can_edit, help=i18n_t("cat.manual_cat_help"))
        b1, b2 = st.columns(2)
        if b1.button(i18n_t("cat.manual_btn"), type="primary", key=f"cat_link_save_{sel}", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            if new_key is None:
                st.error(i18n_t("cat.pick_cat_err"))
            elif new_key == _cur and r["key_source"] == "manual":
                st.info(i18n_t("cat.nochange"))
            else:
                try:
                    exec_sql([("""INSERT INTO kabinet_data.sku_category_links
                                      (sku, category_key, key_source, updated_by, updated_at)
                                  VALUES (%s, %s, 'manual', %s, now())
                                  ON CONFLICT (sku) DO UPDATE
                                     SET category_key = EXCLUDED.category_key, key_source = 'manual',
                                         updated_by = EXCLUDED.updated_by, updated_at = now()""",
                               (sel, new_key, _actor()))])
                    st.cache_data.clear(); st.success(i18n_t("cat.manual_ok", sku=sel)); st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))
        st.caption(i18n_t("cat.manual_hint"))
        # Ручную связь можно снять: тогда утром загрузчик снова поставит автоматическую. До его прогона у SKU
        # категории не будет — это сказано в подтверждении.
        if can_edit and r["key_source"] == "manual":
            with b2:
                if confirm_delete(f"catlink_{sel}", i18n_t("cat.reset_what", sku=sel)):
                    try:
                        exec_sql([("DELETE FROM kabinet_data.sku_category_links WHERE sku = %s AND key_source = 'manual'",
                                   (sel,))])
                        st.cache_data.clear(); st.success(i18n_t("cat.reset_ok", sku=sel)); st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))


def _cat_tree(дерево):
    """Дерево ERP: список узлов → карточка узла, где правятся свои подписи на трёх языках. Ключи и названия ERP не
    правятся — их приносит загрузчик."""
    st.caption(i18n_t("cat.tree_hint"))
    _пер = int(дерево["title_en"].notna().sum())
    _спор = int((дерево["label_en_source"] == "ambiguous").sum())
    _руч = int((дерево["label_en_source"] == "manual").sum())
    st.caption(i18n_t("cat.en_stats", n=_пер, all=len(дерево), man=_руч))
    if _спор:
        st.caption(i18n_t("cat.en_amb", amb=_спор))

    # SKU с учётом потомков: у узла первого уровня своих связей почти нет — они висят на третьем
    _родитель = dict(zip(дерево["category_key"], дерево["parent_key"]))
    _итого = {k: 0 for k in дерево["category_key"]}
    for ключ, своих in zip(дерево["category_key"], дерево["own_skus"]):
        узел = ключ
        while узел:
            _итого[узел] = _итого.get(узел, 0) + int(своих)
            узел = _родитель.get(узел)

    _поле = {"ru": "label_ru", "uk": "label_uk"}.get(get_lang(), "label_en")
    f1, f2, f3 = st.columns([2, 1.4, 1])
    поиск = dict_kit.search_input(i18n_t("cat.f_tree"), "cat_t_search", _tr, "Шуруповерт, Garden…", where=f1).lower()
    _l1 = list(dict.fromkeys(as_text(v) for v in дерево.loc[дерево["depth"] == 1, _поле]))
    ур1 = f2.selectbox(i18n_t("cat.f_level1"), ["all"] + _l1, key="cat_t_l1",
                       format_func=lambda x: i18n_t("cat.f_all") if x == "all" else x)
    глуб = f3.selectbox(i18n_t("cat.f_depth"), ["all", 1, 2, 3], key="cat_t_depth",
                        format_func=lambda x: i18n_t("cat.f_all") if x == "all" else i18n_t("cat.depth_n", n=x))
    вид = дерево
    if ур1 != "all":
        _k1 = дерево.loc[(дерево["depth"] == 1) & (дерево[_поле].map(as_text) == ур1), "level1"]
        вид = вид[вид["level1"].isin(set(_k1))]
    if глуб != "all":
        вид = вид[вид["depth"] == глуб]
    if поиск:
        вид = вид[[поиск in as_text(a).lower() or поиск in as_text(b).lower() or поиск in as_text(c).lower()
                   for a, b, c in zip(вид[_поле], вид["title"], вид["title_en"])]]
    st.caption(i18n_t("cat.shown", n=len(вид), all=len(дерево)))
    lst = pd.DataFrame({
        "title": ["— " * (int(d) - 1) + as_text(t) for d, t in zip(вид["depth"], вид[_поле])],
        "erp": [as_text(v) for v in вид["title"]],
        "en_erp": [as_text(v) for v in вид["title_en"]],
        "own": [num_text(v) for v in вид["own_skus"]],
        "total": [num_text(_итого.get(k, 0)) for k in вид["category_key"]],
        "label": [i18n_t("cat.lbl_src." + as_text(v, "erp")) for v in вид["label_en_source"]],
    })
    options = list(вид["category_key"])
    picked = dict_kit.table_pick(lst, options, "cat_tree", (поиск, ур1, глуб), column_config={
        "title": st.column_config.TextColumn(i18n_t("cat.col_title"), width="large"),
        "erp": st.column_config.TextColumn(i18n_t("cat.col_erp"), width="medium"),
        "en_erp": st.column_config.TextColumn(i18n_t("cat.col_en_erp"), width="medium"),
        "own": st.column_config.TextColumn(i18n_t("cat.col_own"), width=90),
        "total": st.column_config.TextColumn(i18n_t("cat.col_total"), width=110),
        "label": st.column_config.TextColumn(i18n_t("cat.col_label_src"), width=140, help=i18n_t("cat.lbl_src_help")),
    })
    st.caption(i18n_t("cat.filtered_empty") if not options else i18n_t("cat.list_hint"))
    if not options:
        return
    labels = {k: ("— " * (int(d) - 1)) + as_text(t) for k, d, t in zip(вид["category_key"], вид["depth"], вид[_поле])}
    st.markdown("#### " + i18n_t("cat.node_card"))
    sel = dict_kit.card_pick(i18n_t("cat.col_title"), options, labels, "cat_node_card", picked)
    r = дерево.set_index("category_key").loc[sel]
    can_edit = auth.can("dict.edit")
    with st.container(border=True):
        st.markdown(f"**{as_text(r[_поле])}**")
        st.caption(i18n_t("cat.node_meta", erp=" / ".join(x for x in (as_text(r["level1"]), as_text(r["level2"]),
                                                                       as_text(r["level3"])) if x),
                          en=as_text(r["title_en"], "—"), own=int(r["own_skus"]), total=_итого.get(sel, 0)))
        if bool(r["en_ambiguous"]) if pd.notna(r["en_ambiguous"]) else False:
            st.caption(i18n_t("cat.node_amb"))
        c1, c2, c3 = st.columns(3)
        ru = c1.text_input("RU", value=as_text(r["name_ru"]), key=f"cat_n_ru_{sel}", disabled=not can_edit,
                           help=i18n_t("cat.name_help"))
        uk = c2.text_input("UK", value=as_text(r["name_uk"]), key=f"cat_n_uk_{sel}", disabled=not can_edit,
                           help=i18n_t("cat.name_help"))
        en = c3.text_input("EN", value=as_text(r["name_en"]), key=f"cat_n_en_{sel}", disabled=not can_edit,
                           help=i18n_t("cat.name_en_help"))
        if st.button(i18n_t("cat.save_names"), type="primary", key=f"cat_n_save_{sel}", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            было = (as_text(r["name_ru"]), as_text(r["name_uk"]), as_text(r["name_en"]))
            стало = (ru.strip(), uk.strip(), en.strip())
            if было == стало:
                st.info(i18n_t("cat.nochange"))
            else:
                try:
                    exec_sql([("""INSERT INTO kabinet_data.category_names
                                      (category_key, name_ru, name_uk, name_en, updated_by, updated_at)
                                  VALUES (%s, NULLIF(%s,''), NULLIF(%s,''), NULLIF(%s,''), %s, now())
                                  ON CONFLICT (category_key) DO UPDATE
                                     SET name_ru = EXCLUDED.name_ru, name_uk = EXCLUDED.name_uk,
                                         name_en = EXCLUDED.name_en,
                                         updated_by = EXCLUDED.updated_by, updated_at = now()""",
                               (sel,) + стало + (_actor(),))])
                    st.cache_data.clear(); st.success(i18n_t("cat.saved", n=1)); st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))
        if int(r["own_skus"]):
            skus = q1("""SELECT m.sku, m.name FROM kabinet_data.sku_category_links l
                         JOIN kabinet_data.sku_master m ON m.sku = l.sku WHERE l.category_key = %s ORDER BY 1""", (sel,))
            st.caption(i18n_t("cat.node_skus", n=len(skus)))
            st.dataframe(skus.rename(columns={"sku": "SKU", "name": i18n_t("cat.col_name")}), hide_index=True,
                         use_container_width=True, height=min(260, 38 + 35 * len(skus)))


def _cat_life(связи):
    """Жизненный цикл: список действующих статусов → карточка пары SKU × маркетплейс с историей ручных решений,
    новым решением с датой и отменой ещё не наступившего. Удалять наступившее решение нельзя — это история."""
    st.caption(i18n_t("cat.life_hint"))
    цикл = q("""SELECT sku, marketplace, status, is_manual, effective_from, COALESCE(updated_by, '') AS updated_by
                FROM kabinet_data.v_sku_lifecycle_current ORDER BY is_manual DESC, sku, marketplace""")
    будущие = q("""SELECT sku, marketplace, status, effective_from, COALESCE(reason, '') AS reason
                   FROM kabinet_data.sku_lifecycle_manual WHERE effective_from > current_date
                   ORDER BY effective_from, sku""")
    if not будущие.empty:
        # отложенное решение показываем отдельно: иначе «с 01.11» поставили, а в таблице по-прежнему «активен»
        st.info(i18n_t("cat.life_future", n=len(будущие)))
    СТАТУСЫ = ["active", "not_launched", "phasing_out", "seasonal_pause", "discontinued"]
    _имя = dict(zip(связи["sku"], связи["name"]))
    f1, f2, f3, f4 = st.columns([2, 1, 1.2, 1])
    поиск = dict_kit.search_input(i18n_t("cat.f_search"), "cat_l_search", _tr, "41324000…", where=f1).lower()
    _mps = sorted({as_text(v) for v in цикл["marketplace"]}) if not цикл.empty else []
    mp = f2.selectbox(i18n_t("cat.life_mp"), ["all"] + _mps, key="cat_l_mp_f",
                      format_func=lambda x: i18n_t("cat.f_all") if x == "all" else x)
    стат = f3.selectbox(i18n_t("cat.life_status"), ["all"] + СТАТУСЫ, key="cat_l_st_f",
                        format_func=lambda x: i18n_t("cat.f_all") if x == "all" else i18n_t("cat.life." + x))
    реш = f4.selectbox(i18n_t("cat.life_who"), ["all", "manual", "calc"], key="cat_l_who_f",
                       format_func=lambda x: i18n_t("cat.f_all") if x == "all"
                       else i18n_t("cat.life_manual" if x == "manual" else "cat.life_calc"))
    вид = цикл
    if not вид.empty:
        if поиск:
            вид = вид[[поиск in as_text(s).lower() or поиск in as_text(_имя.get(s)).lower() for s in вид["sku"]]]
        if mp != "all":
            вид = вид[вид["marketplace"] == mp]
        if стат != "all":
            вид = вид[вид["status"] == стат]
        if реш != "all":
            вид = вид[вид["is_manual"].astype(bool) == (реш == "manual")]
    st.caption(i18n_t("cat.shown", n=len(вид), all=len(цикл)))
    keys = [f"{s}|{m}" for s, m in zip(вид["sku"], вид["marketplace"])] if not вид.empty else []
    lst = pd.DataFrame({
        "sku": list(вид["sku"]) if keys else [],
        "name": [as_text(_имя.get(s))[:60] for s in вид["sku"]] if keys else [],
        "mp": list(вид["marketplace"]) if keys else [],
        "status": [i18n_t("cat.life." + as_text(v)) for v in вид["status"]] if keys else [],
        "who": [i18n_t("cat.life_manual") if bool(v) else i18n_t("cat.life_calc") for v in вид["is_manual"]] if keys else [],
        "from": [fmt_d(v) for v in вид["effective_from"]] if keys else [],
        "author": [as_text(v, "—") for v in вид["updated_by"]] if keys else [],
    })
    picked = dict_kit.table_pick(lst, keys, "cat_life", (поиск, mp, стат, реш), column_config={
        "sku": st.column_config.TextColumn("SKU", width=130),
        "name": st.column_config.TextColumn(i18n_t("cat.col_name"), width="large"),
        "mp": st.column_config.TextColumn(i18n_t("cat.life_mp"), width=90),
        "status": st.column_config.TextColumn(i18n_t("cat.life_status"), width=130),
        "who": st.column_config.TextColumn(i18n_t("cat.life_who"), width=100),
        "from": st.column_config.TextColumn(i18n_t("cat.life_from"), width=100),
        "author": st.column_config.TextColumn(i18n_t("cat.col_author"), width="small"),
    })
    st.caption(i18n_t("cat.filtered_empty") if not keys else i18n_t("cat.list_hint"))
    can_edit = auth.can("dict.edit")
    if keys:
        labels = {k: f"{k.split('|')[0]} · {k.split('|')[1]}" for k in keys}
        st.markdown("#### " + i18n_t("cat.life_card"))
        sel = dict_kit.card_pick(i18n_t("cat.life_pair"), keys, labels, "cat_life_card", picked)
        s_sku, s_mp = sel.split("|", 1)
        r = цикл[(цикл["sku"] == s_sku) & (цикл["marketplace"] == s_mp)].iloc[0]
        with st.container(border=True):
            st.markdown(f"**{s_sku} · {s_mp}** — {as_text(_имя.get(s_sku))}")
            st.caption(i18n_t("cat.life_now", st=i18n_t("cat.life." + as_text(r["status"])),
                              who=i18n_t("cat.life_manual") if bool(r["is_manual"]) else i18n_t("cat.life_calc"),
                              d=fmt_d(r["effective_from"]) or "—"))
            ист = q1("""SELECT status, effective_from, COALESCE(reason, '') AS reason, COALESCE(updated_by, '') AS who
                        FROM kabinet_data.sku_lifecycle_manual WHERE sku = %s AND marketplace = %s
                        ORDER BY effective_from DESC""", (s_sku, s_mp))
            if ист.empty:
                st.caption(i18n_t("cat.life_no_manual"))
            else:
                st.dataframe(pd.DataFrame({
                    i18n_t("cat.life_status"): [i18n_t("cat.life." + as_text(v)) for v in ист["status"]],
                    i18n_t("cat.life_from"): [fmt_d(v) for v in ист["effective_from"]],
                    i18n_t("cat.life_reason"): [as_text(v) for v in ист["reason"]],
                    i18n_t("cat.col_author"): [as_text(v, "—") for v in ист["who"]],
                }), hide_index=True, use_container_width=True, height=min(220, 38 + 35 * len(ист)))
                # не наступившее решение можно отменить: оно ещё ничего не меняло
                for d in [v for v in ист["effective_from"] if pd.to_datetime(v).date() > date.today()]:
                    if can_edit and confirm_delete(f"catlife_{s_sku}_{s_mp}_{d}",
                                                   i18n_t("cat.life_cancel_what", d=fmt_d(d))):
                        try:
                            exec_sql([("""DELETE FROM kabinet_data.sku_lifecycle_manual
                                          WHERE sku = %s AND marketplace = %s AND effective_from = %s
                                            AND effective_from > current_date""", (s_sku, s_mp, d))])
                            st.cache_data.clear(); st.rerun()
                        except Exception as e:
                            st.error(_trf("err", e=e))
            if can_edit:
                _life_form(s_sku, s_mp, СТАТУСЫ, f"cat_life_c_{sel}")
    st.markdown("#### " + i18n_t("cat.life_set"))
    if not can_edit:
        st.caption(i18n_t("cat.life_ro"))
        return
    st.caption(i18n_t("cat.life_new_hint"))
    c1, c2 = st.columns([1.4, 1])
    l_sku = c1.selectbox("SKU", list(связи["sku"]), key="cat_l_sku",
                         format_func=lambda s: f"{s} — {as_text(_имя.get(s))[:50]}")
    _all_mps = q("SELECT code FROM kabinet_data.v_marketplaces_selectable ORDER BY code")
    _mp_opts = sorted(set(_mps) | {as_text(v) for v in _all_mps["code"]}) if not _all_mps.empty else (_mps or ["ES"])
    l_mp = c2.selectbox(i18n_t("cat.life_mp"), _mp_opts, key="cat_l_mp", help=i18n_t("cat.life_mp_help"))
    _life_form(l_sku, l_mp, СТАТУСЫ, "cat_life_new")
    st.caption(i18n_t("cat.life_note"))


def _life_form(sku, mp, СТАТУСЫ, key):
    """Новое ручное решение по статусу пары SKU × маркетплейс: статус, дата начала, причина."""
    c3, c4 = st.columns([1.2, 1])
    # статус в базе английским кодом — его читают расчёты; на экране слово
    l_st = c3.selectbox(i18n_t("cat.life_status"), СТАТУСЫ, format_func=lambda s: i18n_t("cat.life." + s),
                        key=f"{key}_st")
    l_from = c4.date_input(i18n_t("cat.life_from"), value=date.today(), key=f"{key}_from",
                           help=i18n_t("cat.life_from_help"))
    l_why = st.text_input(i18n_t("cat.life_reason"), key=f"{key}_why", help=i18n_t("cat.life_reason_help"))
    if st.button(i18n_t("cat.life_btn"), type="primary", key=f"{key}_btn"):
        try:
            exec_sql([("""INSERT INTO kabinet_data.sku_lifecycle_manual
                              (sku, marketplace, status, effective_from, reason, updated_by, updated_at)
                          VALUES (%s, %s, %s, %s, NULLIF(%s,''), %s, now())
                          ON CONFLICT (sku, marketplace, effective_from) DO UPDATE
                             SET status = EXCLUDED.status, reason = EXCLUDED.reason,
                                 updated_by = EXCLUDED.updated_by, updated_at = now()""",
                       (sku, mp, l_st, l_from, (l_why or "").strip(), _actor()))])
            st.cache_data.clear()
            st.success(i18n_t("cat.life_ok", sku=sku, d=l_from.strftime("%d.%m.%Y")))
            st.rerun()
        except Exception as e:
            st.error(_trf("err", e=e))


# ---------------------------------------------------------------- склады ---
def _section_wh():
    st.caption(_tr("wh_hint"))
    wh = q("""
        SELECT w.id, COALESCE(a.display_name, w.name) AS name, w.code, w.type,
               w.marketplace, w.country, w.shipping_priority, w.is_active,
               w.canonical_id, w.note, w.name AS erp_name
        FROM kabinet_data.warehouses w
        LEFT JOIN kabinet_data.warehouse_attributes a ON a.warehouse_id = w.id
        ORDER BY 2
    """)
    if wh.empty:
        st.info(_tr("no_data"))
    else:
        # ── маркетплейсы и пулы — из справочников: список склада обязан совпадать с ними (доработка 17.09) ──
        mp = q("""
            SELECT id, code, name, country_alpha2 AS country, platform_short AS channel
            FROM kabinet_data.v_marketplaces_selectable ORDER BY code
        """)
        pools_df = q("""
            SELECT p.id, p.name, string_agg(DISTINCT m.country_alpha2, ',') AS country, string_agg(m.code, ', ' ORDER BY m.code) AS members
            FROM kabinet_data.pools p
            LEFT JOIN kabinet_data.pool_members pm ON pm.pool_id = p.id AND pm.valid_from <= current_date AND (pm.valid_to IS NULL OR pm.valid_to > current_date)
            LEFT JOIN kabinet_data.marketplaces_new m ON m.id = pm.marketplace_id
            GROUP BY p.id, p.name ORDER BY p.name
        """) if has_table("kabinet_data.pools") else pd.DataFrame(columns=["id", "name", "country", "members"])
        # варианты привязки: ('marketplace', id) → (подпись, короткая подпись, страны); у пула страны — всех участников
        # (по ТЗ 004 пул одностранный, но фильтр по стране не должен терять пул, если это когда-нибудь изменится)
        # Пул БЕЗ действующих участников — реальный случай с 28.09.2026 (Spain распущен): LEFT JOIN
        # не находит ни одной строки, `string_agg` по пустой группе возвращает NULL, а pandas отдаёт
        # его как NaN. `NaN or ""` даёт сам NaN (NaN в Python истинен), и `.split()` падает
        # AttributeError — так упала вкладка «Склады». Приведение только через `as_text`.
        targets = {("marketplace", int(r["id"])): (f'{r["code"]} · {r["name"]}', r["code"],
                                                   {as_text(r["country"])} - {""}) for _, r in mp.iterrows()}
        targets.update({("pool", int(r["id"])): (f'{_tr("t_pool")} {r["name"]} ({as_text(r["members"], "—")})',
                                                 f'{_tr("t_pool")} {r["name"]}',
                                                 set(as_text(r["country"]).split(",")) - {""}) for _, r in pools_df.iterrows()})
        WP = "kabinet_data.warehouse_priorities"
        prios = q(f"SELECT warehouse_id, priority, target_type, target_id FROM {WP}") if has_table(WP) else pd.DataFrame(columns=["warehouse_id", "priority", "target_type", "target_id"])
        prio_by_wh = {int(k): {int(r.priority): (r.target_type, int(r.target_id)) for r in g.itertuples()} for k, g in prios.groupby("warehouse_id")}
        def _tlabel(key):
            return targets.get(key, (f"{key[0]} #{key[1]}", f"{key[0]} #{key[1]}", set()))[0]

        _dup_state = {"dup": []}

        def dup_stop() -> bool:
            """Повтор маркетплейса раньше только подсвечивался: приоритеты не писались,
            а маршруты подпитки сохранялись, и человек видел «Сохранено»."""
            if _dup_state["dup"]:
                st.error(_tr("wh_prio_dup_block"))
                return True
            return False

        # ── склад: по алфавиту, рядом тип (доработка 17.09) ──
        show_all = st.toggle(_tr("wh_show_sales"), value=True, key="wh_show_all")
        st.caption(_tr("wh_show_sales_hint"))
        pool = wh if show_all else wh[wh["type"] == "storage"]
        if pool.empty:
            st.info(_tr("no_data"))
        else:
            def _type_lbl(tp):
                return _tr(f"t_{tp}") if tp else "—"
            titles = {int(r["id"]): f'{r["name"]} · {_type_lbl(r["type"])}' + (f' ({r["code"]})' if r["code"] else "") for _, r in pool.iterrows()}
            sel = st.selectbox(_tr("wh_pick"), sorted(titles, key=lambda i: str(pool.set_index("id").loc[i, "name"]).lower()),
                               format_func=lambda i: titles[i], key="wh_pick")
            row = wh.set_index("id").loc[sel]
            attrs = q1("""SELECT owner_company, owner_source, owner_synced_at, long_term_control,
                                 is_partner, display_name
                          FROM kabinet_data.warehouse_attributes WHERE warehouse_id = %s""", (int(sel),))
            _owner = attrs["owner_company"].iloc[0] if not attrs.empty else None
            _own_src = attrs["owner_source"].iloc[0] if not attrs.empty else None
            _partner = bool(attrs["is_partner"].iloc[0]) if not attrs.empty and "is_partner" in attrs.columns else False
            _long_term = bool(attrs["long_term_control"].iloc[0]) if not attrs.empty else False
            _disp = (attrs["display_name"].iloc[0] if not attrs.empty and "display_name" in attrs.columns else None)
            _disp = "" if _disp is None or pd.isna(_disp) else str(_disp)
            # `is False` тут не работал: из pandas приходит `numpy.bool`, а он НЕ тот же объект,
            # что питоновский `False`. В NumPy 2 он и печатается как «bool», поэтому в отладке
            # выглядит правильным. Проверка всегда ложна — неактивный склад подписывался «Активен».
            facts = [_type_lbl(row["type"]), as_text(row["country"], "—"),
                     _tr("wh_active") if bool(row["is_active"]) else _tr("wh_inactive")]
            st.markdown(f'#### {_disp or row["name"]}')
            st.caption(" · ".join(facts))
            # Имя из ERP правится только в ERP: по `warehouses.name` склады сопоставляются
            # в остатках, накладных и маршрутах, и переименование у нас порвало бы связи
            # (так уже было с дублями «Amazon FBA XX»). Поэтому здесь — отдельное имя для экрана.
            # ВАЖНО: `row["name"]` — уже подпись для экрана (запрос отдаёт COALESCE(display_name, name)),
            # а здесь нужно имя ИЗ ERP, иначе подсказка «в ERP склад называется …» назовёт
            # отображаемое имя и будет врать ровно про то, что объясняет. Оно в `erp_name`.
            _erp = as_text(row.get("erp_name"), as_text(row["name"]))
            disp_new = st.text_input(_tr("wh_display"), value=_disp, key=f"wh_disp_{sel}",
                                     placeholder=_erp, help=_trf("wh_display_help", n=_erp))
            if _disp:
                st.caption(_trf("wh_display_erp", n=_erp))
            # владелец — реквизит ERP (Odoo, stock.warehouse.company_id): в Кабинете только показываем.
            # У складов, которых в Odoo нет (FBA, Piasecznie, Тернополь), значение дало снабжение —
            # подписываем источник, иначе строка обещает ERP там, где её нет.
            if _owner:
                st.caption(_trf("wh_owner_manual" if str(_own_src or "").startswith("manual") else "wh_owner_line", o=_owner))
            else:
                st.caption(_tr("wh_owner_none"))
            if _partner:
                st.warning(_tr("wh_partner"))

            # ── приоритеты маркетплейсов/пулов: только у склада продаж (доработка 17.09, п.1) ──
            st.markdown("##### " + _tr("wh_mp_h"))
            prev_prio = dict(prio_by_wh.get(int(sel), {}))
            new_prio = None
            if row["type"] != "sales" and not prev_prio:
                st.caption(_tr("wh_prio_not_sales"))
            elif not has_table(WP):
                st.warning(_tr("wh_prio_missing"))
            else:
                st.caption(_tr("wh_prio_hint"))
                if row["type"] != "sales":
                    st.info(_tr("wh_prio_legacy"))   # привязка есть у склада не-продаж (Мадрид → MM-ES): показываем, чтобы человек решил
                # фильтр по стране сужает список маркетплейсов (доработка 17.09, п.2)
                countries = sorted({c for (_, _, cs) in targets.values() for c in cs})
                _c_all = _tr("all_countries")
                c_sel = st.selectbox(_tr("wh_country_filter"), [_c_all] + countries,
                                     index=([_c_all] + countries).index(row["country"]) if row["country"] in countries else 0, key=f"wh_cf_{sel}")
                opts = [k for k, (_, _, cs) in targets.items() if c_sel == _c_all or c_sel in cs or k in prev_prio.values()]
                # пустой вариант как "" Streamlit рисует словом «None» — берём прочерк
                _empty = _tr("prio_empty")
                opt_labels = [_empty] + [_tlabel(k) for k in opts]
                label_to_key = {_tlabel(k): k for k in opts}
                grid = pd.DataFrame({"priority": list(range(1, 11)),
                                     "target": [_tlabel(prev_prio[i]) if i in prev_prio else _empty for i in range(1, 11)]})
                ed_p = st.data_editor(grid, key=f"wh_prio_{sel}", hide_index=True, use_container_width=True, num_rows="fixed",
                                      column_config={"priority": st.column_config.NumberColumn(_tr("col_priority"), disabled=True, width="small"),
                                                     "target": st.column_config.SelectboxColumn(_tr("col_target_mp"), options=opt_labels, width="large")},
                                      height=38 + 35 * 10)
                new_prio = {}
                dup = []
                for r in ed_p.itertuples():
                    if r.target and r.target != _empty:
                        k = label_to_key.get(r.target)
                        if k is None:
                            continue
                        if k in new_prio.values():
                            dup.append(r.target); continue
                        new_prio[int(r.priority)] = k
                _dup_state["dup"] = dup
                if dup:
                    st.error(_trf("wh_prio_dup", t=", ".join(dup)))
                if not new_prio and row["type"] == "sales":
                    st.error(_tr("wh_prio_none"))     # контроль п.3: у склада продаж должен быть хотя бы один маркетплейс/пул — сохранение отменяется

            # ── откуда пополняется: все маршруты, включая выключенные; срок и активность правятся здесь (доработка, п.6) ──
            st.markdown("##### " + _tr("wh_src_h"))
            # пороги сравнения факта с планом — из reorder_params, не константами (ТЗ 001 §5)
            _lt_par = {r["key"]: float(r["value"]) for _, r in
                       q("SELECT key, value FROM kabinet_data.reorder_params WHERE key LIKE 'lead_time%'").iterrows()}
            # закрытых накладных в ERP единицы, и подпись должна это говорить, а не оставлять пустую колонку
            _ttn = q1("SELECT count(*) AS n, count(actual_delivery_date) AS closed FROM kabinet_data.shipments_history", ())
            _ttn_all = int(_ttn["n"].iloc[0]) if not _ttn.empty else 0
            _ttn_closed = int(_ttn["closed"].iloc[0]) if not _ttn.empty else 0
            src = q(f"""
                SELECT c.id, f.name AS src_name, c.median_days, c.lead_source, c.sample_size, c.is_active,
                       lt.actual_days, lt.shipments, lt.window_days, lt.last_delivery
                FROM kabinet_data.supply_chains c
                JOIN kabinet_data.warehouses f ON f.id = c.from_warehouse_id
                LEFT JOIN kabinet_data.supply_lead_time_facts lt ON lt.route_id = c.id
                WHERE c.to_warehouse_id = {int(sel)}
                ORDER BY c.is_active DESC, c.median_days, f.name
            """)
            ed_src = None
            if src.empty:
                st.caption(_tr("wh_src_none"))
            else:
                st.caption(_tr("wh_src_hint"))
                st.caption(_trf("wh_lt_hint", w=int(_lt_par.get("lead_time_window_days", 180)),
                                t=int(_lt_par.get("lead_time_deviation_pct", 15)),
                                m=int(_lt_par.get("lead_time_min_shipments", 5))))
                src["basis"] = [_trf("basis_ttn", n=int(n)) if s_ == "ttn_planned" and pd.notna(n) else _tr("basis_expert")
                                for s_, n in zip(src["lead_source"], src["sample_size"])]
                # факт и отклонение — текстом: пустую числовую ячейку Streamlit рисует словом «None»,
                # а пусто здесь значит «поставок в окне не было», и это не ноль дней (см. AGENTS.md)
                src["fact"] = [f"{float(d):.0f} ({int(n)})" if pd.notna(d) and pd.notna(n) and int(n) > 0 else ""
                               for d, n in zip(src["actual_days"], src["shipments"])]
                src["dev"] = ["" if not (pd.notna(d) and pd.notna(pl) and float(pl) > 0)
                              else f"{(float(d) - float(pl)) / float(pl) * 100:+.0f} %"
                              for d, pl in zip(src["actual_days"], src["median_days"])]
                ed_src = st.data_editor(
                    src[["id", "src_name", "median_days", "fact", "dev", "basis", "is_active"]], key=f"wh_src_{sel}",
                    hide_index=True, use_container_width=True, num_rows="fixed",
                    disabled=["id", "src_name", "fact", "dev", "basis"],
                    column_config={"id": None, "src_name": st.column_config.TextColumn(_tr("col_src"), width="large"),
                                   "median_days": st.column_config.NumberColumn(_tr("col_lt_plan"), min_value=0, max_value=365, step=1),
                                   "fact": st.column_config.TextColumn(_tr("col_lt_fact")),
                                   "dev": st.column_config.TextColumn(_tr("col_lt_dev")),
                                   "basis": st.column_config.TextColumn(_tr("col_basis")),
                                   "is_active": st.column_config.CheckboxColumn(_tr("col_active"))})
                if not src["actual_days"].notna().any():
                    st.caption(_trf("wh_lt_nofact", n=_ttn_all, k=_ttn_closed))

            # ── страны обслуживания, Long Term, график отгрузки, внешние коды (ТЗ 001) ──
            st.markdown("##### " + _tr("wh_serve_h"))
            _is_transit = str(row["type"] or "").startswith("transit")
            # названия на языке интерфейса: в самом справочнике стран их нет, они лежат рядом (country_names)
            _lang_col = {"ru": "name_ru", "uk": "name_uk"}.get(get_lang(), "name_en")
            _countries = q(f"""SELECT c.alpha2, COALESCE(n.{_lang_col}, n.name_en, c.name) AS name
                               FROM kabinet_data.countries c
                               LEFT JOIN kabinet_data.country_names n ON n.alpha2 = c.alpha2
                               WHERE c.is_active ORDER BY 2""")
            _c_lbl = {r["alpha2"]: f'{r["name"]} ({r["alpha2"]})' for _, r in _countries.iterrows()}
            _served_now = q1("SELECT country_alpha2 FROM kabinet_data.warehouse_countries WHERE warehouse_id = %s ORDER BY 1",
                             (int(sel),))["country_alpha2"].tolist()
            if _is_transit:
                # у склада в пути страны обслуживания и Long Term по ТЗ недоступны
                st.caption(_tr("wh_serve_transit")); served_new, long_term_new = _served_now, _long_term
            else:
                st.caption(_tr("wh_serve_hint"))
                served_new = st.multiselect(_tr("wh_serve_pick"), list(_c_lbl), default=[c for c in _served_now if c in _c_lbl],
                                            format_func=lambda c: _c_lbl.get(c, c), key=f"wh_serve_{sel}",
                                            placeholder=_tr("ph_any"))
                long_term_new = st.checkbox(_tr("wh_long_term"), value=_long_term, key=f"wh_lt_{sel}",
                                            help=_tr("wh_long_term_help"))

            _DOW = _tr("wh_dow").split(",")
            sched_now = q1("""SELECT order_dow, ship_dow FROM kabinet_data.warehouse_shipping_schedule
                              WHERE warehouse_id = %s ORDER BY order_dow""", (int(sel),))
            _none_lbl = _tr("wh_sched_none_day")
            sched_map = dict(zip(sched_now["order_dow"], sched_now["ship_dow"])) if not sched_now.empty else {}
            st.markdown("##### " + _tr("wh_sched_h"))
            st.caption(_tr("wh_sched_hint"))
            ed_sched = st.data_editor(
                pd.DataFrame({"order": _DOW,
                              "ship": [_DOW[sched_map[i + 1] - 1] if (i + 1) in sched_map else _none_lbl for i in range(7)]}),
                key=f"wh_sched_{sel}", hide_index=True, use_container_width=True, num_rows="fixed",
                column_config={"order": st.column_config.TextColumn(_tr("wh_sched_order"), disabled=True, width="medium"),
                               "ship": st.column_config.SelectboxColumn(_tr("wh_sched_ship"), options=[_none_lbl] + _DOW, width="medium")},
                height=38 + 35 * 7)

            st.markdown("##### " + _tr("wh_ext_h"))
            st.caption(_tr("wh_ext_hint"))
            ext_now = q1("""SELECT id, system_name, external_code, external_name
                            FROM kabinet_data.warehouse_external_ids WHERE warehouse_id = %s ORDER BY system_name, external_code""",
                         (int(sel),))
            ed_ext = st.data_editor(
                ext_now if not ext_now.empty else pd.DataFrame(columns=["id", "system_name", "external_code", "external_name"]),
                key=f"wh_ext_{sel}", hide_index=True, use_container_width=True, num_rows="dynamic",
                column_config={"id": None,
                               "system_name": st.column_config.TextColumn(_tr("wh_ext_system"), width="medium"),
                               "external_code": st.column_config.TextColumn(_tr("wh_ext_code"), width="medium"),
                               "external_name": st.column_config.TextColumn(_tr("wh_ext_name"), width="large")})

            # ── сохранение ────────────────────────────────────────────────
            def prio_empty_stop() -> bool:
                """У склада продаж должен остаться хотя бы один маркетплейс или пул: очистку всех строк не сохраняем.
                Склад без привязок вовсе (Tienda, FBA CZ) править маршруты может — красный контроль выше остаётся."""
                if new_prio is not None and not new_prio and prev_prio and row["type"] == "sales":
                    st.error(_tr("wh_prio_none_block"))
                    return True
                return False

            # Сохранение в два шага, если правка что-то УДАЛЯЕТ (решение владельца 06.10.2026): строку внешнего
            # кода убирают корзиной в сетке, приоритет — прочерком, день графика — «без ограничения», страну —
            # крестиком, и раньше всё это стиралось первым же «Сохранить» без вопроса. Теперь удаляемое
            # перечисляется словами, и запись идёт только после «Да, удалить и сохранить».
            def _wh_build():
                """Запросы на запись и список того, что они удалят (словами)."""
                stmts, removed = [], []
                if new_prio is not None and new_prio != prev_prio and not dup:
                    for pr, k in sorted(prev_prio.items()):
                        if k not in new_prio.values():
                            removed.append(_trf("wh_rm_prio", p=pr, t=_tlabel(k)))
                    stmts.append((f"DELETE FROM {WP} WHERE warehouse_id = %s", (int(sel),)))
                    for pr, (tt, tid) in sorted(new_prio.items()):
                        stmts.append((f"INSERT INTO {WP} (warehouse_id, priority, target_type, target_id, updated_by) VALUES (%s, %s, %s, %s, 'kabinet')",
                                      (int(sel), int(pr), tt, int(tid))))
                if ed_src is not None:
                    before_src = src.set_index("id")
                    for r in ed_src.itertuples():
                        b = before_src.loc[int(r.id)]
                        sets, params, logs = [], [], []
                        if _int0(r.median_days) != _int0(b["median_days"]):
                            # срок, введённый человеком, — уже не медиана накладных: основание «вручную»
                            sets += ["median_days = %s", "lead_source = 'expert'"]; params.append(_int0(r.median_days))
                            logs.append(_ch_log(int(r.id), "median_days", b["median_days"], _int0(r.median_days)))
                        if bool(r.is_active) != bool(b["is_active"]):
                            sets.append("is_active = %s"); params.append(bool(r.is_active))
                            logs.append(_ch_log(int(r.id), "is_active", bool(b["is_active"]), bool(r.is_active)))
                        if sets:
                            stmts.append((f"UPDATE kabinet_data.supply_chains SET {', '.join(sets)}, updated_at = now() WHERE id = %s", params + [int(r.id)]))
                            stmts += logs
                # страны обслуживания: сравниваем множества, пишем разницу
                if set(served_new) != set(_served_now):
                    gone = set(_served_now) - set(served_new)
                    for c in sorted(gone):
                        removed.append(_trf("wh_rm_country", c=_c_lbl.get(c, c)))
                    if gone:
                        stmts.append(("DELETE FROM kabinet_data.warehouse_countries WHERE warehouse_id = %s AND country_alpha2 = ANY(%s)",
                                      (int(sel), list(gone))))
                    for c in set(served_new) - set(_served_now):
                        stmts.append(("INSERT INTO kabinet_data.warehouse_countries (warehouse_id, country_alpha2) VALUES (%s, %s) "
                                      "ON CONFLICT DO NOTHING", (int(sel), c)))
                if (disp_new or "").strip() != _disp:
                    _dv = (disp_new or "").strip() or None
                    stmts.append(("""INSERT INTO kabinet_data.warehouse_attributes (warehouse_id, display_name)
                                     VALUES (%s, %s)
                                     ON CONFLICT (warehouse_id) DO UPDATE SET display_name = EXCLUDED.display_name,
                                       updated_at = now(), updated_by = 'kabinet'""", (int(sel), _dv)))
                if bool(long_term_new) != bool(_long_term):
                    stmts.append(("""INSERT INTO kabinet_data.warehouse_attributes (warehouse_id, long_term_control)
                                     VALUES (%s, %s)
                                     ON CONFLICT (warehouse_id) DO UPDATE SET long_term_control = EXCLUDED.long_term_control,
                                       updated_at = now(), updated_by = 'kabinet'""", (int(sel), bool(long_term_new))))
                # график отгрузки: строка без дня отгрузки означает «ограничения нет»
                new_sched = {}
                for i, r_ in enumerate(ed_sched.itertuples(), start=1):
                    if r_.ship and r_.ship != _none_lbl and r_.ship in _DOW:
                        new_sched[i] = _DOW.index(r_.ship) + 1
                for od in sorted(set(sched_map) - set(new_sched)):
                    removed.append(_trf("wh_rm_sched", o=_DOW[od - 1], s=_DOW[sched_map[od] - 1]))
                if new_sched != sched_map:
                    stmts.append(("DELETE FROM kabinet_data.warehouse_shipping_schedule WHERE warehouse_id = %s", (int(sel),)))
                    for od, sd in sorted(new_sched.items()):
                        stmts.append(("INSERT INTO kabinet_data.warehouse_shipping_schedule (warehouse_id, order_dow, ship_dow) "
                                      "VALUES (%s, %s, %s)", (int(sel), od, sd)))
                # внешние сопоставления: строки без системы или кода не сохраняем
                _ext_before = {int(r.id): (r.system_name, r.external_code, r.external_name) for r in ext_now.itertuples()} if not ext_now.empty else {}
                _seen = set()
                for r_ in ed_ext.itertuples():
                    sys_, code_ = (str(getattr(r_, "system_name", "") or "").strip(), str(getattr(r_, "external_code", "") or "").strip())
                    name_ = str(getattr(r_, "external_name", "") or "").strip() or None
                    rid_ = getattr(r_, "id", None)
                    if not sys_ or not code_:
                        continue
                    if pd.notna(rid_) and int(rid_) in _ext_before:
                        _seen.add(int(rid_))
                        if _ext_before[int(rid_)] != (sys_, code_, name_):
                            stmts.append(("UPDATE kabinet_data.warehouse_external_ids SET system_name = %s, external_code = %s, "
                                          "external_name = %s, updated_at = now() WHERE id = %s", (sys_, code_, name_, int(rid_))))
                    else:
                        stmts.append(("INSERT INTO kabinet_data.warehouse_external_ids (warehouse_id, system_name, external_code, external_name) "
                                      "VALUES (%s, %s, %s, %s) ON CONFLICT DO NOTHING", (int(sel), sys_, code_, name_)))
                for rid_ in sorted(set(_ext_before) - _seen):
                    _s, _c, _n = (as_text(x) for x in _ext_before[rid_])
                    removed.append(_trf("wh_rm_ext", s=_s, c=_c, n=f" ({_n})" if _n else ""))
                    stmts.append(("DELETE FROM kabinet_data.warehouse_external_ids WHERE id = %s", (rid_,)))
                return stmts, removed

            def _wh_write(stmts):
                try:
                    exec_sql(stmts)
                    st.cache_data.clear()
                    st.session_state.pop(_pend, None)
                    st.success(_trf("saved", n=len(stmts)))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

            _pend = f"wh_pending_del_{sel}"
            if st.button(_tr("save"), key="save_wh_card", type="primary") and not dup_stop() and not prio_empty_stop():
                stmts, removed = _wh_build()
                if not stmts:
                    st.info(_tr("nochange"))
                elif removed:
                    st.session_state[_pend] = True    # спросим ниже; ничего не записано
                else:
                    _wh_write(stmts)
            if st.session_state.get(_pend):
                # список собирается заново на каждом прогоне: если человек вернул строку в сетку,
                # она исчезает из вопроса, а если вернул всё — вопрос снимается сам
                stmts, removed = _wh_build()
                if not removed:
                    st.session_state.pop(_pend, None)
                else:
                    st.warning(_trf("wh_rm_q", n=len(removed)) + "\n\n" + "\n".join(f"- {x}" for x in removed))
                    c1, c2 = st.columns(2)
                    if c1.button(_tr("wh_rm_yes"), key=f"wh_rm_yes_{sel}", type="primary"):
                        if not dup_stop() and not prio_empty_stop():
                            _wh_write(stmts)
                    if c2.button(_tr("wh_rm_no"), key=f"wh_rm_no_{sel}"):
                        st.session_state.pop(_pend, None)
                        st.rerun()

            # ── сводка: название, тип, активен, приоритет 1..10 (доработка 17.09, «Отображение в таблице») ──
            st.markdown("##### " + _tr("wh_sum_h"))
            # сводка не зависит от тумблера «показывать все типы»: склады продаж и всё, у чего есть привязки
            sales_rows = wh[(wh["type"] == "sales") | wh["id"].astype(int).isin(prio_by_wh.keys())]
            summary = pd.DataFrame({
                _tr("col_name"): list(sales_rows["name"]),
                _tr("col_type"): [_type_lbl(tp) for tp in sales_rows["type"]],
                _tr("col_active"): list(sales_rows["is_active"]),
            })
            for i in range(1, 11):
                summary[f"{_tr('col_priority_short')} {i}"] = [
                    (targets.get(prio_by_wh.get(int(w), {}).get(i), ("", "", set()))[1] if prio_by_wh.get(int(w), {}).get(i) else "")
                    for w in sales_rows["id"]]
            # ТЗ 001: код уникален и длиной 3–30. В Кабинете он не правится (приезжает из ERP),
            # поэтому проверяем загруженное и показываем нарушения — иначе правило существует только на бумаге
            _codes = wh[wh["code"].notna() & (wh["code"].astype(str).str.strip() != "")]
            _bad_len = [(r["name"], str(r["code"]).strip()) for _, r in _codes.iterrows()
                        if not 3 <= len(str(r["code"]).strip()) <= 30]
            _dups = {}
            for _, r in _codes.iterrows():
                _dups.setdefault(str(r["code"]).strip().lower(), []).append(r["name"])
            _dup_list = [(c, names) for c, names in _dups.items() if len(names) > 1]
            for _name, _code in _bad_len[:5]:
                st.warning(_trf("wh_code_len", c=_code, n=len(_code)))
            for _code, _names in _dup_list[:5]:
                st.warning(_trf("wh_code_dup", c=_code, w=", ".join(_names)))

            missing = [n for n, tp, w in zip(sales_rows["name"], sales_rows["type"], sales_rows["id"]) if tp == "sales" and not prio_by_wh.get(int(w))]
            if missing:
                st.warning(_trf("wh_sales_without_mp", n=len(missing), names=", ".join(missing[:8]) + ("…" if len(missing) > 8 else "")))
            st.dataframe(summary, use_container_width=True, hide_index=True,
                         column_config={_tr("col_active"): st.column_config.CheckboxColumn(), _tr("col_name"): st.column_config.TextColumn(width="large", pinned=True)},
                         height=min(600, 38 + 35 * len(summary)))
        # ── таблица целиком, для тех, кто правит пачкой ───────────────────
        with st.expander(_tr("wh_all")):
            wh_tbl = wh.copy()
            for _c in ("marketplace", "country", "code", "note"):   # пустое поле рисовалось словом «None»
                wh_tbl[_c] = wh_tbl[_c].fillna("")
            ed = st.data_editor(
                wh_tbl, key="ed_wh", use_container_width=True, height=520,
                hide_index=True, num_rows="fixed",
                # список disabled перекрывает column_config[...].disabled: колонка, которой нет
                # в списке, остаётся редактируемой, даже если в конфиге стоит disabled=True
                disabled=["id", "name", "code", "canonical_id", "shipping_priority"],
                column_config={
                    "id": st.column_config.NumberColumn(_tr("col_id"), width="small"),
                    "name": st.column_config.TextColumn(_tr("col_name"), width="large"),
                    "code": st.column_config.TextColumn(_tr("col_code"), width="small"),
                    # варианты — ровно те, что пропускает CHECK на warehouses.type (view добавлен владельцем 21.09.2026)
                    "type": st.column_config.SelectboxColumn(
                        _tr("col_type"), help=_tr("col_type_help"),
                        options=["sales", "storage", "transit_domestic", "transit_inter", "manufacturer", "fba", "view"]),
                    "marketplace": st.column_config.TextColumn(_tr("col_mp"), width="small"),
                    "country": st.column_config.TextColumn(_tr("col_country"), width="small"),
                    # приоритет переехал в warehouse_priorities: правка этого числа больше ни на что
                    # не влияет, а max_value=99 принимал 11 и «сохранял» его молча
                    "shipping_priority": st.column_config.NumberColumn(
                        _tr("col_ship_prio"), help=_tr("col_ship_prio_help"), disabled=True),
                    "is_active": st.column_config.CheckboxColumn(_tr("col_active")),
                    "canonical_id": st.column_config.NumberColumn(_tr("col_canon"), width="small"),
                    "note": st.column_config.TextColumn(_tr("col_note"), width="large"),
                },
            )
            if st.button(_tr("save"), key="save_wh", type="primary"):
                save_block(wh_tbl, ed, "kabinet_data.warehouses", "id",
                           ["type", "marketplace", "country", "is_active", "note"])

# ------------------------------------------------------------- подпитка ---
# Плечи, по которым Stock Loader считает срок поставки в автозаказе (`_route_days`, константы WH_* в ноутбуке):
# Piasecznie → Мадрид, Мадрид → FBA ES, Тернополь → Piasecznie. Выключи такую связь — автозаказ возьмёт
# оценку поставщика из reorder_params, и человек должен узнать это ДО нажатия, а не из лога загрузчика.
AUTOORDER_LEGS = {(32, 43): "PL", (43, 86): "Madrid", (37, 32): "UA"}
SCLOG = ("INSERT INTO kabinet_data.supply_chain_change_log (chain_id, field, old_value, new_value, actor) "
         "VALUES (%s, %s, %s, %s, %s)")
CH_ROUTES = ["internal", "last_mile", "fba_inbound"]


def _ch_log(cid, field, old, new):
    o = None if old is None or (not isinstance(old, str) and pd.isna(old)) else str(old)
    n = None if new is None or (not isinstance(new, str) and pd.isna(new)) else str(new)
    return (SCLOG, (int(cid), field, o, n, _actor()))


def _ch_load() -> pd.DataFrame:
    # Имя склада на экран — `COALESCE(display_name, name)`; сопоставление и ключи — по id (доработка 28.09)
    return q("""
        SELECT c.id, c.from_warehouse_id AS from_id, c.to_warehouse_id AS to_id,
               COALESCE(fa.display_name, f.name)  AS from_name,
               COALESCE(ta.display_name, tw.name) AS to_name,
               c.route_type, c.median_days, c.lead_source, c.sample_size, c.is_active, c.note,
               lt.actual_days, lt.shipments, lt.last_delivery
        FROM kabinet_data.supply_chains c
        LEFT JOIN kabinet_data.warehouses f  ON f.id  = c.from_warehouse_id
        LEFT JOIN kabinet_data.warehouses tw ON tw.id = c.to_warehouse_id
        LEFT JOIN kabinet_data.warehouse_attributes fa ON fa.warehouse_id = f.id
        LEFT JOIN kabinet_data.warehouse_attributes ta ON ta.warehouse_id = tw.id
        LEFT JOIN kabinet_data.supply_lead_time_facts lt ON lt.route_id = c.id
        ORDER BY 5, 4
    """)


def _ch_fact(r) -> str:
    """Факт — текстом: пусто значит «закрытых поставок в окне не было», а не ноль дней."""
    if pd.notna(r["actual_days"]) and pd.notna(r["shipments"]) and int(r["shipments"]) > 0:
        return f"{float(r['actual_days']):.0f} ({int(r['shipments'])})"
    return ""


def _ch_dev(r) -> str:
    if pd.notna(r["actual_days"]) and pd.notna(r["median_days"]) and float(r["median_days"]) > 0:
        return f"{(float(r['actual_days']) - float(r['median_days'])) / float(r['median_days']) * 100:+.0f} %"
    return ""


def _ch_basis(r) -> str:
    if r["lead_source"] == "ttn_planned" and pd.notna(r["sample_size"]):
        return _trf("basis_ttn", n=int(r["sample_size"]))
    return _tr("basis_expert")


def _section_ch():
    """Подпитка по общему приёму справочников (07.10.2026): инструкция → список с поиском и фильтрами → карточка
    по клику → форма добавления. Плановый срок (`median_days`) правит только человек (ТЗ 001 §5) — здесь или в
    карточке склада-получателя; Кабинет его сам не меняет ни при каком отклонении факта. Ни один загрузчик в
    `supply_chains` не пишет: все связи ведутся здесь."""
    dict_kit.instruction(_tr("ch_about"), _tr("ch_about_cap"))
    _created = st.session_state.pop("ch_created_msg", None)
    if _created:
        st.success(_created)
    ch = _ch_load()
    route_lbl = {c: _tr("ch_route_" + c) for c in CH_ROUTES}

    f1, f2, f3 = st.columns([2, 1, 1])
    needle = dict_kit.search_input(_tr("ch_search"), "ch_search", _tr, _tr("ch_search_ph"), where=f1).lower()
    route_sel = f2.selectbox(_tr("col_route"), ["all"] + CH_ROUTES, key="ch_route_f",
                             format_func=lambda x: _tr("ctry_state_all") if x == "all" else route_lbl[x])
    state_sel = f3.selectbox(_tr("sku_state_f"), ["active", "archived", "all"], key="ch_state_f",
                             format_func=lambda x: _tr(f"sku_state_{x}"))
    view = ch
    if needle:
        view = view[view["from_name"].fillna("").str.lower().str.contains(needle, regex=False)
                    | view["to_name"].fillna("").str.lower().str.contains(needle, regex=False)]
    if route_sel != "all":
        view = view[view["route_type"] == route_sel]
    if state_sel != "all":
        view = view[view["is_active"].astype(bool) == (state_sel == "active")]
    st.caption(_trf("mp_summary", shown=len(view), total=len(ch), arch=int((~ch["is_active"].astype(bool)).sum())))

    lst = pd.DataFrame({
        "from": view["from_name"].fillna("—"),
        "to": view["to_name"].fillna("—"),
        "route": [route_lbl.get(x, as_text(x)) for x in view["route_type"]],
        "plan": [("" if pd.isna(x) else f"{int(x)}") for x in view["median_days"]],
        "fact": [_ch_fact(r) for _, r in view.iterrows()],
        "dev": [_ch_dev(r) for _, r in view.iterrows()],
        "basis": [_ch_basis(r) for _, r in view.iterrows()],
        "state": [_tr("sku_state_active") if bool(a) else _tr("sku_state_archived") for a in view["is_active"]],
        "note": [as_text(x) for x in view["note"]],
    })
    options = [int(i) for i in view["id"]]
    picked = dict_kit.table_pick(lst, options, "ch_list", (needle, route_sel, state_sel), column_config={
        "from": st.column_config.TextColumn(_tr("ch_from"), width="medium"),
        "to": st.column_config.TextColumn(_tr("ch_to"), width="medium"),
        "route": st.column_config.TextColumn(_tr("col_route"), width=130),
        "plan": st.column_config.TextColumn(_tr("col_lt_plan"), width=90, help=_tr("ch_plan_help")),
        "fact": st.column_config.TextColumn(_tr("col_lt_fact"), width=90, help=_tr("ch_fact_help")),
        "dev": st.column_config.TextColumn(_tr("col_lt_dev"), width=90),
        "basis": st.column_config.TextColumn(_tr("col_basis"), width=120, help=_tr("ch_basis_help")),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=90),
        "note": st.column_config.TextColumn(_tr("col_note"), width="large"),
    })
    st.caption(_tr("ch_list_empty") if lst.empty else _tr("ch_list_hint"))
    if options:
        labels = {int(r.id): f"{as_text(r.from_name, '—')} → {as_text(r.to_name, '—')}"
                  + ("" if bool(r.is_active) else f" · {_tr('wh_inactive')}") for r in view.itertuples()}
        st.markdown("#### " + _tr("ch_card_h"))
        sel = dict_kit.card_pick(_tr("ch_pick"), options, labels, "ch_card", picked)
        _ch_card(ch.set_index("id").loc[sel], int(sel), route_lbl)

    _ch_add_form(ch, route_lbl)


def _ch_card(row, sel: int, route_lbl: dict):
    can_edit = auth.can("dict.edit")
    leg = AUTOORDER_LEGS.get((int(row["from_id"]), int(row["to_id"])))
    with st.container(border=True):
        st.markdown(f"**{as_text(row['from_name'], '—')} → {as_text(row['to_name'], '—')}**"
                    + ("" if bool(row["is_active"]) else f"  \n{_tr('ch_is_archived')}"))
        st.caption(f"ID {sel} · " + _tr("ch_ends_ro"))
        if leg:
            st.caption(_trf("ch_leg_note", leg=_tr(f"ch_leg_{leg}")))
        c1, c2 = st.columns(2)
        cur_route = row["route_type"] if row["route_type"] in CH_ROUTES else CH_ROUTES[0]
        new_route = c1.selectbox(_tr("col_route"), CH_ROUTES, index=CH_ROUTES.index(cur_route),
                                 format_func=lambda x: route_lbl[x], key=f"ch_route_{sel}",
                                 help=_tr("ch_route_help"), disabled=not can_edit)
        new_days = c2.number_input(_tr("col_lt_plan"), min_value=0, max_value=365, step=1,
                                   value=_int0(row["median_days"]), key=f"ch_days_{sel}",
                                   help=_tr("ch_plan_help"), disabled=not can_edit)
        new_note = st.text_input(_tr("col_note"), value=as_text(row["note"]), key=f"ch_note_{sel}",
                                 help=_tr("ch_note_help"), disabled=not can_edit)
        fact = _ch_fact(row)
        if fact:
            st.caption(_trf("ch_fact_line", fact=fact, dev=_ch_dev(row) or "—",
                            last=pd.Timestamp(row["last_delivery"]).strftime("%d.%m.%Y")
                            if pd.notna(row["last_delivery"]) else "—"))
        else:
            st.caption(_tr("ch_fact_none"))
        st.caption(_tr("col_basis") + ": " + _ch_basis(row))
        if st.button(_tr("save"), key=f"ch_save_{sel}", type="primary", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            stmts, sets, params = [], [], []
            if new_route != row["route_type"]:
                sets.append("route_type = %s"); params.append(new_route)
                stmts.append(_ch_log(sel, "route_type", row["route_type"], new_route))
            if int(new_days) != _int0(row["median_days"]):
                # срок, введённый человеком, — уже не медиана накладных: основание меняется на «вручную»
                sets += ["median_days = %s", "lead_source = 'expert'"]; params.append(int(new_days))
                stmts.append(_ch_log(sel, "median_days", row["median_days"], int(new_days)))
            if (new_note or "").strip() != as_text(row["note"]):
                sets.append("note = %s"); params.append((new_note or "").strip() or None)
                stmts.append(_ch_log(sel, "note", row["note"], (new_note or "").strip() or None))
            if not sets:
                st.info(_tr("nochange"))
            else:
                stmts.insert(0, (f"UPDATE kabinet_data.supply_chains SET {', '.join(sets)}, updated_at = now() "
                                 f"WHERE id = %s", tuple(params) + (sel,)))
                try:
                    exec_sql(stmts); st.cache_data.clear(); st.success(_tr("ch_saved")); st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

    if can_edit:
        _ch_archive(row, sel, leg)

    with st.expander(_tr("ctry_log")):
        lg = q1("""SELECT ts, field, old_value, new_value, actor FROM kabinet_data.supply_chain_change_log
                   WHERE chain_id = %s ORDER BY ts DESC LIMIT 200""", (sel,))
        if lg.empty:
            st.caption(_tr("ch_log_empty"))
        else:
            lg["ts"] = pd.to_datetime(lg["ts"]).dt.strftime("%d.%m.%Y %H:%M")
            lg["field"] = [_tr(f"ch_logf_{f}") if f in ("created", "median_days", "route_type", "note", "is_active")
                           else f for f in lg["field"]]
            lg.columns = [_tr("mp_log_when"), _tr("mp_log_field"), _tr("mp_log_old"), _tr("mp_log_new"), _tr("mp_log_who")]
            st.dataframe(lg, hide_index=True, use_container_width=True, height=min(300, 38 + 35 * len(lg)))


def _ch_archive(row, sel: int, leg):
    """В архив / вернуть / удалить. Удалить можно только связь, уже убранную в архив и без фактических поставок:
    по связи с поставками считался факт срока, и история сравнения план — факт без неё стала бы необъяснимой."""
    box = st.container(border=True)
    box.markdown("**" + _tr("mp_act_h") + "**")
    flag = f"ch_arch_ask_{sel}"
    if not bool(row["is_active"]):
        box.caption(_tr("ch_restore_note"))
        if box.button(_tr("mp_act_restore"), key=f"ch_rest_{sel}"):
            _ch_set_active(sel, True)
        has_fact = pd.notna(row["shipments"]) and int(row["shipments"]) > 0
        if has_fact:
            box.caption(_tr("ch_del_blocked"))
        else:
            with box:
                if confirm_delete(f"ch_{sel}", f"{as_text(row['from_name'])} → {as_text(row['to_name'])}"):
                    try:
                        exec_sql([("DELETE FROM kabinet_data.supply_chains WHERE id = %s AND NOT is_active", (sel,)),
                                  _ch_log(sel, "deleted", f"{row['from_name']} → {row['to_name']}", None)])
                        st.cache_data.clear()
                        st.session_state.pop("ch_card", None)
                        st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))
        return
    if not st.session_state.get(flag):
        box.caption(_tr("ch_off_note"))
        if box.button(_tr("mp_act_archive"), key=f"ch_arch_{sel}"):
            st.session_state[flag] = True
            st.rerun()
        return
    if leg:
        box.warning(_trf("ch_leg_warn", leg=_tr(f"ch_leg_{leg}")))
    elif row["route_type"] == "fba_inbound":
        box.warning(_tr("ch_fba_warn"))
    else:
        box.info(_tr("ch_off_plain"))
    c1, c2 = box.columns(2)
    if c1.button(_tr("mp_act_archive_yes"), key=f"ch_arch_yes_{sel}", type="primary"):
        st.session_state.pop(flag, None)
        _ch_set_active(sel, False)
    if c2.button(_tr("del_confirm_no"), key=f"ch_arch_no_{sel}"):
        st.session_state.pop(flag, None)
        st.rerun()


def _ch_set_active(sel: int, active: bool):
    try:
        exec_sql([("UPDATE kabinet_data.supply_chains SET is_active = %s, updated_at = now() WHERE id = %s", (active, sel)),
                  _ch_log(sel, "is_active", str(not active), str(active))])
        st.cache_data.clear()
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _ch_add_form(ch: pd.DataFrame, route_lbl: dict):
    """Новая связь: источник, получатель, тип маршрута и плановый срок обязательны; пара «источник → получатель»
    уникальна среди ВСЕХ связей, и найденная в архиве предлагается к возврату, а не дублируется."""
    st.markdown("#### " + _tr("ch_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("ch_ro_add"))
        return
    st.caption(_tr("ch_add_note"))
    wh = q("""
        SELECT w.id, COALESCE(a.display_name, w.name) AS name, COALESCE(w.code, '') AS code
        FROM kabinet_data.warehouses w
        LEFT JOIN kabinet_data.warehouse_attributes a ON a.warehouse_id = w.id
        WHERE w.is_active IS NOT FALSE
        ORDER BY 2
    """)
    lbl = {int(r.id): (f"{r['name']} ({r.code})" if r.code else r["name"]) for _, r in wh.iterrows()}
    ids = [None] + list(lbl)
    fmt = lambda i: _tr("ch_pick_wh") if i is None else lbl[i]
    c1, c2 = st.columns(2)
    src = c1.selectbox(_tr("ch_from") + " *", ids, format_func=fmt, key="ch_add_src", help=_tr("ch_from_help"))
    rec = c2.selectbox(_tr("ch_to") + " *", ids, format_func=fmt, key="ch_add_rec", help=_tr("ch_to_help"))
    c3, c4, c5 = st.columns([1, 1, 2])
    rtype = c3.selectbox(_tr("col_route") + " *", CH_ROUTES, format_func=lambda x: route_lbl[x], key="ch_add_type",
                         help=_tr("ch_route_help"))
    days = c4.number_input(_tr("col_lt_plan") + " *", min_value=0, max_value=365, step=1, value=None,
                           placeholder="14", key="ch_add_days", help=_tr("ch_plan_help"))
    note = c5.text_input(_tr("col_note"), key="ch_add_note", help=_tr("ch_note_help"))
    if not st.button(_tr("ch_create"), key="ch_add_go", type="primary"):
        return
    errs = []
    if src is None or rec is None:
        errs.append(_tr("ch_need_both"))
    elif src == rec:
        errs.append(_tr("ch_same"))
    if days is None:
        errs.append(_tr("ch_need_days"))
    if not errs:
        ex = q_now("SELECT id, is_active FROM kabinet_data.supply_chains WHERE from_warehouse_id = %s "
                   "AND to_warehouse_id = %s LIMIT 1", (int(src), int(rec)))
        if not ex.empty:
            errs.append(_tr("ch_exists") if bool(ex["is_active"].iloc[0]) else _tr("ch_exists_archived"))
    if errs:
        for e in errs:
            st.error(e)
        return
    try:
        exec_sql([("""
            WITH c AS (INSERT INTO kabinet_data.supply_chains
                           (from_warehouse_id, to_warehouse_id, route_type, median_days, lead_source, is_active, note)
                       VALUES (%s, %s, %s, %s, 'expert', TRUE, %s) RETURNING id)
            INSERT INTO kabinet_data.supply_chain_change_log (chain_id, field, old_value, new_value, actor)
            SELECT id, 'created', NULL, %s, %s FROM c
        """, (int(src), int(rec), rtype, int(days), (note or "").strip() or None,
              f"{lbl[src]} → {lbl[rec]} · {int(days)}", _actor()))])
        st.cache_data.clear()
        new = q_now("SELECT id FROM kabinet_data.supply_chains WHERE from_warehouse_id = %s AND to_warehouse_id = %s",
                    (int(src), int(rec)))
        if not new.empty:
            dict_kit.card_focus("ch_card", int(new["id"].iloc[0]))
        for k in ("ch_add_src", "ch_add_rec", "ch_add_days", "ch_add_note"):
            st.session_state.pop(k, None)
        st.session_state["ch_created_msg"] = _trf("ch_created_ok", name=f"{lbl[src]} → {lbl[rec]}")
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))

# -------------------------------------------------------- маркетплейсы ---
def _curr_label(code: str, curr: pd.DataFrame) -> str:
    """Валюта на экране. Названия в `currencies` пришли из ISO 4217 и все английские
    («Euro», «Pound Sterling»). Для ходовых валют показываем подпись на языке интерфейса,
    для остальных — код: «EUR — Euro» посреди русского экрана читается как недоделка,
    а переводить все 178 кодов ради трёх используемых незачем."""
    own = _tr("curr_" + code)
    if own and not own.startswith("curr_"):
        return f"{code} — {own}"
    return code


def _mp_filters_view(mps: pd.DataFrame, plats: pd.DataFrame, countries: pd.DataFrame):
    """Поиск и фильтры списка маркетплейсов. Пустой выбор — «все» (как во всех фильтрах Кабинета)."""
    f1, f2, f3, f4 = st.columns([1.6, 1.2, 1.2, 1])
    search = dict_kit.search_input(_tr("mp_search"), "mp_search", _tr, _tr("mp_search_ph"), where=f1)
    # в фильтре — только площадки, у которых есть маркетплейсы: пустой вариант (Wallapop) отсеивал бы всё
    plat_sel = f2.multiselect(_tr("mp_platform"), sorted(set(mps["platform_short"])), placeholder=_tr("ph_any"),
                              key="mp_plat_f",
                              format_func=lambda sh: f"{sh} — {plats.set_index('short_name').loc[sh, 'full_name']}")
    cnames = countries.set_index("alpha2")["name"].to_dict()
    ctry_sel = f3.multiselect(_tr("mp_country"), sorted(set(mps["country_alpha2"])), placeholder=_tr("ph_any"),
                              key="mp_ctry_f", format_func=lambda a: f"{cnames.get(a, a)} ({a})")
    state_sel = f4.selectbox(_tr("sku_state_f"), ["active", "archived", "all"], key="mp_state_f",
                             format_func=lambda x: _tr(f"sku_state_{x}"))
    view = mps.copy()
    if search:
        view = view[view["code"].str.contains(search, case=False, na=False, regex=False)
                    | view["name"].fillna("").str.contains(search, case=False, na=False, regex=False)]
    if plat_sel:
        view = view[view["platform_short"].isin(plat_sel)]
    if ctry_sel:
        view = view[view["country_alpha2"].isin(ctry_sel)]
    if state_sel != "all":
        view = view[view["is_active"].astype(bool) == (state_sel == "active")]
    return view, (search, tuple(plat_sel), tuple(ctry_sel), state_sel)


def _section_mp():
    """Маркетплейсы по общему приёму справочников (06.10.2026): инструкция → список с поиском и
    фильтрами → карточка выбранной строки → форма создания. Правила — ТЗ 003 без изменений:
    код производный, площадка и страна меняются только пока нет матрицы и прогнозов, валюта из
    перечня ISO 4217, внешние коды парой, ссылка только https. Физического удаления нет (§6) —
    только архив и возврат из архива (решение владельца 06.10.2026)."""
    dict_kit.instruction(_tr("mp_about"), _tr("mp_hint"))
    _created = st.session_state.pop("mp_created", None)
    if _created:
        st.success(_trf("mp_created_ok", code=_created))
    mps = q("""
        SELECT m.id, m.code, m.name, m.platform_short, m.country_alpha2, m.currency, m.is_active,
               m.legacy_code, m.amazon_id,
               a.external_system, a.external_id, a.website_url,
               (SELECT count(*) FROM kabinet_data.assortment_admissions ad
                 WHERE ad.level = 'marketplace' AND ad.marketplace_id = m.id AND ad.removed_on IS NULL) AS n_adm,
               (SELECT string_agg(p.name, ', ' ORDER BY p.name) FROM kabinet_data.pool_members pm
                 JOIN kabinet_data.pools p ON p.id = pm.pool_id
                 WHERE pm.marketplace_id = m.id
                   AND pm.valid_from <= CURRENT_DATE AND (pm.valid_to IS NULL OR pm.valid_to > CURRENT_DATE)) AS pools,
               (SELECT count(DISTINCT f.sku) FROM kabinet_data.forecast_register f
                 WHERE f.object_type = 'marketplace' AND f.object_id = m.id AND f.is_current) AS n_fc
        FROM kabinet_data.marketplaces_new m
        LEFT JOIN kabinet_data.marketplace_attributes a ON a.marketplace_id = m.id
        ORDER BY m.code
    """)
    mps = _mp_with_data_status(mps)
    plats = _plat_attrs()
    _lang_col = {"ru": "name_ru", "uk": "name_uk"}.get(get_lang(), "name_en")
    countries = q(f"""SELECT c.alpha2, COALESCE(n.{_lang_col}, n.name_en, c.name) AS name, c.is_active
                      FROM kabinet_data.countries c
                      LEFT JOIN kabinet_data.country_names n ON n.alpha2 = c.alpha2
                      ORDER BY 2""")
    curr = q("SELECT code, name FROM kabinet_data.currencies WHERE is_active ORDER BY code")
    if mps.empty:
        st.info(_tr("no_data"))
        _mp_add_form(mps, plats, countries, curr)
        return

    _bad = mps[mps["data_status"].isin(["no_config", "no_data"])]
    if not _bad.empty:
        st.warning(_trf("mp_nodata_banner", n=len(_bad), codes=", ".join(_bad["code"])) + " "
                   + _tr("mp_nodata_text"))
    view, fsig = _mp_filters_view(mps, plats, countries)
    st.caption(_trf("mp_summary", shown=len(view), total=len(mps),
                    arch=int((~mps["is_active"].astype(bool)).sum())))
    cnames = countries.set_index("alpha2")["name"].to_dict()
    pnames = plats.set_index("short_name")["full_name"].to_dict()
    lst = pd.DataFrame({
        "code": view["code"],
        "name": view["name"].fillna(""),
        "platform": [f"{p} — {pnames.get(p, '')}" for p in view["platform_short"]],
        "country": [f"{cnames.get(a, a)} ({a})" for a in view["country_alpha2"]],
        "currency": view["currency"],
        "state": [_tr("sku_state_active") if bool(a) else _tr("sku_state_archived") for a in view["is_active"]],
        "data": [_mp_data_label(r) for _, r in view.iterrows()],
        "used": [_mp_used_text(r) for _, r in view.iterrows()],
    })
    options = [int(i) for i in view["id"]]
    picked = dict_kit.table_pick(lst, options, "mp_list", fsig, column_config={
        "code": st.column_config.TextColumn(_tr("mp_col_code"), width=90),
        "name": st.column_config.TextColumn(_tr("col_name"), width="medium"),
        "platform": st.column_config.TextColumn(_tr("mp_platform"), width="medium"),
        "country": st.column_config.TextColumn(_tr("mp_country"), width="medium"),
        "currency": st.column_config.TextColumn(_tr("mp_currency"), width=80),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=90),
        "data": st.column_config.TextColumn(_tr("mp_col_data"), width="medium", help=_tr("mp_col_data_help")),
        "used": st.column_config.TextColumn(_tr("mp_col_used"), width="large", help=_tr("mp_col_used_help")),
    })
    st.caption(_tr("mp_list_empty") if lst.empty else _tr("mp_list_hint"))
    if options:
        labels = {int(r.id): f"{r.code} — {r['name']}" + ("" if r.is_active else f" · {_tr('wh_inactive')}")
                  for _, r in view.iterrows()}
        st.markdown("#### " + _tr("mp_card_h"))
        sel = dict_kit.card_pick(_tr("mp_pick"), options, labels, "mp_card", picked)
        _mp_card(mps.set_index("id").loc[sel], int(sel), plats, countries, curr)

    _mp_add_form(mps, plats, countries, curr)


def _mp_with_data_status(mps: pd.DataFrame) -> pd.DataFrame:
    """Статус загрузки данных из `v_marketplace_data_status` — того же вью, что читает сторож: правило
    «данные не загружаются» живёт в одном месте (sql/marketplace_data_status_2026-10-06.sql). Вью нет или
    оно не прочиталось — колонка пустая, а не «всё в порядке»."""
    try:
        ds = q("""SELECT marketplace_id AS id, status AS data_status, config_missing, last_data_at, window_days,
                         trial_until
                  FROM kabinet_data.v_marketplace_data_status""")
        return mps.merge(ds, on="id", how="left")
    except Exception:
        out = mps.copy()
        out["data_status"], out["config_missing"], out["last_data_at"], out["window_days"] = None, None, None, None
        out["trial_until"] = None
        return out


def _mp_data_label(r) -> str:
    """Подпись колонки «Загрузка данных». 'trial' — пробный период без единого заказа: данных по заказам и не должно
    быть, поэтому это не тревога, а пометка с датой окончания (07.10.2026, ManoMano Pro)."""
    st_ = r.get("data_status")
    if st_ == "trial":
        tu = r.get("trial_until")
        return _trf("mp_data_trial", d=pd.to_datetime(tu).strftime("%d.%m.%Y")) if not pd.isna(tu) else _tr("mp_trial_short")
    return _tr("mp_data_" + st_) if st_ in ("no_config", "no_data", "ok") else ""


def _mp_nodata_reason(row) -> str:
    """Почему помечен: каких настроек нет, или когда пришли последние данные."""
    if row["data_status"] == "no_config":
        miss = row["config_missing"] if isinstance(row["config_missing"], (list, tuple)) else []
        return _trf("mp_nodata_cfg", what=", ".join(_tr("mp_cfg_" + m) for m in miss) or "—")
    last = row["last_data_at"]
    if last is None or (not isinstance(last, (list, tuple)) and pd.isna(last)):
        return _tr("mp_nodata_never")
    return _trf("mp_nodata_since", d=pd.to_datetime(last).strftime("%d.%m.%Y"), n=int(row["window_days"] or 14))


def _mp_used_text(r) -> str:
    """«Где используется» — действующие связи словами, чтобы по списку было видно, что маркетплейс живой."""
    parts = []
    if int(r["n_adm"] or 0):
        parts.append(_trf("mp_used_adm", n=int(r["n_adm"])))
    if as_text(r["pools"]):
        parts.append(_trf("mp_used_pool", p=as_text(r["pools"])))
    if int(r["n_fc"] or 0):
        parts.append(_trf("mp_used_fc", n=int(r["n_fc"])))
    return " · ".join(parts) if parts else _tr("mp_used_none")


def _mp_card(row, sel: int, plats, countries, curr):
    """Карточка маркетплейса. Логика сохранения — прежняя (ТЗ 003 §4–§5); признак активности
    вынесен в отдельные действия «В архив» / «Вернуть из архива» (§6–§7)."""
    can_edit = auth.can("dict.edit")
    act_countries = countries[countries["is_active"].astype(bool)]
    blockers = _mp_blockers(sel)
    box = st.container(border=True)
    with box:
        st.markdown(f"**{row['code']} · {row['name']}**" + ("" if bool(row["is_active"])
                                                              else f"  \n{_tr('mp_is_archived')}"))
        st.caption(f"ID {sel}")
        if row["data_status"] in ("no_config", "no_data"):
            st.warning("**" + _tr("mp_nodata_text") + "**  \n" + _mp_nodata_reason(row))
        elif row.get("data_status") == "trial":
            st.info(_mp_data_label(row) + " — " + _tr("mp_trial_info"))
        if blockers:
            st.caption(_tr("mp_deps_head") + " " + "; ".join(blockers))
        else:
            st.caption(_tr("mp_free"))

        c1, c2 = st.columns([1, 2])
        c1.text_input(_tr("mp_code_ro"), value=row["code"], disabled=True, key=f"mc_{sel}",
                      help=_tr("mp_code_hint"))
        new_name = c2.text_input(_tr("col_name"), value=row["name"] or "", key=f"mn_{sel}",
                                 help=_tr("mp_name_help"))

        p1, p2, p3 = st.columns(3)
        # площадку и страну меняем только при пустых матрице и прогнозах (ТЗ §5) — иначе поля видны,
        # но заблокированы, и рядом написано, что именно мешает
        plat_opts = list(plats["short_name"])
        new_plat = p1.selectbox(_tr("mp_platform"), plat_opts, index=plat_opts.index(row["platform_short"]),
                                key=f"mp_{sel}", disabled=bool(blockers),
                                format_func=lambda sh: f"{sh} — {plats.set_index('short_name').loc[sh, 'full_name']}")
        ctry_opts = list(act_countries["alpha2"])
        if row["country_alpha2"] not in ctry_opts:
            ctry_opts = [row["country_alpha2"]] + ctry_opts
        cn = countries.set_index("alpha2")["name"].to_dict()
        new_ctry = p2.selectbox(_tr("mp_country"), ctry_opts, index=ctry_opts.index(row["country_alpha2"]),
                                key=f"mcy_{sel}", disabled=bool(blockers),
                                format_func=lambda a: f"{cn.get(a, a)} ({a})")
        cur_opts = list(curr["code"])
        _cu = cur_opts.index(row["currency"]) if row["currency"] in cur_opts else 0
        new_curr = p3.selectbox(_tr("mp_currency"), cur_opts, index=_cu, key=f"mcu_{sel}",
                                help=_tr("mp_currency_help"),
                                format_func=lambda c_: _curr_label(c_, curr))
        if blockers:
            # рядом с заблокированным полем говорим не только «нельзя», но и что делать вместо этого:
            # отказ без выхода читается как поломка экрана
            st.caption(_trf("mp_locked", what=_tr("mp_locked_what_platform"), what2=_tr("mp_locked_for_platform")))
            st.info(_tr("mp_locked_advice"))

        e1, e2, e3 = st.columns([1, 1, 2])
        new_esys = e1.text_input(_tr("mp_ext_sys"), value=row["external_system"] or "", key=f"mes_{sel}")
        new_eid = e2.text_input(_tr("mp_ext_id"), value=row["external_id"] or "", key=f"mei_{sel}")
        new_site = e3.text_input(_tr("mp_site"), value=row["website_url"] or "", key=f"mw_{sel}",
                                 help=_tr("mp_site_help"))
        st.caption(_tr("mp_ext_hint"))

        if st.button(_tr("save"), key=f"mp_save_{sel}", type="primary", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            errs = _mp_check(sel, row, new_name, new_plat, new_ctry, new_esys, new_eid, new_site,
                             plats, blockers)
            if errs:
                for e in errs:
                    st.error(e)
            else:
                _mp_save(sel, row, new_name, new_plat, new_ctry, new_curr, new_esys, new_eid, new_site)

    _mp_trial(row, sel, can_edit)
    if can_edit:
        _mp_archive(row, sel)

    with st.expander(_tr("mp_log")):
        lg = q1("""SELECT changed_at, field, old_value, new_value, actor
                   FROM kabinet_data.marketplace_change_log
                   WHERE object_type = 'marketplace' AND object_id = %s
                   ORDER BY changed_at DESC LIMIT 200""", (sel,))
        if lg.empty:
            st.caption(_tr("mp_log_empty"))
        else:
            lg["changed_at"] = pd.to_datetime(lg["changed_at"]).dt.strftime("%d.%m.%Y %H:%M")
            lg.columns = [_tr("mp_log_when"), _tr("mp_log_field"), _tr("mp_log_old"),
                          _tr("mp_log_new"), _tr("mp_log_who")]
            st.dataframe(lg, hide_index=True, use_container_width=True,
                         height=min(320, 38 + 35 * len(lg)))


def _mp_trial(row, sel: int, can_edit: bool):
    """Пробный период маркетплейса (07.10.2026): дата окончания и пояснение в marketplace_attributes. Пока период идёт
    и заказов не было, вью v_marketplace_data_status даёт статус 'trial', и сторож не заводит «нет данных»."""
    cur_tu = q1("SELECT trial_until, trial_note FROM kabinet_data.marketplace_attributes WHERE marketplace_id = %s",
                (sel,))
    tu = cur_tu["trial_until"].iloc[0] if not cur_tu.empty else None
    tu = None if tu is None or pd.isna(tu) else pd.to_datetime(tu).date()
    note = as_text(cur_tu["trial_note"].iloc[0]) if not cur_tu.empty else ""
    with st.container(border=True):
        st.markdown("**" + _tr("mp_trial_h") + "**")
        st.caption(_tr("mp_trial_hint"))
        on = st.checkbox(_tr("mp_trial_on"), value=tu is not None, key=f"mtr_on_{sel}", disabled=not can_edit)
        t1, t2 = st.columns([1, 2])
        new_tu = t1.date_input(_tr("mp_trial_until"), value=tu or (date.today() + timedelta(days=30)),
                               key=f"mtr_d_{sel}", disabled=not (can_edit and on), help=_tr("mp_trial_until_help"))
        new_note = t2.text_input(_tr("mp_trial_note"), value=note, key=f"mtr_n_{sel}",
                                 disabled=not (can_edit and on), placeholder=_tr("mp_trial_note_ph"))
        if can_edit and st.button(_tr("mp_trial_save"), key=f"mtr_save_{sel}"):
            want_tu = new_tu if on else None
            want_note = ((new_note or "").strip() or None) if on else None
            if want_tu == tu and (want_note or "") == note:
                st.info(_tr("nochange"))
            else:
                try:
                    exec_sql([("INSERT INTO kabinet_data.marketplace_attributes (marketplace_id) VALUES (%s) "
                               "ON CONFLICT (marketplace_id) DO NOTHING", (sel,)),
                              ("UPDATE kabinet_data.marketplace_attributes SET trial_until = %s, trial_note = %s, "
                               "updated_at = now() WHERE marketplace_id = %s", (want_tu, want_note, sel)),
                              (MPLOG, ("marketplace", sel, "trial_until", None if tu is None else str(tu),
                                       None if want_tu is None else str(want_tu)))])
                    st.cache_data.clear(); st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))


def _mp_ext_site_errors(sel, esys, eid, site) -> list:
    """Проверки внешних данных и ссылки — общие для карточки и формы создания (ТЗ 003 §4)."""
    errs = []
    if bool((esys or "").strip()) != bool((eid or "").strip()):
        errs.append(_tr("mp_ext_half"))
    if (esys or "").strip() and (eid or "").strip():
        dup = q_now("""SELECT m.code FROM kabinet_data.marketplace_attributes a
                       JOIN kabinet_data.marketplaces_new m ON m.id = a.marketplace_id
                       WHERE a.external_system = %s AND a.external_id = %s AND a.marketplace_id <> %s""",
                    (esys.strip(), eid.strip(), sel))
        if not dup.empty:
            errs.append(_trf("mp_ext_dup", code=dup["code"].iloc[0]))
    if (site or "").strip() and not re.match(r"^https://[^\s/]+\.[^\s/]+\S*$", site.strip()):
        errs.append(_tr("mp_site_bad"))
    return errs


def _mp_check(sel, row, new_name, new_plat, new_ctry, new_esys, new_eid, new_site, plats, blockers) -> list:
    errs = []
    plat_changed = new_plat != row["platform_short"]
    ctry_changed = new_ctry != row["country_alpha2"]
    if (plat_changed or ctry_changed) and blockers:
        errs.append(_trf("mp_locked", what=_tr("mp_locked_what_platform"),
                         what2=_tr("mp_locked_for_platform")) + " " + "; ".join(blockers)
                    + " " + _tr("mp_locked_advice"))
    if plat_changed and not bool(plats.set_index("short_name").loc[new_plat, "is_active"]):
        errs.append(_trf("mp_platform_inactive", name=new_plat))
    if plat_changed or ctry_changed:
        dup = q_now("""SELECT code FROM kabinet_data.marketplaces_new
                       WHERE platform_short = %s AND country_alpha2 = %s AND id <> %s""",
                    (new_plat, new_ctry, sel))
        if not dup.empty:
            errs.append(_trf("mp_dup_pair", code=dup["code"].iloc[0]))
    if ctry_changed:
        # пул по ТЗ 004 — маркетплейсы ОДНОЙ страны: увести участника в другую страну значит
        # сломать пул, поэтому проверяем страны остальных действующих участников
        pools = q_now("""SELECT p.name, string_agg(DISTINCT m2.country_alpha2, ', ') AS countries
                         FROM kabinet_data.pool_members pm
                         JOIN kabinet_data.pools p ON p.id = pm.pool_id
                         JOIN kabinet_data.pool_members pm2 ON pm2.pool_id = pm.pool_id
                              AND pm2.marketplace_id <> pm.marketplace_id
                              AND (pm2.valid_to IS NULL OR pm2.valid_to > CURRENT_DATE)
                         JOIN kabinet_data.marketplaces_new m2 ON m2.id = pm2.marketplace_id
                         WHERE pm.marketplace_id = %s AND (pm.valid_to IS NULL OR pm.valid_to > CURRENT_DATE)
                         GROUP BY p.name""", (sel,))
        for _, pr in pools.iterrows():
            others = [x.strip() for x in as_text(pr["countries"]).split(",") if x.strip()]
            if any(o != new_ctry for o in others):
                errs.append(_trf("mp_pool_country", pool=pr["name"], countries=", ".join(others)))
    errs += _mp_ext_site_errors(sel, new_esys, new_eid, new_site)
    if not (new_name or "").strip():
        errs.append(_tr("plat_name_empty"))
    return errs


def _mp_save(sel, row, new_name, new_plat, new_ctry, new_curr, new_esys, new_eid, new_site):
    plat_changed = new_plat != row["platform_short"]
    ctry_changed = new_ctry != row["country_alpha2"]
    stmts, log = [], []
    new_code = f"{new_plat}-{new_ctry}" if (plat_changed or ctry_changed) else row["code"]
    if (new_name or "").strip() != (row["name"] or ""):
        stmts.append(("UPDATE kabinet_data.marketplaces_new SET name = %s WHERE id = %s", (new_name.strip(), sel)))
        log.append(("name", row["name"], new_name.strip()))
    if new_curr != row["currency"]:
        stmts.append(("UPDATE kabinet_data.marketplaces_new SET currency = %s WHERE id = %s", (new_curr, sel)))
        log.append(("currency", row["currency"], new_curr))
    if plat_changed:
        stmts.append(("UPDATE kabinet_data.marketplaces_new SET platform_short = %s WHERE id = %s", (new_plat, sel)))
        log.append(("platform_short", row["platform_short"], new_plat))
    if ctry_changed:
        stmts.append(("UPDATE kabinet_data.marketplaces_new SET country_alpha2 = %s WHERE id = %s", (new_ctry, sel)))
        log.append(("country_alpha2", row["country_alpha2"], new_ctry))
    if new_code != row["code"]:
        # код производный: после разрешённой смены пересобираем его сами, id не трогаем (§4)
        stmts.append(("UPDATE kabinet_data.marketplaces_new SET code = %s WHERE id = %s", (new_code, sel)))
        log.append(("code", row["code"], new_code))
    ext = {"external_system": (new_esys or "").strip() or None,
           "external_id": (new_eid or "").strip() or None,
           "website_url": (new_site or "").strip() or None}
    if any(not _same(row[k], v) for k, v in ext.items()):
        stmts.append(("INSERT INTO kabinet_data.marketplace_attributes (marketplace_id) VALUES (%s) "
                      "ON CONFLICT (marketplace_id) DO NOTHING", (sel,)))
        stmts.append(("UPDATE kabinet_data.marketplace_attributes SET external_system = %s, "
                      "external_id = %s, website_url = %s, updated_at = now(), updated_by = 'kabinet' "
                      "WHERE marketplace_id = %s",
                      (ext["external_system"], ext["external_id"], ext["website_url"], sel)))
        log += [(k, row[k], v) for k, v in ext.items() if not _same(row[k], v)]
    if not stmts:
        st.info(_tr("mp_nochange"))
        return
    stmts += [(MPLOG, ("marketplace", sel, f,
                       None if (o is None or (isinstance(o, float) and pd.isna(o))) else str(o),
                       None if v is None else str(v))) for f, o, v in log]
    try:
        exec_sql(stmts)
        st.cache_data.clear()
        st.success(_trf("mp_saved", code=new_code))
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _mp_archive(row, sel: int):
    """В архив / вернуть из архива (ТЗ 003 §6–§7). Физического удаления нет вовсе — и у записи,
    заведённой по ошибке, тоже (решение владельца 06.10.2026). Перед архивом — действующие связи
    и второе нажатие: архив не стирает данные, но выключает маркетплейс из новых операций."""
    box = st.container(border=True)
    box.markdown("**" + _tr("mp_act_h") + "**")
    flag = f"mp_arch_ask_{sel}"
    if not bool(row["is_active"]):
        box.caption(_tr("mp_restore_note"))
        if box.button(_tr("mp_act_restore"), key=f"mp_rest_{sel}"):
            _mp_set_active(row, sel, True)
        return
    if not st.session_state.get(flag):
        box.caption(_tr("mp_off_note"))
        if box.button(_tr("mp_act_archive"), key=f"mp_arch_{sel}"):
            st.session_state[flag] = True
            st.rerun()
        return
    deps = _mp_active_deps(sel)
    if deps:
        box.warning(_tr("mp_off_deps") + ":\n\n" + "\n".join(f"- {d}" for d in deps)
                    + "\n\n" + _tr("mp_off_deps_tail"))
    else:
        box.info(_tr("mp_off_nodeps"))
    c1, c2 = box.columns(2)
    if c1.button(_tr("mp_act_archive_yes"), key=f"mp_arch_yes_{sel}", type="primary"):
        st.session_state.pop(flag, None)
        _mp_set_active(row, sel, False)
    if c2.button(_tr("del_confirm_no"), key=f"mp_arch_no_{sel}"):
        st.session_state.pop(flag, None)
        st.rerun()


def _mp_set_active(row, sel: int, active: bool):
    try:
        exec_sql([("UPDATE kabinet_data.marketplaces_new SET is_active = %s WHERE id = %s", (active, sel)),
                  (MPLOG, ("marketplace", sel, "is_active", str(bool(row["is_active"])), str(active)))])
        st.cache_data.clear()
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _mp_add_form(mps, plats, countries, curr):
    """Создание маркетплейса (ТЗ 003 §4–§5): площадка и страна — из справочников и только активные
    (§7), валюта — из ISO 4217 и не подставляется по стране (§4), код собирается сам, новый
    маркетплейс активен (§6). Пара «площадка + страна» уникальна среди ВСЕХ записей, включая архив."""
    st.markdown("#### " + _tr("mp_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("mp_ro_add"))
        return
    st.caption(_tr("mp_add_note"))
    act_plats = plats[plats["is_active"].astype(bool)]
    act_ctry = countries[countries["is_active"].astype(bool)]
    cn = act_ctry.set_index("alpha2")["name"].to_dict()
    pn = act_plats.set_index("short_name")["full_name"].to_dict()
    with st.form("mp_add_form", clear_on_submit=False):
        a1, a2, a3 = st.columns(3)
        plat = a1.selectbox(_tr("mp_platform") + " *", list(pn), index=None, placeholder=_tr("mp_pick_ph"),
                            format_func=lambda sh: f"{sh} — {pn[sh]}", key="mp_add_plat",
                            help=_tr("mp_add_plat_help"))
        ctry = a2.selectbox(_tr("mp_country") + " *", list(cn), index=None, placeholder=_tr("mp_pick_ph"),
                            format_func=lambda a: f"{cn[a]} ({a})", key="mp_add_ctry",
                            help=_tr("mp_add_ctry_help"))
        cur = a3.selectbox(_tr("mp_currency") + " *", list(curr["code"]), index=None,
                           placeholder=_tr("mp_pick_ph"), format_func=lambda c_: _curr_label(c_, curr),
                           key="mp_add_curr", help=_tr("mp_currency_help"))
        name = st.text_input(_tr("col_name") + " *", key="mp_add_name", help=_tr("mp_name_help"),
                             placeholder="Amazon Spain")
        b1, b2, b3 = st.columns([1, 1, 2])
        esys = b1.text_input(_tr("mp_ext_sys"), key="mp_add_esys", help=_tr("mp_ext_hint"))
        eid = b2.text_input(_tr("mp_ext_id"), key="mp_add_eid", help=_tr("mp_ext_hint"))
        site = b3.text_input(_tr("mp_site"), key="mp_add_site", help=_tr("mp_site_help"),
                             placeholder="https://www.amazon.es")
        go = st.form_submit_button(_tr("mp_add_btn"), type="primary")
    if not go:
        return
    errs = []
    if not plat:
        errs.append(_tr("mp_add_need_plat"))
    if not ctry:
        errs.append(_tr("mp_add_need_ctry"))
    if not cur:
        errs.append(_tr("mp_add_need_curr"))
    if not (name or "").strip():
        errs.append(_tr("plat_name_empty"))
    if plat and ctry:
        dup = q_now("""SELECT code, is_active FROM kabinet_data.marketplaces_new
                       WHERE platform_short = %s AND country_alpha2 = %s""", (plat, ctry))
        if not dup.empty:
            errs.append(_trf("mp_add_dup_active" if bool(dup["is_active"].iloc[0]) else "mp_add_dup_archived",
                             code=dup["code"].iloc[0]))
    errs += _mp_ext_site_errors(-1, esys, eid, site)
    if errs:
        for e in errs:
            st.error(e)
        return
    code = f"{plat}-{ctry}"
    ext = ((esys or "").strip() or None, (eid or "").strip() or None, (site or "").strip() or None)
    try:
        # одна команда: маркетплейс, его реквизиты и запись журнала — либо всё, либо ничего
        exec_sql([("""
            WITH m AS (INSERT INTO kabinet_data.marketplaces_new
                           (code, platform_short, country_alpha2, name, currency, is_active)
                       VALUES (%s, %s, %s, %s, %s, true) RETURNING id),
                 a AS (INSERT INTO kabinet_data.marketplace_attributes
                           (marketplace_id, external_system, external_id, website_url, updated_by)
                       SELECT id, %s, %s, %s, %s FROM m)
            INSERT INTO kabinet_data.marketplace_change_log (object_type, object_id, field, old_value, new_value, actor)
            SELECT 'marketplace', id, 'created', NULL, %s, %s FROM m
        """, (code, plat, ctry, name.strip(), cur, *ext, _actor(), f"{code} · {name.strip()}", _actor()))])
        st.cache_data.clear()
        new_id = q_now("SELECT id FROM kabinet_data.marketplaces_new WHERE code = %s", (code,))
        if not new_id.empty:
            dict_kit.card_focus("mp_card", int(new_id["id"].iloc[0]))
        st.session_state["mp_created"] = code
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


# ---------------------------------------------------------------- ТЗ 002 ---
A2_RE = re.compile(r"^[A-Z]{2}$")
A3_RE = re.compile(r"^[A-Z]{3}$")
CNAME_RE = re.compile(r"^[A-Za-z][A-Za-z\s\.\-'’()]{1,}$")


def _cname_key(v: str) -> str:
    """Нормализация названия для контроля дублей (ТЗ 002 §4): регистр не важен, края обрезаны,
    несколько пробелов внутри сведены к одному. Дефисы и прочие знаки остаются как есть —
    «Guinea-Bissau» и «Guinea Bissau» это разные названия, и склеивать их нельзя."""
    return re.sub(r"\s+", " ", (v or "").strip()).lower()


def _ctry_usage() -> pd.DataFrame:
    """Где страна используется — для колонки списка: маркетплейсы (коды), склады нахождения и обслуживания."""
    return q("""
        SELECT c.alpha2,
               (SELECT string_agg(m.code, ', ' ORDER BY m.code) FROM kabinet_data.marketplaces_new m
                 WHERE m.country_alpha2 = c.alpha2) AS mps,
               (SELECT count(*) FROM kabinet_data.warehouses w WHERE w.country = c.alpha2) AS wh,
               (SELECT count(*) FROM kabinet_data.warehouse_countries wc WHERE wc.country_alpha2 = c.alpha2) AS serve
        FROM kabinet_data.countries c
    """).set_index("alpha2")


def _country_deps(a2: str) -> dict:
    """Что зависит от страны сейчас (ТЗ 002 §8): действующие маркетплейсы, пулы, матрица и прогнозы; склады —
    для сведения. Читается без кеша: по этому списку решается, можно ли деактивировать."""
    r = q_now("""
        WITH m AS (SELECT id, code, is_active FROM kabinet_data.marketplaces_new WHERE country_alpha2 = %s),
             p AS (SELECT DISTINCT pm.pool_id FROM kabinet_data.pool_members pm
                    WHERE pm.marketplace_id IN (SELECT id FROM m)
                      AND pm.valid_from <= CURRENT_DATE AND (pm.valid_to IS NULL OR pm.valid_to > CURRENT_DATE))
        SELECT (SELECT string_agg(code, ', ' ORDER BY code) FROM m WHERE is_active) AS mps,
               (SELECT count(*) FROM m WHERE is_active) AS mps_n,
               (SELECT string_agg(name, ', ' ORDER BY name) FROM kabinet_data.pools WHERE id IN (SELECT pool_id FROM p)) AS pools,
               (SELECT count(*) FROM kabinet_data.assortment_admissions
                 WHERE level = 'marketplace' AND removed_on IS NULL AND marketplace_id IN (SELECT id FROM m)) AS adm,
               (SELECT count(*) FROM kabinet_data.forecast_register
                 WHERE is_current AND ((object_type = 'marketplace' AND object_id IN (SELECT id FROM m))
                                       OR (object_type = 'pool' AND object_id IN (SELECT pool_id FROM p)))) AS fc,
               (SELECT count(*) FROM kabinet_data.warehouses WHERE country = %s) AS wh,
               (SELECT count(*) FROM kabinet_data.warehouse_countries WHERE country_alpha2 = %s) AS serve
    """, (a2, a2, a2))
    row = r.iloc[0]
    return {"mps": as_text(row["mps"]), "mps_n": int(row["mps_n"]), "pools": as_text(row["pools"]),
            "adm": int(row["adm"]), "fc": int(row["fc"]), "wh": int(row["wh"]), "serve": int(row["serve"])}


def _ctry_log_row(a2, field, old, new):
    return ("INSERT INTO kabinet_data.country_change_log (alpha2, field, old_value, new_value, actor) "
            "VALUES (%s, %s, %s, %s, %s)", (a2, field, old, new, _actor()))


def _ctry_field_errs(key: str, field: str):
    """Ошибка проверки под своим полем (ТЗ 002 §7: «ошибки показываются на уровне конкретного поля»)."""
    for e in st.session_state.get(key, {}).get(field, []):
        st.error(e)


def _section_ctry():
    """Страны по общему приёму справочников (07.10.2026): инструкция → список с поиском и фильтром → карточка по
    клику → форма создания. Правила ТЗ 002 v0.2 без изменений: ключ ссылок — Alpha-2, ISO-коды после создания
    только для чтения, дубли ищутся по ВСЕМ записям (коды как есть, название без регистра и лишних пробелов),
    физического удаления нет — только признак активности, деактивация с проверкой зависимостей (§8)."""
    dict_kit.instruction(_tr("ctry_about"), _tr("ctry_id_note"))
    _created = st.session_state.pop("ctry_created_code", None)
    if _created:
        st.success(_trf("ctry_created_ok", code=_created))
    _lang_col = {"ru": "name_ru", "uk": "name_uk"}.get(get_lang(), "name_en")
    ctry = q(f"""
        SELECT c.alpha2, c.alpha3, c."numeric" AS num, c.name, c.is_active,
               COALESCE(n.{_lang_col}, n.name_en) AS local_name
        FROM kabinet_data.countries c
        LEFT JOIN kabinet_data.country_names n ON n.alpha2 = c.alpha2
        ORDER BY c.name
    """)
    use = _ctry_usage()

    f1, f2 = st.columns([2, 1])
    needle = dict_kit.search_input(_tr("ctry_search"), "ctry_search", _tr, "Spain, ES, ESP, 724…", where=f1).lower()
    # по умолчанию «Все», как и было: активных стран полтора десятка, остальные ISO-страны выключены, и
    # список «только активные» прятал бы почти весь справочник
    state_sel = f2.selectbox(_tr("sku_state_f"), ["all", "active", "inactive"], key="ctry_state_f",
                             format_func=lambda x: _tr(f"ctry_state_{x}"))
    view = ctry
    if needle:
        view = view[view.apply(lambda r: needle in str(r["name"]).lower()
                               or needle in as_text(r["local_name"]).lower()
                               or needle == str(r["alpha2"]).lower()
                               or needle == str(r["alpha3"]).lower()
                               or needle.lstrip("0") == str(r["num"]), axis=1)]
        # точное совпадение кода — первой строкой: по «ES» ищут Испанию, а не Estonia и Seychelles
        exact = (view["alpha2"].str.lower() == needle) | (view["alpha3"].str.lower() == needle)
        view = pd.concat([view[exact], view[~exact]])
    if state_sel != "all":
        view = view[view["is_active"].astype(bool) == (state_sel == "active")]
    st.caption(_trf("ctry_summary", shown=len(view), total=len(ctry),
                    off=int((~ctry["is_active"].astype(bool)).sum())))

    def _used(a2):
        if a2 not in use.index:
            return ""
        u = use.loc[a2]
        parts = []
        if as_text(u["mps"]):
            parts.append(as_text(u["mps"]))
        if int(u["wh"]):
            parts.append(_trf("ctry_use_wh", n=int(u["wh"])))
        if int(u["serve"]):
            parts.append(_trf("ctry_use_serve", n=int(u["serve"])))
        return " · ".join(parts) or _tr("ctry_use_none")

    lst = pd.DataFrame({
        "a2": view["alpha2"],
        "name": view["name"],
        "local": [as_text(x) for x in view["local_name"]],
        "a3": view["alpha3"],
        "num": [f"{int(x):03d}" for x in view["num"]],
        "state": [_tr("ctry_state_active") if bool(a) else _tr("ctry_state_inactive") for a in view["is_active"]],
        "used": [_used(a) for a in view["alpha2"]],
    })
    options = list(view["alpha2"])
    picked = dict_kit.table_pick(lst, options, "ctry_list", (needle, state_sel), column_config={
        "a2": st.column_config.TextColumn(_tr("ctry_col_id"), width=160, help=_tr("ctry_col_id_help")),
        "name": st.column_config.TextColumn(_tr("ctry_col_name"), width="medium"),
        "local": st.column_config.TextColumn(_tr("ctry_col_local"), width="medium", help=_tr("ctry_local_note")),
        "a3": st.column_config.TextColumn(_tr("ctry_col_a3"), width=80),
        "num": st.column_config.TextColumn(_tr("ctry_col_num"), width=80),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=100),
        "used": st.column_config.TextColumn(_tr("ctry_col_used"), width="large", help=_tr("ctry_col_used_help")),
    })
    st.caption(_tr("ctry_list_empty") if lst.empty else _tr("ctry_list_hint"))
    if options:
        labels = {r.alpha2: f"{r.name} ({r.alpha2})" + ("" if r.is_active else f" · {_tr('ctry_state_inactive')}")
                  for r in view.itertuples()}
        st.markdown("#### " + _tr("ctry_card"))
        sel = dict_kit.card_pick(_tr("ctry_pick"), options, labels, "ctry_card", picked)
        _ctry_card(ctry.set_index("alpha2").loc[sel], sel, ctry)

    _ctry_add_form(ctry)


def _ctry_card(row, sel: str, ctry: pd.DataFrame):
    can_edit = auth.can("dict.edit")
    ekey = f"ctry_card_errs_{sel}"
    with st.container(border=True):
        st.markdown(f"**{row['name']} · {sel}**" + ("" if bool(row["is_active"]) else f"  \n{_tr('ctry_is_off')}"))
        c1, c2, c3 = st.columns(3)
        c1.text_input(_tr("ctry_col_id"), value=sel, disabled=True, key=f"ca2_{sel}")
        c2.text_input(_tr("ctry_col_a3"), value=row["alpha3"], disabled=True, key=f"ca3_{sel}")
        c3.text_input(_tr("ctry_col_num"), value=f"{int(row['num']):03d}", disabled=True, key=f"cnum_{sel}")
        st.caption(_tr("ctry_codes_ro"))
        new_name = st.text_input(_tr("ctry_col_name"), value=row["name"], key=f"cname_{sel}",
                                 help=_tr("ctry_name_help"), disabled=not can_edit)
        _ctry_field_errs(ekey, "name")
        if as_text(row["local_name"]):
            st.caption(f"{_tr('ctry_col_local')}: {row['local_name']} · {_tr('ctry_local_note')}")
        if st.button(_tr("save"), key=f"ctry_save_{sel}", type="primary", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            name = (new_name or "").strip()
            errs = []
            if not CNAME_RE.match(name):
                errs.append(_tr("ctry_name_bad"))
            others = ctry[ctry["alpha2"] != sel]
            keys = {_cname_key(x): x for x in others["name"]}
            if _cname_key(name) in keys:
                errs.append(_trf("ctry_dup_name", name=keys[_cname_key(name)]))
            if errs:
                st.session_state[ekey] = {"name": errs}
                st.rerun()
            st.session_state.pop(ekey, None)
            if name == row["name"]:
                st.info(_tr("nochange"))
            else:
                try:
                    exec_sql([("UPDATE kabinet_data.countries SET name = %s WHERE alpha2 = %s", (name, sel)),
                              _ctry_log_row(sel, "name", row["name"], name)])
                    st.cache_data.clear(); st.success(_tr("ctry_saved")); st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

    if can_edit:
        _ctry_activity(row, sel)

    with st.expander(_tr("ctry_log")):
        lg = q1("""SELECT changed_at, field, old_value, new_value, actor
                   FROM kabinet_data.country_change_log WHERE alpha2 = %s
                   ORDER BY changed_at DESC LIMIT 200""", (sel,))
        if lg.empty:
            st.caption(_tr("mp_log_empty"))
        else:
            lg["changed_at"] = pd.to_datetime(lg["changed_at"]).dt.strftime("%d.%m.%Y %H:%M")
            lg["field"] = [_tr(f"ctry_logf_{f}") if f in ("name", "is_active", "created", "migration_plan") else f
                           for f in lg["field"]]
            lg.columns = [_tr("mp_log_when"), _tr("mp_log_field"), _tr("mp_log_old"),
                          _tr("mp_log_new"), _tr("mp_log_who")]
            st.dataframe(lg, hide_index=True, use_container_width=True, height=min(300, 38 + 35 * len(lg)))


def _ctry_activity(row, sel: str):
    """Сделать неактивной / вернуть (ТЗ 002 §3, §8). Удаления нет. Перед деактивацией — всё, что от страны
    зависит; пока у неё есть действующие маркетплейсы (новые операции по ним не закрыты), деактивация проходит
    только с подтверждённым планом миграции — он ложится в историю страны."""
    box = st.container(border=True)
    box.markdown("**" + _tr("ctry_act_h") + "**")
    flag = f"ctry_off_ask_{sel}"
    if not bool(row["is_active"]):
        box.caption(_tr("ctry_on_note"))
        if box.button(_tr("ctry_act_on"), key=f"ctry_on_{sel}"):
            _ctry_set_active(sel, True)
        return
    if not st.session_state.get(flag):
        box.caption(_tr("ctry_off_note"))
        if box.button(_tr("ctry_act_off"), key=f"ctry_off_{sel}"):
            st.session_state[flag] = True
            st.rerun()
        return
    d = _country_deps(sel)
    lines = []
    if d["mps_n"]:
        lines.append(_trf("ctry_dep_mps", n=d["mps_n"], codes=d["mps"]))
    if d["pools"]:
        lines.append(_trf("ctry_dep_pools", names=d["pools"]))
    if d["adm"]:
        lines.append(_trf("ctry_dep_adm", n=d["adm"]))
    if d["fc"]:
        lines.append(_trf("ctry_dep_fc", n=d["fc"]))
    if d["wh"]:
        lines.append(_trf("ctry_dep_wh", n=d["wh"]))
    if d["serve"]:
        lines.append(_trf("ctry_dep_serve", n=d["serve"]))
    if lines:
        box.warning(_tr("ctry_off_deps") + ":\n\n" + "\n".join(f"- {x}" for x in lines)
                    + "\n\n" + _tr("ctry_off_deps_tail"))
    else:
        box.info(_tr("ctry_dep_none"))
    plan = ""
    if d["mps_n"]:
        box.caption(_tr("ctry_need_plan"))
        plan = box.text_area(_tr("ctry_plan"), key=f"ctry_plan_{sel}", help=_tr("ctry_plan_help")).strip()
    c1, c2 = box.columns(2)
    blocked = bool(d["mps_n"]) and not plan
    if c1.button(_tr("ctry_act_off_yes"), key=f"ctry_off_yes_{sel}", type="primary", disabled=blocked,
                 help=_tr("ctry_plan_needed") if blocked else None):
        st.session_state.pop(flag, None)
        _ctry_set_active(sel, False, plan or None)
    if c2.button(_tr("del_confirm_no"), key=f"ctry_off_no_{sel}"):
        st.session_state.pop(flag, None)
        st.rerun()


def _ctry_set_active(sel: str, active: bool, plan: str | None = None):
    stmts = [("UPDATE kabinet_data.countries SET is_active = %s WHERE alpha2 = %s", (active, sel)),
             _ctry_log_row(sel, "is_active", str(not active), str(active))]
    if plan:
        stmts.append(_ctry_log_row(sel, "migration_plan", None, plan))
    try:
        exec_sql(stmts)
        st.cache_data.clear()
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _ctry_add_form(ctry: pd.DataFrame):
    """Создание страны (ТЗ 002): все четыре поля обязательны, страна создаётся активной. Проверки формата и
    дублей — до сохранения и по ВСЕМ записям, ошибка — под своим полем (§7)."""
    st.markdown("#### " + _tr("ctry_new"))
    if not auth.can("dict.edit"):
        st.caption(_tr("ctry_ro_add"))
        return
    st.caption(_tr("ctry_add_note"))
    ekey = "ctry_add_errs"
    a1, a2c, a3c = st.columns(3)
    with a1:
        n_a2 = st.text_input(_tr("ctry_col_a2") + " *", key="ctry_add_a2", placeholder="DE", help=_tr("ctry_a2_help"))
        _ctry_field_errs(ekey, "a2")
    with a2c:
        n_a3 = st.text_input(_tr("ctry_col_a3") + " *", key="ctry_add_a3", placeholder="DEU", help=_tr("ctry_a3_help"))
        _ctry_field_errs(ekey, "a3")
    with a3c:
        n_num = st.text_input(_tr("ctry_col_num") + " *", key="ctry_add_num", placeholder="276",
                              help=_tr("ctry_num_help"))
        _ctry_field_errs(ekey, "num")
    n_name = st.text_input(_tr("ctry_col_name") + " *", key="ctry_add_name", placeholder="Germany",
                           help=_tr("ctry_name_help"))
    _ctry_field_errs(ekey, "name")
    if not st.button(_tr("ctry_create"), key="ctry_add_go", type="primary"):
        return
    a2, a3 = (n_a2 or "").strip().upper(), (n_a3 or "").strip().upper()
    name = (n_name or "").strip()
    errs = {}
    # дубли ищем среди ВСЕХ записей, активных и неактивных (ТЗ §4); читаем без кеша — проверка перед записью
    allc = q_now('SELECT alpha2, alpha3, "numeric" AS num, name FROM kabinet_data.countries', ())
    if not A2_RE.match(a2):
        errs.setdefault("a2", []).append(_tr("ctry_a2_bad"))
    elif a2 in set(allc["alpha2"]):
        errs.setdefault("a2", []).append(_trf("ctry_dup_a2", v=a2, name=allc.set_index("alpha2").loc[a2, "name"]))
    if not A3_RE.match(a3):
        errs.setdefault("a3", []).append(_tr("ctry_a3_bad"))
    elif a3 in set(allc["alpha3"]):
        errs.setdefault("a3", []).append(_trf("ctry_dup_a3", v=a3, name=allc.set_index("alpha3").loc[a3, "name"]))
    try:
        num = int((n_num or "").strip())
        if not 1 <= num <= 999:
            raise ValueError
    except ValueError:
        num = None
        errs.setdefault("num", []).append(_tr("ctry_num_bad"))
    if num is not None and num in set(int(x) for x in allc["num"]):
        errs.setdefault("num", []).append(_trf("ctry_dup_num", v=f"{num:03d}",
                                               name=allc[allc["num"] == num]["name"].iloc[0]))
    if not CNAME_RE.match(name):
        errs.setdefault("name", []).append(_tr("ctry_name_bad"))
    else:
        keys = {_cname_key(x): x for x in allc["name"]}
        if _cname_key(name) in keys:
            errs.setdefault("name", []).append(_trf("ctry_dup_name", name=keys[_cname_key(name)]))
    if errs:
        st.session_state[ekey] = errs
        st.rerun()
    st.session_state.pop(ekey, None)
    try:
        exec_sql([("INSERT INTO kabinet_data.countries (alpha2, alpha3, \"numeric\", name, is_active) "
                   "VALUES (%s, %s, %s, %s, true)", (a2, a3, num, name)),
                  _ctry_log_row(a2, "created", None, f"{a2} / {a3} / {num:03d} · {name}")])
        st.cache_data.clear()
        for k in ("ctry_add_a2", "ctry_add_a3", "ctry_add_num", "ctry_add_name"):
            st.session_state.pop(k, None)
        dict_kit.card_focus("ctry_card", a2)
        st.session_state["ctry_created_code"] = a2
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))

# ---------------------------------------------------------------- ТЗ 003 ---
SHORT_RE = re.compile(r"^[A-Z0-9]{2,10}$")
MPLOG = ("INSERT INTO kabinet_data.marketplace_change_log (object_type, object_id, field, old_value, new_value, actor) "
         "VALUES (%s, %s, %s, %s, %s, 'kabinet')")


def _plat_attrs() -> pd.DataFrame:
    """Реквизиты площадок из таблицы рядом; строки может не быть у только что созданной площадки."""
    return q("""
        SELECT p.id, p.short_name, p.full_name,
               COALESCE(a.is_active, true) AS is_active, a.comment,
               a.variation_group_label, a.variation_label, a.product_entity_label, a.peid_format_hint
        FROM kabinet_data.platforms p
        LEFT JOIN kabinet_data.platform_attributes a ON a.platform_id = p.id
        ORDER BY p.short_name
    """)


def _mp_blockers(mp_id: int) -> list:
    """Связи, из-за которых по ТЗ 003 §5 запрещена смена страны и площадки.

    Считаем ВСЁ, включая закрытое и историческое: «закрытие записи, перевод в историю или
    деактивация marketplace не снимают запрет» — так в ТЗ, и это правильно, иначе смена страны
    задним числом переписала бы историю чужого рынка.
    """
    rows = q1("""
        SELECT (SELECT count(*) FROM kabinet_data.assortment_admissions
                 WHERE level = 'marketplace' AND marketplace_id = %s) AS adm,
               (SELECT count(*) FROM kabinet_data.assortment_representations r
                 JOIN kabinet_data.assortment_admissions a ON a.id = r.admission_id
                 WHERE a.level = 'marketplace' AND a.marketplace_id = %s) AS repr,
               (SELECT count(*) FROM kabinet_data.forecast_documents
                 WHERE object_type = 'marketplace' AND object_id = %s) AS docs,
               (SELECT count(*) FROM kabinet_data.forecast_register
                 WHERE object_type = 'marketplace' AND object_id = %s) AS reg
    """, (mp_id, mp_id, mp_id, mp_id))
    out = []
    if int(rows["adm"].iloc[0]):
        out.append(_trf("mp_dep_matrix", n=int(rows["adm"].iloc[0])))
    if int(rows["repr"].iloc[0]):
        out.append(_trf("mp_dep_repr", n=int(rows["repr"].iloc[0])))
    if int(rows["docs"].iloc[0]):
        out.append(_trf("mp_dep_forecast", n=int(rows["docs"].iloc[0])))
    if int(rows["reg"].iloc[0]):
        out.append(_trf("mp_dep_register", n=int(rows["reg"].iloc[0])))
    return out


def _mp_active_deps(mp_id: int) -> list:
    """Что показать перед деактивацией (ТЗ 003 §7): действующие связи, а не вся история."""
    rows = q1("""
        SELECT (SELECT count(*) FROM kabinet_data.assortment_admissions
                 WHERE level = 'marketplace' AND marketplace_id = %s AND removed_on IS NULL) AS adm,
               (SELECT count(*) FROM kabinet_data.pool_members
                 WHERE marketplace_id = %s AND (valid_to IS NULL OR valid_to > CURRENT_DATE)) AS pools,
               (SELECT count(*) FROM kabinet_data.forecast_register
                 WHERE object_type = 'marketplace' AND object_id = %s AND is_current) AS fc,
               (SELECT count(*) FROM kabinet_data.product_entities
                 WHERE marketplace_id = %s AND is_active IS NOT FALSE) AS peid,
               -- открытые алерты по маркетплейсу как объекту: прогнозные ([PACE:/MISSING:/PARTIAL:код/SKU]).
               -- Своей колонки рынка у инцидентов нет, поэтому ищем по коду в токене сообщения
               (SELECT count(*) FROM kabinet_data.incidents
                 WHERE status IN ('open', 'acknowledged')
                   AND message LIKE '%%:' || (SELECT code FROM kabinet_data.marketplaces_new WHERE id = %s) || '/%%') AS alerts
    """, (mp_id, mp_id, mp_id, mp_id, mp_id))
    out = []
    if int(rows["adm"].iloc[0]):
        out.append(_trf("mp_adep_matrix", n=int(rows["adm"].iloc[0])))
    if int(rows["pools"].iloc[0]):
        out.append(_trf("mp_dep_pool", n=int(rows["pools"].iloc[0])))
    if int(rows["fc"].iloc[0]):
        out.append(_trf("mp_adep_fc", n=int(rows["fc"].iloc[0])))
    if int(rows["peid"].iloc[0]):
        out.append(_trf("mp_dep_peid", n=int(rows["peid"].iloc[0])))
    if int(rows["alerts"].iloc[0]):
        out.append(_trf("mp_dep_alerts", n=int(rows["alerts"].iloc[0])))
    return out


def _section_plat():
    """Площадки по общему приёму справочников (06.10.2026): инструкция → список с поиском и фильтром →
    карточка выбранной строки → форма создания. Правила — ТЗ 003 §3, §6, §7 без изменений: краткое
    название 2–10 заглавных латинских букв и цифр, уникально; три обозначения ассортиментной структуры
    живут на площадке и используются всеми её маркетплейсами; физического удаления нет — только архив и
    возврат (решение владельца 06.10.2026)."""
    dict_kit.instruction(_tr("plat_about"), _tr("plat_hint"))
    _created = st.session_state.pop("plat_created_code", None)
    if _created:
        st.success(_trf("plat_created_ok", code=_created))
    plats = _plat_attrs()
    mp_cnt = q("""
        SELECT platform_short, count(*) AS total, count(*) FILTER (WHERE is_active) AS active,
               string_agg(code, ', ' ORDER BY code) FILTER (WHERE is_active) AS codes
        FROM kabinet_data.marketplaces_new GROUP BY 1
    """).set_index("platform_short")

    f1, f2 = st.columns([2, 1])
    search = dict_kit.search_input(_tr("plat_search"), "plat_search", _tr, "AMZ, Amazon…", where=f1)
    state_sel = f2.selectbox(_tr("sku_state_f"), ["active", "archived", "all"], key="plat_state_f",
                             format_func=lambda x: _tr(f"sku_state_{x}"))
    view = plats.copy()
    if search:
        view = view[view["short_name"].str.contains(search, case=False, na=False, regex=False)
                    | view["full_name"].fillna("").str.contains(search, case=False, na=False, regex=False)]
    if state_sel != "all":
        view = view[view["is_active"].astype(bool) == (state_sel == "active")]
    st.caption(_trf("mp_summary", shown=len(view), total=len(plats),
                    arch=int((~plats["is_active"].astype(bool)).sum())))

    def _labels(r):
        parts = [as_text(r[k]) for k in ("variation_group_label", "variation_label", "product_entity_label")]
        return " / ".join(p or "—" for p in parts) if any(parts) else ""

    lst = pd.DataFrame({
        "short": view["short_name"],
        "name": view["full_name"].fillna(""),
        "mps": [as_text(mp_cnt["codes"].get(sh)) if sh in mp_cnt.index else "" for sh in view["short_name"]],
        "labels": [_labels(r) for _, r in view.iterrows()],
        "state": [_tr("sku_state_active") if bool(a) else _tr("sku_state_archived") for a in view["is_active"]],
        "comment": [as_text(c) for c in view["comment"]],
    })
    options = [int(i) for i in view["id"]]
    picked = dict_kit.table_pick(lst, options, "plat_list", (search, state_sel), column_config={
        "short": st.column_config.TextColumn(_tr("plat_short"), width=140),
        "name": st.column_config.TextColumn(_tr("plat_name"), width="medium"),
        "mps": st.column_config.TextColumn(_tr("plat_col_mps"), width="large", help=_tr("plat_col_mps_help")),
        "labels": st.column_config.TextColumn(_tr("plat_col_labels"), width="medium",
                                              help=_tr("plat_col_labels_help")),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=90),
        "comment": st.column_config.TextColumn(_tr("plat_comment"), width="medium"),
    })
    st.caption(_tr("plat_list_empty") if lst.empty else _tr("plat_list_hint"))
    if options:
        labels = {int(r.id): f"{r.short_name} — {r.full_name}" + ("" if r.is_active else f" · {_tr('wh_inactive')}")
                  for _, r in view.iterrows()}
        st.markdown("#### " + _tr("plat_card_h"))
        sel = dict_kit.card_pick(_tr("plat_pick"), options, labels, "plat_card", picked)
        _plat_card(plats.set_index("id").loc[sel], int(sel), plats, mp_cnt)

    _plat_add_form(plats)


def _plat_card(row, sel: int, plats, mp_cnt):
    can_edit = auth.can("dict.edit")
    total = int(mp_cnt["total"].get(row["short_name"], 0)) if row["short_name"] in mp_cnt.index else 0
    active = int(mp_cnt["active"].get(row["short_name"], 0)) if row["short_name"] in mp_cnt.index else 0
    box = st.container(border=True)
    with box:
        st.markdown(f"**{row['short_name']} · {row['full_name']}**"
                    + ("" if bool(row["is_active"]) else f"  \n{_tr('plat_is_archived')}"))
        st.caption(f"ID {sel} · " + _trf("plat_off_mps", n=total, a=active))

        c1, c2 = st.columns([1, 2])
        # краткое название входит в код каждого маркетплейса и во внешний ключ: пока на площадку
        # ссылаются маркетплейсы, переименование не даст база, и честнее сказать это сразу
        if total:
            c1.text_input(_tr("plat_short"), value=row["short_name"], disabled=True,
                          key=f"ps_{sel}", help=_trf("plat_short_locked", n=total))
            new_short = row["short_name"]
        else:
            new_short = c1.text_input(_tr("plat_short"), value=row["short_name"], key=f"ps_{sel}",
                                      help=_tr("plat_short_help"))
        new_name = c2.text_input(_tr("plat_name"), value=row["full_name"] or "", key=f"pn_{sel}",
                                 help=_tr("plat_name_help"))
        new_cmt = st.text_input(_tr("plat_comment"), value=row["comment"] or "", key=f"pc2_{sel}",
                                help=_tr("plat_comment_help"))

        st.markdown("##### " + _tr("plat_labels"))
        st.caption(_tr("plat_labels_hint"))
        l1, l2, l3 = st.columns(3)
        new_vg = l1.text_input(_tr("plat_vg"), value=row["variation_group_label"] or "",
                               placeholder=_tr("plat_vg_ph"), key=f"pvg_{sel}", help=_tr("plat_vg_help"))
        new_var = l2.text_input(_tr("plat_var"), value=row["variation_label"] or "",
                                placeholder=_tr("plat_var_ph"), key=f"pvar_{sel}", help=_tr("plat_var_help"))
        new_pe = l3.text_input(_tr("plat_peid"), value=row["product_entity_label"] or "",
                               placeholder=_tr("plat_peid_ph"), key=f"ppe_{sel}", help=_tr("plat_peid_help"))
        new_fmt = st.text_input(_tr("plat_peid_fmt"), value=row["peid_format_hint"] or "",
                                placeholder=_tr("plat_peid_fmt_ph"), key=f"pfmt_{sel}",
                                help=_tr("plat_peid_fmt_help"))

        if st.button(_tr("save"), key=f"plat_save_{sel}", type="primary", disabled=not can_edit,
                     help=None if can_edit else _tr("sku_ro_help")):
            short = (new_short or "").strip().upper()
            errs = []
            if not SHORT_RE.match(short):
                errs.append(_tr("plat_short_bad"))
            if not (new_name or "").strip():
                errs.append(_tr("plat_name_empty"))
            if short != row["short_name"] and short in set(plats["short_name"]):
                errs.append(_tr("plat_short_dup"))
            if errs:
                for e in errs:
                    st.error(e)
            else:
                stmts, log = [], []
                if short != row["short_name"]:
                    stmts.append(("UPDATE kabinet_data.platforms SET short_name = %s WHERE id = %s", (short, sel)))
                    log.append(("short_name", row["short_name"], short))
                if (new_name or "").strip() != (row["full_name"] or ""):
                    stmts.append(("UPDATE kabinet_data.platforms SET full_name = %s WHERE id = %s",
                                  (new_name.strip(), sel)))
                    log.append(("full_name", row["full_name"], new_name.strip()))
                fields = {"comment": new_cmt or None, "variation_group_label": new_vg or None,
                          "variation_label": new_var or None, "product_entity_label": new_pe or None,
                          "peid_format_hint": new_fmt or None}
                changed = {k: v for k, v in fields.items() if not _same(row[k], v)}
                if changed:
                    sets = ", ".join(f"{k} = %s" for k in changed)
                    stmts.append(("INSERT INTO kabinet_data.platform_attributes (platform_id) VALUES (%s) "
                                  "ON CONFLICT (platform_id) DO NOTHING", (sel,)))
                    stmts.append((f"UPDATE kabinet_data.platform_attributes SET {sets}, updated_at = now(), "
                                  f"updated_by = 'kabinet' WHERE platform_id = %s",
                                  tuple(changed.values()) + (sel,)))
                    log += [(k, row[k], v) for k, v in changed.items()]
                if not stmts:
                    st.info(_tr("nochange"))
                else:
                    stmts += [(MPLOG, ("platform", sel, f, None if pd.isna(o) else str(o),
                                       None if v is None else str(v))) for f, o, v in log]
                    try:
                        exec_sql(stmts); st.cache_data.clear(); st.success(_tr("plat_saved")); st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))

    if can_edit:
        _plat_archive(row, sel)

    if total:
        st.markdown("##### " + _tr("plat_mps"))
        st.dataframe(q1("""SELECT code, name, country_alpha2 AS country, currency, is_active
                           FROM kabinet_data.marketplaces_new WHERE platform_short = %s ORDER BY code""",
                        (row["short_name"],)),
                     hide_index=True, use_container_width=True)

    with st.expander(_tr("mp_log")):
        lg = q1("""SELECT changed_at, field, old_value, new_value, actor
                   FROM kabinet_data.marketplace_change_log
                   WHERE object_type = 'platform' AND object_id = %s
                   ORDER BY changed_at DESC LIMIT 200""", (sel,))
        if lg.empty:
            st.caption(_tr("mp_log_empty"))
        else:
            lg["changed_at"] = pd.to_datetime(lg["changed_at"]).dt.strftime("%d.%m.%Y %H:%M")
            lg.columns = [_tr("mp_log_when"), _tr("mp_log_field"), _tr("mp_log_old"),
                          _tr("mp_log_new"), _tr("mp_log_who")]
            st.dataframe(lg, hide_index=True, use_container_width=True,
                         height=min(320, 38 + 35 * len(lg)))


def _plat_active_deps(short: str) -> list:
    """Что показать перед архивом площадки (ТЗ 003 §7): действующие связи площадки и всех её маркетплейсов."""
    r = q_now("""
        WITH m AS (SELECT id, code FROM kabinet_data.marketplaces_new WHERE platform_short = %s)
        SELECT (SELECT count(*) FROM kabinet_data.marketplaces_new WHERE platform_short = %s AND is_active) AS mps,
               (SELECT count(*) FROM kabinet_data.assortment_admissions a
                 WHERE a.removed_on IS NULL
                   AND ((a.level = 'platform' AND a.platform = %s)
                        OR (a.level = 'marketplace' AND a.marketplace_id IN (SELECT id FROM m)))) AS adm,
               (SELECT count(*) FROM kabinet_data.pool_members
                 WHERE marketplace_id IN (SELECT id FROM m)
                   AND (valid_to IS NULL OR valid_to > CURRENT_DATE)) AS pools,
               (SELECT count(*) FROM kabinet_data.forecast_register
                 WHERE object_type = 'marketplace' AND object_id IN (SELECT id FROM m) AND is_current) AS fc,
               (SELECT count(*) FROM kabinet_data.product_entities
                 WHERE marketplace_id IN (SELECT id FROM m) AND is_active IS NOT FALSE) AS peid,
               (SELECT count(*) FROM kabinet_data.incidents i
                 WHERE i.status IN ('open', 'acknowledged')
                   AND EXISTS (SELECT 1 FROM m WHERE i.message LIKE '%%:' || m.code || '/%%')) AS alerts
    """, (short, short, short))
    out = []
    for col, key in (("mps", "plat_adep_mps"), ("adm", "mp_adep_matrix"), ("pools", "mp_dep_pool"),
                     ("fc", "mp_adep_fc"), ("peid", "mp_dep_peid"), ("alerts", "mp_dep_alerts")):
        n = int(r[col].iloc[0])
        if n:
            out.append(_trf(key, n=n))
    return out


def _plat_archive(row, sel: int):
    """В архив / вернуть из архива (ТЗ 003 §6–§7). Удаления нет. Архив площадки не трогает её
    маркетплейсы и их данные: он закрывает площадку для НОВЫХ операций (выбор в формах идёт через
    `v_marketplaces_selectable`), а всё существующее остаётся как есть."""
    box = st.container(border=True)
    box.markdown("**" + _tr("mp_act_h") + "**")
    flag = f"plat_arch_ask_{sel}"
    if not bool(row["is_active"]):
        box.caption(_tr("plat_restore_note"))
        if box.button(_tr("mp_act_restore"), key=f"plat_rest_{sel}"):
            _plat_set_active(row, sel, True)
        return
    if not st.session_state.get(flag):
        box.caption(_tr("plat_off_note"))
        if box.button(_tr("mp_act_archive"), key=f"plat_arch_{sel}"):
            st.session_state[flag] = True
            st.rerun()
        return
    deps = _plat_active_deps(row["short_name"])
    if deps:
        box.warning(_tr("mp_off_deps") + ":\n\n" + "\n".join(f"- {d}" for d in deps)
                    + "\n\n" + _tr("plat_off_deps_tail"))
    else:
        box.info(_tr("mp_off_nodeps"))
    c1, c2 = box.columns(2)
    if c1.button(_tr("mp_act_archive_yes"), key=f"plat_arch_yes_{sel}", type="primary"):
        st.session_state.pop(flag, None)
        _plat_set_active(row, sel, False)
    if c2.button(_tr("del_confirm_no"), key=f"plat_arch_no_{sel}"):
        st.session_state.pop(flag, None)
        st.rerun()


def _plat_set_active(row, sel: int, active: bool):
    try:
        exec_sql([("INSERT INTO kabinet_data.platform_attributes (platform_id) VALUES (%s) "
                   "ON CONFLICT (platform_id) DO NOTHING", (sel,)),
                  ("UPDATE kabinet_data.platform_attributes SET is_active = %s, updated_at = now(), "
                   "updated_by = 'kabinet' WHERE platform_id = %s", (active, sel)),
                  (MPLOG, ("platform", sel, "is_active", str(bool(row["is_active"])), str(active)))])
        st.cache_data.clear()
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _plat_add_form(plats):
    """Создание площадки (ТЗ 003 §3): краткое название и название обязательны, обозначения ассортиментной
    структуры — по необходимости, сразу активна. Запись журнала привязана к id новой площадки — раньше
    создание писалось с id 0 и ни к какой площадке не относилось."""
    st.markdown("#### " + _tr("plat_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("plat_ro_add"))
        return
    st.caption(_tr("plat_add_note"))
    with st.form("plat_add_form", clear_on_submit=False):
        a1, a2 = st.columns([1, 2])
        n_short = a1.text_input(_tr("plat_short") + " *", help=_tr("plat_short_help"), key="plat_add_short",
                                placeholder="AMZ")
        n_name = a2.text_input(_tr("plat_name") + " *", help=_tr("plat_name_help"), key="plat_add_name",
                               placeholder="Amazon")
        n_cmt = st.text_input(_tr("plat_comment"), help=_tr("plat_comment_help"), key="plat_add_cmt")
        st.caption(_tr("plat_labels_hint"))
        l1, l2, l3 = st.columns(3)
        n_vg = l1.text_input(_tr("plat_vg"), placeholder=_tr("plat_vg_ph"), help=_tr("plat_vg_help"),
                             key="plat_add_vg")
        n_var = l2.text_input(_tr("plat_var"), placeholder=_tr("plat_var_ph"), help=_tr("plat_var_help"),
                              key="plat_add_var")
        n_pe = l3.text_input(_tr("plat_peid"), placeholder=_tr("plat_peid_ph"), help=_tr("plat_peid_help"),
                             key="plat_add_pe")
        n_fmt = st.text_input(_tr("plat_peid_fmt"), placeholder=_tr("plat_peid_fmt_ph"),
                              help=_tr("plat_peid_fmt_help"), key="plat_add_fmt")
        go = st.form_submit_button(_tr("plat_create"), type="primary")
    if not go:
        return
    short = (n_short or "").strip().upper()
    errs = []
    if not SHORT_RE.match(short):
        errs.append(_tr("plat_short_bad"))
    if not (n_name or "").strip():
        errs.append(_tr("plat_name_empty"))
    if short and not q_now("SELECT 1 FROM kabinet_data.platforms WHERE short_name = %s", (short,)).empty:
        errs.append(_tr("plat_short_dup"))
    if errs:
        for e in errs:
            st.error(e)
        return
    v = lambda x: (x or "").strip() or None
    try:
        # одна команда: площадка, её реквизиты и запись журнала с её настоящим id
        exec_sql([("""
            WITH p AS (INSERT INTO kabinet_data.platforms (short_name, full_name) VALUES (%s, %s) RETURNING id),
                 a AS (INSERT INTO kabinet_data.platform_attributes
                           (platform_id, is_active, comment, variation_group_label, variation_label,
                            product_entity_label, peid_format_hint, updated_by)
                       SELECT id, true, %s, %s, %s, %s, %s, %s FROM p)
            INSERT INTO kabinet_data.marketplace_change_log (object_type, object_id, field, old_value, new_value, actor)
            SELECT 'platform', id, 'created', NULL, %s, %s FROM p
        """, (short, n_name.strip(), v(n_cmt), v(n_vg), v(n_var), v(n_pe), v(n_fmt), _actor(),
              f"{short} · {n_name.strip()}", _actor()))])
        st.cache_data.clear()
        new_id = q_now("SELECT id FROM kabinet_data.platforms WHERE short_name = %s", (short,))
        if not new_id.empty:
            dict_kit.card_focus("plat_card", int(new_id["id"].iloc[0]))
        st.session_state["plat_created_code"] = short
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


# ------------------------------------------------------------------ пулы ---
# Справочник по общему приёму (07.10.2026): инструкция → список с поиском и фильтрами → карточка по клику →
# форма создания. Правила — ТЗ 004 v0.2 без изменений. Отдельного признака «Активен» у пула нет (§9): пул
# ДЕЙСТВУЕТ, пока у него не меньше двух действующих связей. Пул с историей физически не удаляется (§10) — его
# действие прекращается датами окончания связей; удалить можно только пул без связей и без ссылок.
#
# Даты участия на экране — «с» и «последний день участия» включительно (§4: «после этой даты не учитывается»),
# а в базе `valid_to` — первый день БЕЗ пула (полуоткрытый период, как читают все потребители состава).
# Поэтому при записи к последнему дню прибавляется день, при показе — вычитается.
PLOG = ("INSERT INTO kabinet_data.pool_change_log (pool_id, link_id, action, before_state, after_state, actor) "
        "VALUES (%s, %s, %s, %s::jsonb, %s::jsonb, %s)")


def _pool_links() -> pd.DataFrame:
    return q("""
        SELECT pm.id, pm.pool_id, pm.marketplace_id, pm.valid_from, pm.valid_to,
               m.code, m.name AS mp_name, m.country_alpha2 AS country, m.is_active AS mp_active
        FROM kabinet_data.pool_members pm
        JOIN kabinet_data.marketplaces_new m ON m.id = pm.marketplace_id
        ORDER BY pm.valid_from, m.code
    """)


def _pool_usage() -> pd.DataFrame:
    """Где пул используется — и для колонки списка, и для запрета удаления (§10)."""
    try:
        return q("""
            SELECT p.id,
                   (SELECT count(*) FROM kabinet_data.forecast_documents d
                     WHERE d.object_type = 'pool' AND d.object_id = p.id)::int                      AS docs,
                   (SELECT count(*) FROM kabinet_data.forecast_register r
                     WHERE r.object_type = 'pool' AND r.object_id = p.id AND r.is_current)::int    AS fc_rows,
                   (SELECT count(*) FROM kabinet_data.coverage_norm_rules n WHERE n.pool_id = p.id)::int
                 + (SELECT count(*) FROM kabinet_data.coverage_norms n2 WHERE n2.pool_id = p.id)::int AS norms,
                   (SELECT count(*) FROM kabinet_data.warehouse_priorities w
                     WHERE w.target_type = 'pool' AND w.target_id = p.id)::int                      AS prios,
                   (SELECT count(*) FROM kabinet_data.forecast_alert_rules a
                     WHERE a.object_type = 'pool' AND a.object_id = p.id)::int                      AS alert_rules,
                   (SELECT count(*) FROM kabinet_data.v_forecast_pool_drift v WHERE v.pool_id = p.id)::int AS drift
            FROM kabinet_data.pools p
        """).set_index("id")
    except Exception:
        return pd.DataFrame(columns=["docs", "fc_rows", "norms", "prios", "alert_rules", "drift"])


def _link_state(r, today) -> str:
    """active — участвует сегодня, future — начнёт позже, past — история (§4, период полуоткрытый)."""
    vf = pd.Timestamp(r["valid_from"]).date()
    vt = None if pd.isna(r["valid_to"]) else pd.Timestamp(r["valid_to"]).date()
    if vf > today:
        return "future"
    if vt is not None and vt <= today:
        return "past"
    return "active"


def _last_day(vt):
    """`valid_to` базы (первый день без пула) → последний день участия для экрана."""
    return None if vt is None or pd.isna(vt) else (pd.Timestamp(vt) - pd.Timedelta(days=1)).date()


def _vt_from_last(d_last):
    return None if d_last is None else d_last + timedelta(days=1)


def _pool_usage_text(u) -> str:
    if u is None:
        return ""
    parts = []
    for k in ("docs", "fc_rows", "norms", "prios", "alert_rules"):
        n = int(u.get(k, 0) or 0)
        if n:
            parts.append(_trf(f"pool_use_{k}", n=n))
    return "; ".join(parts) or _tr("pool_use_none")


def _pool_link_errors(pid, mp_id, d_from, d_last, exclude_link=None) -> list:
    """Проверки связи «пул → маркетплейс» ДО записи — те же, что держит триггер базы, но словами (§2, §4, §5, §8).
    Читается через `q_now`: десятиминутный кеш разрешил бы то, что уже нельзя."""
    errs = []
    if d_from is None:
        errs.append(_tr("pool_e_from"))
        return errs
    if d_last is not None and d_last < d_from:
        errs.append(_tr("pool_e_order"))
        return errs
    vt = _vt_from_last(d_last)
    ex = int(exclude_link) if exclude_link is not None else -1
    busy = q_now("""
        SELECT p.name AS pool_name, pm.pool_id, pm.valid_from, pm.valid_to
        FROM kabinet_data.pool_members pm JOIN kabinet_data.pools p ON p.id = pm.pool_id
        WHERE pm.marketplace_id = %s AND pm.id <> %s
          AND daterange(pm.valid_from, pm.valid_to, '[)') && daterange(%s::date, %s::date, '[)')
    """, (int(mp_id), ex, d_from, vt))
    for _, r in busy.iterrows():
        per = f"{pd.Timestamp(r.valid_from):%d.%m.%Y}–" + (
            f"{_last_day(r.valid_to):%d.%m.%Y}" if pd.notna(r.valid_to) else _tr("pool_open"))
        errs.append(_trf("pool_e_same" if int(r.pool_id) == int(pid) else "pool_e_other",
                         pool=r.pool_name, per=per))
    # §2: страна нового участника = страна остальных участников, чьё участие пересекается с этим периодом
    me = q_now("SELECT country_alpha2 FROM kabinet_data.marketplaces_new WHERE id = %s", (int(mp_id),))
    others = q_now("""
        SELECT DISTINCT m.country_alpha2 AS c
        FROM kabinet_data.pool_members pm JOIN kabinet_data.marketplaces_new m ON m.id = pm.marketplace_id
        WHERE pm.pool_id = %s AND pm.id <> %s AND pm.marketplace_id <> %s
          AND daterange(pm.valid_from, pm.valid_to, '[)') && daterange(%s::date, %s::date, '[)')
    """, (int(pid), ex, int(mp_id), d_from, vt))
    my_c = as_text(me["country_alpha2"].iloc[0]) if not me.empty else ""
    oth = sorted({as_text(c) for c in others["c"]} - {""}) if not others.empty else []
    if oth and (len(oth) > 1 or oth[0] != my_c):
        errs.append(_tr("pool_e_country") + " " + _trf("pool_e_country_d", mine=my_c or "—", them=", ".join(oth)))
    return errs


def _section_pool():
    dict_kit.instruction(_tr("pool_about"), _tr("pool_about_hint"))
    _created = st.session_state.pop("pool_created_name", None)
    if _created:
        st.success(_trf("pool_created_ok", name=_created))
    today = date.today()
    pools = q("SELECT id, name, comment FROM kabinet_data.pools ORDER BY name")
    links = _pool_links()
    usage = _pool_usage()
    if not links.empty:
        links["state"] = [_link_state(r, today) for _, r in links.iterrows()]
    else:
        links["state"] = pd.Series(dtype=str)

    summary = []
    for _, p in pools.iterrows():
        L = links[links["pool_id"] == p["id"]]
        act, fut = L[L["state"] == "active"], L[L["state"] == "future"]
        cur = pd.concat([act, fut])
        countries = sorted({as_text(c) for c in (cur if not cur.empty else L)["country"]} - {""})
        u = usage.loc[int(p["id"])] if int(p["id"]) in usage.index else None
        summary.append(dict(
            id=int(p["id"]), name=p["name"], acting=len(act) >= 2, country=", ".join(countries),
            members=", ".join(act["code"]),
            future=", ".join(f"{r.code} {_tr('pool_from_short')} {pd.Timestamp(r.valid_from):%d.%m}" for _, r in fut.iterrows()),
            history=int((L["state"] == "past").sum()), used=_pool_usage_text(u),
            drift=bool(u is not None and int(u.get("drift", 0) or 0)), comment=as_text(p["comment"]),
            codes=" ".join(L["code"])))
    sm = pd.DataFrame(summary, columns=["id", "name", "acting", "country", "members", "future", "history",
                                        "used", "drift", "comment", "codes"])

    f1, f2, f3 = st.columns([2, 1, 1])
    search = dict_kit.search_input(_tr("pool_search"), "pool_search", _tr, "Spain, AMZ-ES…", where=f1)
    state_sel = f2.selectbox(_tr("pool_state_f"), ["all", "acting", "not_acting"], key="pool_state_f",
                             format_func=lambda x: _tr(f"pool_state_{x}"))
    ctry_opts = sorted({c.strip() for cs in sm["country"] for c in cs.split(",") if c.strip()})
    ctry_sel = f3.selectbox(_tr("pool_country_f"), ["*"] + ctry_opts, key="pool_country_f",
                            format_func=lambda x: _tr("pool_all") if x == "*" else x)
    view = sm.copy()
    if search:
        view = view[view["name"].str.contains(search, case=False, na=False, regex=False)
                    | view["codes"].str.contains(search, case=False, na=False, regex=False)]
    if state_sel != "all":
        view = view[view["acting"] == (state_sel == "acting")]
    if ctry_sel != "*":
        view = view[view["country"].str.contains(ctry_sel, na=False, regex=False)]
    st.caption(_trf("pool_summary", shown=len(view), total=len(sm), acting=int(sm["acting"].sum()) if len(sm) else 0))

    lst = pd.DataFrame({
        "name": view["name"],
        "state": [(_tr("pool_state_acting") + (" ⚠️" if d else "")) if a else _tr("pool_state_not_acting")
                  for a, d in zip(view["acting"], view["drift"])],
        "country": view["country"], "members": view["members"], "future": view["future"],
        "history": view["history"].astype(int), "used": view["used"], "comment": view["comment"],
    })
    options = [int(i) for i in view["id"]]
    picked = dict_kit.table_pick(lst, options, "pool_list", (search, state_sel, ctry_sel), column_config={
        "name": st.column_config.TextColumn(_tr("pool_name"), width="medium"),
        "state": st.column_config.TextColumn(_tr("pool_col_state"), width=130, help=_tr("pool_col_state_help")),
        "country": st.column_config.TextColumn(_tr("pool_col_country"), width=80),
        "members": st.column_config.TextColumn(_tr("pool_col_members"), width="medium", help=_tr("pool_col_members_help")),
        "future": st.column_config.TextColumn(_tr("pool_col_future"), width="small", help=_tr("pool_col_future_help")),
        "history": st.column_config.NumberColumn(_tr("pool_col_history"), width=90, help=_tr("pool_col_history_help")),
        "used": st.column_config.TextColumn(_tr("pool_col_used"), width="large", help=_tr("pool_col_used_help")),
        "comment": st.column_config.TextColumn(_tr("pool_comment"), width="medium"),
    })
    st.caption(_tr("pool_list_empty") if lst.empty else _tr("pool_list_hint"))
    if options:
        labels = {int(r.id): f"{r.name} · " + (_tr("pool_state_acting") if r.acting else _tr("pool_state_not_acting"))
                  for _, r in view.iterrows()}
        st.markdown("#### " + _tr("pool_card_h"))
        sel = dict_kit.card_pick(_tr("pool_pick"), options, labels, "pool_card", picked)
        prow = pools.set_index("id").loc[sel]
        u = usage.loc[sel] if sel in usage.index else None
        _pool_card(prow, int(sel), links[links["pool_id"] == sel].copy(), u, today)

    _pool_add_form()


def _pool_card(prow, pid: int, L: pd.DataFrame, u, today):
    can_edit = auth.can("dict.edit")
    n_act = int((L["state"] == "active").sum()) if not L.empty else 0
    acting = n_act >= 2
    cur = L[L["state"].isin(["active", "future"])] if not L.empty else L
    countries = sorted({as_text(c) for c in (cur if not cur.empty else L)["country"]} - {""}) if not L.empty else []
    with st.container(border=True):
        st.markdown(f"**{prow['name']}** · " + (_tr("pool_state_acting") if acting else _tr("pool_state_not_acting")))
        st.caption(f"ID {pid} · {_tr('pool_col_country')}: {', '.join(countries) or '—'} · "
                   f"{_tr('pool_col_used')}: {_pool_usage_text(u)}")
        if not acting:
            st.warning(_trf("pool_not_acting_warn", n=n_act))
        if u is not None and int(u.get("drift", 0) or 0):
            st.warning(_tr("pool_drift_warn"))

        # ── реквизиты ──
        c1, c2 = st.columns([1, 2])
        new_name = c1.text_input(_tr("pool_name") + " *", value=prow["name"], key=f"pn_{pid}", help=_tr("pool_name_help"))
        new_cmt = c2.text_input(_tr("pool_comment"), value=as_text(prow["comment"]), key=f"pcm_{pid}",
                                help=_tr("pool_comment_help"))
        if st.button(_tr("pool_save_attrs"), key=f"psa_{pid}", disabled=not can_edit):
            nm, cm = (new_name or "").strip(), (new_cmt or "").strip() or None
            if not nm:
                st.error(_tr("pool_empty_name"))
            elif nm != prow["name"] and not q_now(
                    "SELECT 1 FROM kabinet_data.pools WHERE lower(name) = lower(%s) AND id <> %s", (nm, pid)).empty:
                st.error(_trf("pool_e_dup", name=nm))
            elif nm == prow["name"] and cm == (as_text(prow["comment"]) or None):
                st.info(_tr("nochange"))
            else:
                before = {"name": prow["name"], "comment": as_text(prow["comment"]) or None}
                try:
                    exec_sql([("UPDATE kabinet_data.pools SET name = %s, comment = %s, updated_at = now() WHERE id = %s",
                               (nm, cm, pid)),
                              (PLOG, (pid, None, "rename" if nm != prow["name"] else "comment",
                                      json.dumps(before, ensure_ascii=False),
                                      json.dumps({"name": nm, "comment": cm}, ensure_ascii=False), _actor()))])
                    st.cache_data.clear()
                    st.success(_tr("saved").format(n=1))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

        # ── состав и история участия ──
        st.markdown("##### " + _tr("pool_members"))
        st.caption(_tr("pool_members_hint"))
        if L.empty:
            st.info(_tr("pool_no_links"))
        else:
            t = pd.DataFrame({
                "mp": [f"{r.code} · {as_text(r.mp_name)}" + ("" if bool(r.mp_active) else f" ({_tr('wh_inactive')})")
                       for _, r in L.iterrows()],
                "country": L["country"].map(as_text),
                "from": [pd.Timestamp(v).strftime("%d.%m.%Y") for v in L["valid_from"]],
                "last": [(_last_day(v).strftime("%d.%m.%Y") if pd.notna(v) else _tr("pool_open")) for v in L["valid_to"]],
                "state": [_tr(f"pool_link_{s}") for s in L["state"]],
            })
            st.dataframe(t, hide_index=True, use_container_width=True, column_config={
                "mp": st.column_config.TextColumn(_tr("pool_c_mp"), width="large"),
                "country": st.column_config.TextColumn(_tr("pool_col_country"), width=80),
                "from": st.column_config.TextColumn(_tr("pool_c_from"), width=110),
                "last": st.column_config.TextColumn(_tr("pool_c_last"), width=150, help=_tr("pool_c_last_help")),
                "state": st.column_config.TextColumn(_tr("pool_col_state"), width=120),
            })

        if can_edit:
            _pool_add_link(pid, L, today)
            if not L.empty:
                _pool_edit_link(pid, L, today)
            if not cur.empty:
                _pool_close(pid, prow["name"], L, today)
        else:
            st.caption(_tr("pool_ro"))

        # ── журнал ──
        with st.expander(_tr("pool_log_h")):
            lg = q_now("""SELECT ts, actor, action, before_state, after_state FROM kabinet_data.pool_change_log
                          WHERE pool_id = %s ORDER BY ts DESC, id DESC LIMIT 200""", (pid,))
            if lg.empty:
                st.caption(_tr("pool_log_empty"))
            else:
                st.dataframe(pd.DataFrame({
                    "ts": pd.to_datetime(lg["ts"], utc=True).dt.tz_convert("Europe/Kyiv").dt.strftime("%d.%m.%Y %H:%M"),
                    "who": lg["actor"], "what": [_tr(f"pool_act_{a}") for a in lg["action"]],
                    "was": [json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else as_text(v) for v in lg["before_state"]],
                    "now": [json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else as_text(v) for v in lg["after_state"]],
                }), hide_index=True, use_container_width=True, column_config={
                    "ts": _tr("pool_l_ts"), "who": _tr("pool_l_who"), "what": _tr("pool_l_what"),
                    "was": _tr("pool_l_was"), "now": _tr("pool_l_now")})

        # ── удаление: только пул без связей и без ссылок (§10) ──
        if can_edit:
            refs = []
            if not L.empty:
                refs.append(_trf("pool_ref_links", n=len(L)))
            ut = _pool_usage_text(u)
            if ut and ut != _tr("pool_use_none"):
                refs.append(ut)
            if refs:
                st.caption(_trf("pool_del_blocked", refs="; ".join(refs)))
            elif confirm_delete(f"pool_{pid}", _trf("pool_del_what", name=prow["name"], n=0)):
                try:
                    exec_sql([("DELETE FROM kabinet_data.pools WHERE id = %s", (pid,)),
                              (PLOG, (pid, None, "delete", json.dumps({"name": prow["name"]}, ensure_ascii=False),
                                      None, _actor()))])
                    st.cache_data.clear()
                    st.success(_tr("pool_deleted"))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))


def _pool_add_link(pid: int, L: pd.DataFrame, today):
    """Добавить маркетплейс в пул (§2, §4, §5, §8, §11): только активные маркетплейсы активных площадок,
    дата начала обязательна (по умолчанию сегодня), последний день — по желанию."""
    with st.expander(_tr("pool_add_link_h")):
        sel_mp = q("SELECT id, code, name, country_alpha2 FROM kabinet_data.v_marketplaces_selectable ORDER BY code")
        busy_now = set(L.loc[L["state"].isin(["active", "future"]), "marketplace_id"].astype(int)) if not L.empty else set()
        opts = [int(i) for i in sel_mp["id"] if int(i) not in busy_now]
        if not opts:
            st.caption(_tr("pool_add_none"))
            return
        lab = {int(r.id): f"{r.code} · {as_text(r.name)} ({as_text(r.country_alpha2)})" for _, r in sel_mp.iterrows()}
        a1, a2, a3 = st.columns([2, 1, 1])
        mp_id = a1.selectbox(_tr("pool_c_mp"), opts, format_func=lambda i: lab.get(i, str(i)), key=f"pal_mp_{pid}",
                             help=_tr("pool_add_mp_help"))
        d_from = a2.date_input(_tr("pool_c_from") + " *", value=today, key=f"pal_f_{pid}", format="DD.MM.YYYY",
                               help=_tr("pool_from_help"))
        d_last = a3.date_input(_tr("pool_c_last"), value=None, key=f"pal_l_{pid}", format="DD.MM.YYYY",
                               help=_tr("pool_last_help"))
        st.caption(_tr("pool_switch_note"))
        if st.button(_tr("pool_add_link_btn"), key=f"pal_b_{pid}", type="primary"):
            errs = _pool_link_errors(pid, mp_id, d_from, d_last)
            if errs:
                for e in errs:
                    st.error(e)
                return
            after = {"marketplace": lab.get(mp_id), "from": str(d_from), "last_day": str(d_last) if d_last else None}
            try:
                exec_sql([("""
                    WITH l AS (INSERT INTO kabinet_data.pool_members (pool_id, marketplace_id, valid_from, valid_to)
                               VALUES (%s, %s, %s, %s) RETURNING id)
                    INSERT INTO kabinet_data.pool_change_log (pool_id, link_id, action, before_state, after_state, actor)
                    SELECT %s, id, 'link_add', NULL, %s::jsonb, %s FROM l
                """, (pid, mp_id, d_from, _vt_from_last(d_last), pid, json.dumps(after, ensure_ascii=False), _actor()))])
                st.cache_data.clear()
                st.success(_trf("pool_link_added", mp=lab.get(mp_id)))
                st.rerun()
            except Exception as e:
                st.error(_trf("err", e=e))


def _pool_edit_link(pid: int, L: pd.DataFrame, today):
    """Изменить даты участия или завершить участие (§4, §6): прекращение — это последний день участия,
    история связи сохраняется."""
    with st.expander(_tr("pool_edit_link_h")):
        lab = {int(r.id): f"{r.code} · {pd.Timestamp(r.valid_from):%d.%m.%Y}–"
               + (f"{_last_day(r.valid_to):%d.%m.%Y}" if pd.notna(r.valid_to) else _tr("pool_open"))
               + f" · {_tr(f'pool_link_{r.state}')}" for _, r in L.iterrows()}
        ids = list(lab.keys())
        lid = st.selectbox(_tr("pool_edit_pick"), ids, format_func=lambda i: lab[i], key=f"pel_{pid}")
        r = L.set_index("id").loc[lid]
        e1, e2 = st.columns(2)
        d_from = e1.date_input(_tr("pool_c_from") + " *", value=pd.Timestamp(r["valid_from"]).date(),
                               key=f"pel_f_{pid}_{lid}", format="DD.MM.YYYY", help=_tr("pool_from_help"))
        d_last = e2.date_input(_tr("pool_c_last"), value=_last_day(r["valid_to"]), key=f"pel_l_{pid}_{lid}",
                               format="DD.MM.YYYY", help=_tr("pool_last_help"))
        st.caption(_tr("pool_switch_note"))
        b1, b2 = st.columns(2)
        save = b1.button(_tr("pool_edit_save"), key=f"pel_s_{pid}_{lid}", type="primary")
        end_today = b2.button(_tr("pool_end_today"), key=f"pel_e_{pid}_{lid}",
                              disabled=r["state"] == "past", help=_tr("pool_end_today_help"))
        if not (save or end_today):
            return
        if end_today:
            d_last = today
        old_from, old_last = pd.Timestamp(r["valid_from"]).date(), _last_day(r["valid_to"])
        if d_from == old_from and d_last == old_last:
            st.info(_tr("nochange"))
            return
        errs = _pool_link_errors(pid, int(r["marketplace_id"]), d_from, d_last, exclude_link=lid)
        if errs:
            for e in errs:
                st.error(e)
            return
        try:
            exec_sql([("UPDATE kabinet_data.pool_members SET valid_from = %s, valid_to = %s WHERE id = %s",
                       (d_from, _vt_from_last(d_last), int(lid))),
                      (PLOG, (pid, int(lid), "link_close" if end_today else "link_dates",
                              json.dumps({"marketplace": r["code"], "from": str(old_from),
                                          "last_day": str(old_last) if old_last else None}, ensure_ascii=False),
                              json.dumps({"marketplace": r["code"], "from": str(d_from),
                                          "last_day": str(d_last) if d_last else None}, ensure_ascii=False),
                              _actor()))])
            st.cache_data.clear()
            st.success(_tr("saved").format(n=1))
            st.rerun()
        except Exception as e:
            st.error(_trf("err", e=e))


def _pool_close(pid: int, name: str, L: pd.DataFrame, today):
    """Прекратить действие пула (§9, §10): у всех действующих связей ставится последний день участия. Сам пул и
    история связей остаются; действующие прогнозы этим не переключаются (§6, §11) — только общей заменой на
    «Прогнозе»."""
    with st.expander(_tr("pool_close_h")):
        st.caption(_tr("pool_close_note"))
        fut = L[L["state"] == "future"]
        if not fut.empty:
            st.warning(_trf("pool_close_future", mps=", ".join(fut["code"])))
            return
        d_last = st.date_input(_tr("pool_c_last") + " *", value=today, key=f"pcl_{pid}", format="DD.MM.YYYY",
                               help=_tr("pool_close_last_help"))
        act = L[L["state"] == "active"]
        early = act[[pd.Timestamp(v).date() > d_last for v in act["valid_from"]]] if not act.empty else act
        flag = f"pool_close_ask_{pid}"
        if not st.session_state.get(flag):
            if st.button(_tr("pool_close_btn"), key=f"pcl_b_{pid}"):
                st.session_state[flag] = True
                st.rerun()
            return
        st.warning(_trf("pool_close_q", name=name, n=len(act), d=d_last.strftime("%d.%m.%Y")))
        y, n = st.columns(2)
        if n.button(_tr("del_confirm_no"), key=f"pcl_n_{pid}"):
            st.session_state.pop(flag, None)
            st.rerun()
        if not y.button(_tr("pool_close_yes"), key=f"pcl_y_{pid}", type="primary"):
            return
        st.session_state.pop(flag, None)
        if not early.empty:
            st.error(_trf("pool_close_early", mps=", ".join(early["code"])))
            return
        try:
            exec_sql([("""UPDATE kabinet_data.pool_members SET valid_to = %s
                          WHERE pool_id = %s AND valid_from <= %s AND (valid_to IS NULL OR valid_to > %s)""",
                       (_vt_from_last(d_last), pid, d_last, d_last)),
                      (PLOG, (pid, None, "pool_close", json.dumps({"active": list(act["code"])}, ensure_ascii=False),
                              json.dumps({"last_day": str(d_last)}, ensure_ascii=False), _actor()))])
            st.cache_data.clear()
            st.success(_trf("pool_closed_ok", name=name))
            st.rerun()
        except Exception as e:
            st.error(_trf("err", e=e))


def _pool_add_form():
    """Создание пула (§2, §3, §4): название обязательно и уникально, участников не меньше двух и все — одной
    страны, дата начала обязательна. Пул, его связи и запись журнала — одной командой."""
    st.markdown("#### " + _tr("pool_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("pool_ro"))
        return
    st.caption(_tr("pool_add_note"))
    sel_mp = q("SELECT id, code, name, country_alpha2 FROM kabinet_data.v_marketplaces_selectable ORDER BY code")
    lab = {int(r.id): f"{r.code} · {as_text(r.name)} ({as_text(r.country_alpha2)})" for _, r in sel_mp.iterrows()}
    ctry = {int(r.id): as_text(r.country_alpha2) for _, r in sel_mp.iterrows()}
    code = {int(r.id): r.code for _, r in sel_mp.iterrows()}
    with st.form("pool_add_form", clear_on_submit=False):
        a1, a2 = st.columns([1, 2])
        n_name = a1.text_input(_tr("pool_name") + " *", help=_tr("pool_name_help"), key="pool_add_name",
                               placeholder="Spain Marketplaces")
        n_cmt = a2.text_input(_tr("pool_comment"), help=_tr("pool_comment_help"), key="pool_add_cmt")
        n_mps = st.multiselect(_tr("pool_add_mps") + " *", list(lab.keys()), format_func=lambda i: lab[i],
                               key="pool_add_mps", help=_tr("pool_add_mps_help"), placeholder=_tr("ph_pick_mp"))
        d1, d2 = st.columns(2)
        d_from = d1.date_input(_tr("pool_c_from") + " *", value=date.today(), key="pool_add_from",
                               format="DD.MM.YYYY", help=_tr("pool_from_help"))
        d_last = d2.date_input(_tr("pool_c_last"), value=None, key="pool_add_last", format="DD.MM.YYYY",
                               help=_tr("pool_last_help"))
        go = st.form_submit_button(_tr("pool_create"), type="primary")
    if not go:
        return
    nm = (n_name or "").strip()
    errs = []
    if not nm:
        errs.append(_tr("pool_empty_name"))
    elif not q_now("SELECT 1 FROM kabinet_data.pools WHERE lower(name) = lower(%s)", (nm,)).empty:
        errs.append(_trf("pool_e_dup", name=nm))
    if len(n_mps) < 2:
        errs.append(_tr("pool_e_two"))
    if len({ctry.get(i) for i in n_mps}) > 1:
        errs.append(_tr("pool_e_country") + " " + _trf("pool_e_country_new",
                    mps=", ".join(f"{code[i]} — {ctry[i]}" for i in n_mps)))
    if d_from is None:
        errs.append(_tr("pool_e_from"))
    elif d_last is not None and d_last < d_from:
        errs.append(_tr("pool_e_order"))
    if not errs:
        for i in n_mps:
            for e in _pool_link_errors(-1, i, d_from, d_last):
                errs.append(f"{code[i]}: {e}")
    if errs:
        for e in errs:
            st.error(e)
        return
    after = {"name": nm, "comment": (n_cmt or "").strip() or None, "members": [code[i] for i in n_mps],
             "from": str(d_from), "last_day": str(d_last) if d_last else None}
    try:
        exec_sql([("""
            WITH p AS (INSERT INTO kabinet_data.pools (name, comment) VALUES (%s, %s) RETURNING id),
                 m AS (INSERT INTO kabinet_data.pool_members (pool_id, marketplace_id, valid_from, valid_to)
                       SELECT p.id, x, %s, %s FROM p, unnest(%s::int[]) AS x)
            INSERT INTO kabinet_data.pool_change_log (pool_id, link_id, action, before_state, after_state, actor)
            SELECT id, NULL, 'create', NULL, %s::jsonb, %s FROM p
        """, (nm, (n_cmt or "").strip() or None, d_from, _vt_from_last(d_last), [int(i) for i in n_mps],
              json.dumps(after, ensure_ascii=False), _actor()))])
        st.cache_data.clear()
        new_id = q_now("SELECT id FROM kabinet_data.pools WHERE name = %s", (nm,))
        if not new_id.empty:
            dict_kit.card_focus("pool_card", int(new_id["id"].iloc[0]))
        st.session_state["pool_created_name"] = nm
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


# ------------------------------------------------------------- нормативы ---
NLOG = ("INSERT INTO kabinet_data.coverage_norm_log (rule_id, action, before_state, after_state, actor, note) "
        "VALUES (%s, %s, %s::jsonb, %s::jsonb, %s, %s)")

# Статусы относительно норматива (ТЗ §9.3) — один словарь на страницу и на «Остатки»
NORM_ST = {"below": "norm_st_below", "norm": "norm_st_norm",
           "above": "norm_st_above", "no_norm": "norm_st_no_norm"}


def _norm_state(r) -> str:
    """Подпись правила: уровень + объект нормирования. Отдельной функцией, потому что
    одна и та же строка нужна и в списке, и в выпадающих списках пересмотра и закрытия."""
    obj = r["sku"] or r["category"] or _tr("norm_lvl_default")
    return f'{obj} · {r["target_name"]}'


def _norm_period_state(r, today) -> str:
    """Состояние версии норматива считается по датам, не хранится: действует / с будущей даты / закрыт."""
    if r["effective_from"] > today:
        return "future"
    if pd.notna(r["effective_to"]) and r["effective_to"] < today:
        return "past"
    return "active"


def _section_norm():
    """Нормативы покрытия по общему приёму справочников (07.10.2026): инструкция → список с поиском и фильтрами →
    карточка по клику (пересмотр новой версией, закрытие датой, журнал правила) → форма «Добавить норматив».
    Правила ТЗ «Остатки» §9 без изменений: дни — единица хранения, три уровня с приоритетом в одной функции базы,
    пересмотр — новая версия, а не правка действующей, удаления нет — только закрытие датой."""
    dict_kit.instruction(_tr("norm_about"), _tr("norm_hint"))
    today = date.today()
    rules = q("""
        SELECT r.id, r.level, r.sku, r.category, r.marketplace_id, r.pool_id,
               COALESCE(m.code, p.name) AS target_name,
               r.min_days, r.target_days, r.max_days,
               r.effective_from, r.effective_to, r.note, r.updated_by, r.updated_at
        FROM kabinet_data.coverage_norm_rules r
        LEFT JOIN kabinet_data.marketplaces_new m ON m.id = r.marketplace_id
        LEFT JOIN kabinet_data.pools p            ON p.id = r.pool_id
        ORDER BY r.effective_from DESC, r.id DESC
    """)
    if not rules.empty:
        rules["state"] = [_norm_period_state(r, today) for _, r in rules.iterrows()]
        rules["is_active"] = rules["state"] == "active"
    active = rules[rules["is_active"]] if not rules.empty else rules

    # Сколько строк покрытия получило норматив в последнем расчёте — ответ на вопрос «а работает ли справочник»:
    # правило можно завести так, что оно не совпадёт ни с одной парой
    used = q("""
        SELECT COALESCE(norm_status, 'no_norm') AS norm_status, count(*)::int AS n
        FROM kabinet_data.coverage_summary
        WHERE calc_date = (SELECT MAX(calc_date) FROM kabinet_data.coverage_summary)
        GROUP BY 1
    """)
    rows_total = int(used["n"].sum()) if not used.empty else 0
    with_norm = int(used.loc[used["norm_status"] != "no_norm", "n"].sum()) if not used.empty else 0
    st.caption(_trf("norm_summary", n=len(active),
                    sku=int((active["level"] == "sku").sum()) if not active.empty else 0,
                    cat=int((active["level"] == "category").sum()) if not active.empty else 0,
                    dflt=int((active["level"] == "default").sum()) if not active.empty else 0,
                    rows=rows_total, with_norm=with_norm))
    if rows_total:
        st.caption(_trf("norm_uses", breakdown=" · ".join(
            f'{_tr(NORM_ST.get(r.norm_status, "norm_st_no_norm"))}: {r.n}'
            for r in used.sort_values("n", ascending=False).itertuples())))
    if active.empty:
        st.info(_tr("norm_empty_register"))

    LVL_SHOW = {"sku": _tr("norm_lvl_sku"), "category": _tr("norm_lvl_category"), "default": _tr("norm_lvl_dflt_short")}
    f1, f2, f3, f4 = st.columns([2, 1, 1, 1])
    needle = dict_kit.search_input(_tr("norm_search"), "norm_search", _tr, _tr("norm_search_ph"), where=f1).lower()
    lvl_sel = f2.selectbox(_tr("norm_level"), ["all", "sku", "category", "default"], key="norm_lvl_f",
                           format_func=lambda x: _tr("ctry_state_all") if x == "all" else LVL_SHOW[x])
    tgt_names = sorted(set(rules["target_name"].dropna())) if not rules.empty else []
    tgt_sel = f3.selectbox(_tr("norm_col_target"), ["all"] + tgt_names, key="norm_tgt_f",
                           format_func=lambda x: _tr("ctry_state_all") if x == "all" else x)
    state_sel = f4.selectbox(_tr("sku_state_f"), ["active", "future", "past", "all"], key="norm_state_f",
                             format_func=lambda x: _tr(f"norm_state_{x}"))
    view = rules
    if not view.empty:
        if needle:
            view = view[view["sku"].fillna("").str.lower().str.contains(needle, regex=False)
                        | view["category"].fillna("").str.lower().str.contains(needle, regex=False)]
        if lvl_sel != "all":
            view = view[view["level"] == lvl_sel]
        if tgt_sel != "all":
            view = view[view["target_name"] == tgt_sel]
        if state_sel != "all":
            view = view[view["state"] == state_sel]
    st.caption(_trf("norm_shown", shown=len(view), total=len(rules)))

    by_rule = q("""
        SELECT norm_rule_id AS id, count(*)::int AS rows_now
        FROM kabinet_data.coverage_summary
        WHERE calc_date = (SELECT MAX(calc_date) FROM kabinet_data.coverage_summary)
          AND norm_rule_id IS NOT NULL GROUP BY 1
    """)
    cnt = {int(r.id): int(r.rows_now) for r in by_rule.itertuples()}
    options = [int(i) for i in view["id"]] if not view.empty else []
    lst = pd.DataFrame({
        "level": [LVL_SHOW.get(x, x) for x in view["level"]] if options else [],
        "object": [as_text(r.sku) or as_text(r.category) or _tr("norm_lvl_dflt_short") for r in view.itertuples()] if options else [],
        "target": list(view["target_name"].fillna("—")) if options else [],
        "days": [f"{int(r.min_days)} – {int(r.target_days)} – {int(r.max_days)}" for r in view.itertuples()] if options else [],
        # период — текстом: пустая дата в таблице рисуется словом «None» (Streamlit 1.64)
        "period": [f'{r.effective_from:%d.%m.%Y} → ' + (f'{r.effective_to:%d.%m.%Y}' if pd.notna(r.effective_to) else '…')
                   for r in view.itertuples()] if options else [],
        "state": [_tr(f"norm_state_{s}") for s in view["state"]] if options else [],
        "rows_now": [num_text(cnt.get(int(i), 0)) for i in view["id"]] if options else [],
        "note": [as_text(x) for x in view["note"]] if options else [],
        "author": [as_text(x) for x in view["updated_by"]] if options else [],
    })
    picked = dict_kit.table_pick(lst, options, "norm_list", (needle, lvl_sel, tgt_sel, state_sel), column_config={
        "level": st.column_config.TextColumn(_tr("norm_level"), width=110),
        "object": st.column_config.TextColumn(_tr("norm_col_object"), width="medium"),
        "target": st.column_config.TextColumn(_tr("norm_col_target"), width=110),
        "days": st.column_config.TextColumn(_tr("norm_col_days"), width=130, help=_tr("norm_days_help")),
        "period": st.column_config.TextColumn(_tr("norm_col_period"), width=180),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=110),
        "rows_now": st.column_config.TextColumn(_tr("norm_col_rows"), width=110, help=_tr("norm_col_rows_help")),
        "note": st.column_config.TextColumn(_tr("norm_note"), width="medium"),
        "author": st.column_config.TextColumn(_tr("col_author"), width="small"),
    })
    st.caption(_tr("norm_list_empty") if not options else _tr("norm_list_hint"))
    if options:
        labels = {int(r["id"]): f'#{int(r["id"])} · {_norm_state(r)} · {_tr("norm_state_" + r["state"])}'
                  for _, r in view.iterrows()}
        st.markdown("#### " + _tr("norm_card_h"))
        sel = dict_kit.card_pick(_tr("norm_pick"), options, labels, "norm_card", picked)
        _norm_card(rules.set_index("id").loc[sel], int(sel), cnt.get(int(sel), 0), today, LVL_SHOW)

    _norm_add_form(today, bool(active.empty))


def _norm_card(row, sel: int, rows_now: int, today, LVL_SHOW):
    can_edit = auth.can("dict.edit")
    r = row.copy(); r["id"] = sel
    with st.container(border=True):
        st.markdown(f'**#{sel} · {_norm_state(r)}**  \n{_tr("norm_state_" + row["state"])}')
        c1, c2, c3 = st.columns(3)
        c1.metric(_tr("col_min"), f'{int(row["min_days"])} {_tr("norm_days_unit")}')
        c2.metric(_tr("col_target"), f'{int(row["target_days"])} {_tr("norm_days_unit")}')
        c3.metric(_tr("col_max"), f'{int(row["max_days"])} {_tr("norm_days_unit")}')
        st.caption(_trf("norm_card_meta", level=LVL_SHOW.get(row["level"], row["level"]),
                        period=f'{row["effective_from"]:%d.%m.%Y} → '
                               + (f'{row["effective_to"]:%d.%m.%Y}' if pd.notna(row["effective_to"]) else '…'),
                        rows=rows_now, who=as_text(row["updated_by"], "—")))
        if as_text(row["note"]):
            st.caption(_tr("norm_note") + ": " + as_text(row["note"]))
        if row["state"] == "active" and not rows_now:
            st.caption(_tr("norm_no_rows"))

    if can_edit and row["state"] == "active":
        with st.container(border=True):
            st.markdown("**" + _tr("norm_revise") + "**")
            st.caption(_tr("norm_revise_hint"))
            r1, r2, r3, r4 = st.columns(4)
            n_mn = r1.number_input(_tr("col_min"), 0, 999, int(row["min_days"]), step=5, key=f"norm_rev_mn_{sel}",
                                   help=_tr("norm_days_help"))
            n_tg = r2.number_input(_tr("col_target"), 0, 999, int(row["target_days"]), step=5, key=f"norm_rev_tg_{sel}")
            n_mx = r3.number_input(_tr("col_max"), 0, 999, int(row["max_days"]), step=5, key=f"norm_rev_mx_{sel}")
            n_from = r4.date_input(_tr("norm_revise_from"), value=today, key=f"norm_rev_from_{sel}",
                                   help=_tr("norm_revise_from_help"))
            n_note = st.text_input(_tr("norm_note"), value=as_text(row["note"]), key=f"norm_rev_note_{sel}").strip() or None
            if st.button(_tr("norm_revise_btn"), type="primary", key=f"norm_rev_btn_{sel}"):
                if not (n_mn <= n_tg <= n_mx):
                    st.error(_tr("norm_order"))
                elif n_from <= row["effective_from"]:
                    st.error(_trf("norm_revise_past", d=f'{row["effective_from"]:%d.%m.%Y}'))
                else:
                    _revise_norm(r, n_mn, n_tg, n_mx, n_from, n_note)

        with st.container(border=True):
            st.markdown("**" + _tr("norm_close") + "**")
            st.caption(_tr("norm_close_hint"))
            c_date = st.date_input(_tr("norm_close_date"), value=today, key=f"norm_cls_date_{sel}")
            if c_date < row["effective_from"]:
                st.error(_trf("norm_revise_past", d=f'{row["effective_from"]:%d.%m.%Y}'))
            elif confirm_delete(f"normclose_{sel}", _trf("norm_close_what", id=sel, what=_norm_state(r),
                                                         d=f"{c_date:%d.%m.%Y}")):
                _close_norm(r, c_date)
    elif row["state"] != "active":
        st.caption(_tr("norm_ro_state"))

    with st.expander(_tr("ctry_log")):
        lg = q1("""SELECT changed_at, action, actor, note FROM kabinet_data.coverage_norm_log
                   WHERE rule_id = %s ORDER BY changed_at DESC LIMIT 100""", (sel,))
        if lg.empty:
            st.caption(_tr("norm_log_none"))
        else:
            lg["changed_at"] = pd.to_datetime(lg["changed_at"]).dt.strftime("%d.%m.%Y %H:%M")
            lg["action"] = [_tr(f"norm_act_{a}") if a in ("created", "closed") else a for a in lg["action"]]
            lg.columns = [_tr("mp_log_when"), _tr("norm_log_action"), _tr("mp_log_who"), _tr("norm_note")]
            st.dataframe(lg, hide_index=True, use_container_width=True, height=min(260, 38 + 35 * len(lg)))


def _norm_add_form(today, expanded: bool):
    """Новый норматив: уровень, объект, привязка, три порога в днях, дата начала. Пересечение периодов по той же
    связке не пускает триггер базы — его текст показывается как есть."""
    st.markdown("#### " + _tr("norm_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("norm_ro_add"))
        return
    st.caption(_tr("norm_add_note"))
    mps_n = q("""SELECT id, code, country_alpha2 AS country FROM kabinet_data.v_marketplaces_selectable ORDER BY code""")
    pools_n = q("SELECT id, name FROM kabinet_data.pools ORDER BY name") if has_table("kabinet_data.pools") \
        else pd.DataFrame(columns=["id", "name"])
    cats = q("""
        SELECT category, count(*)::int AS skus FROM kabinet_data.sku_categories
        WHERE effective_to IS NULL AND data_quality_status IS NULL
        GROUP BY 1 ORDER BY 1
    """)
    skus_n = q("SELECT s.sku, s.name FROM kabinet_data.sku_master s WHERE s.is_active ORDER BY s.sku")
    mp_opts = {f'{r.code} ({r.country})': int(r.id) for r in mps_n.itertuples()}
    pool_opts = {r.name: int(r.id) for r in pools_n.itertuples()}
    sku_title = {r.sku: (f"{r.sku} — {r.name}" if r.name else r.sku) for r in skus_n.itertuples()}

    LVL = {"sku": _tr("norm_lvl_sku"), "category": _tr("norm_lvl_category"), "default": _tr("norm_lvl_default")}
    lvl = st.radio(_tr("norm_level") + " *", list(LVL), format_func=LVL.get, horizontal=True, key="norm_lvl",
                   help=_tr("norm_level_help"))
    a1, a2 = st.columns([2, 2])
    sku_val = cat_val = None
    if lvl == "sku":
        manual = a1.checkbox(_tr("norm_manual"), key="norm_manual")
        if manual or skus_n.empty:
            sku_val = a1.text_input(_tr("norm_sku") + " *", key="norm_sku_txt", help=_tr("norm_sku_help")).strip()
        else:
            sku_val = a1.selectbox(_tr("norm_sku") + " *", list(sku_title), format_func=sku_title.get,
                                   key="norm_sku_sel", help=_tr("norm_sku_help"))
    elif lvl == "category":
        if cats.empty:
            a1.caption(_tr("norm_cat_none"))
        else:
            cat_val = a1.selectbox(_tr("norm_category") + " *", list(cats["category"]),
                                   format_func=lambda c: f"{c} ({int(cats.loc[cats['category'] == c, 'skus'].iloc[0])})",
                                   key="norm_cat_sel")
            a1.caption(_trf("norm_cat_hint", n=int(cats["skus"].sum())))
    if not pool_opts:
        a2.caption(_tr("norm_no_pools"))
        is_mp = True
    else:
        is_mp = a2.selectbox(_tr("norm_target") + " *", [_tr("norm_target_mp"), _tr("norm_target_pool")],
                             key="norm_tgt", help=_tr("norm_target_help")) == _tr("norm_target_mp")
    opts = mp_opts if is_mp else pool_opts
    tgt_val = a2.selectbox(_tr("norm_target_val") + " *", list(opts) or ["—"], key="norm_tgt_val")

    b1, b2, b3, b4 = st.columns(4)
    mn = b1.number_input(_tr("col_min") + " *", 0, 999, 30, step=5, key="norm_mn", help=_tr("norm_days_help"))
    tg = b2.number_input(_tr("col_target") + " *", 0, 999, 60, step=5, key="norm_tg", help=_tr("norm_days_help"))
    mx = b3.number_input(_tr("col_max") + " *", 0, 999, 90, step=5, key="norm_mx", help=_tr("norm_days_help"))
    eff = b4.date_input(_tr("norm_from") + " *", value=today, key="norm_eff", help=_tr("norm_from_help"))
    note = st.text_input(_tr("norm_note"), key="norm_note_new", help=_tr("norm_note_help")).strip() or None

    if st.button(_tr("norm_add_btn"), type="primary", key="norm_add_btn"):
        if lvl == "sku" and not sku_val:
            st.error(_tr("norm_empty"))
        elif lvl == "category" and not cat_val:
            st.error(_tr("norm_cat_none"))
        elif not opts:
            st.error(_tr("norm_no_target"))
        elif not (mn <= tg <= mx):
            st.error(_tr("norm_order"))
        elif lvl == "sku" and sku_val not in sku_title:
            # не отказ, а предупреждение: SKU может появиться позже, но молча норматив
            # на несуществующий артикул не сработает никогда — об этом надо сказать
            st.warning(_trf("norm_sku_unknown", sku=sku_val))
        else:
            _insert_norm(lvl, sku_val, cat_val, opts[tgt_val], is_mp, mn, tg, mx, eff, note)


def _norm_json(row) -> str:
    """Снимок правила для журнала.

    Через `_py`, а не напрямую: из pandas в словарь приезжают numpy-числа и `date`,
    и `json.dumps` на них падает «Object of type int64 is not JSON serializable» —
    поймано при первом же пересмотре норматива (27.09.2026)."""
    d = {k: _py(row[k]) for k in ("level", "sku", "category", "marketplace_id", "pool_id",
                                  "min_days", "target_days", "max_days", "note",
                                  "effective_from", "effective_to")}
    return json.dumps({k: (str(v) if isinstance(v, date) else v) for k, v in d.items()},
                      ensure_ascii=False)


def _insert_norm(lvl, sku_val, cat_val, tid, is_mp, mn, tg, mx, eff, note):
    col = "marketplace_id" if is_mp else "pool_id"
    after = json.dumps({"level": lvl, "sku": sku_val, "category": cat_val,
                        col: int(tid), "min_days": int(mn), "target_days": int(tg),
                        "max_days": int(mx), "effective_from": str(eff), "note": note},
                       ensure_ascii=False)
    try:
        auth.demand("dict.edit", None, "coverage_norm_rules", None)
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute(f"""INSERT INTO kabinet_data.coverage_norm_rules
                                (level, sku, category, {col}, min_days, target_days, max_days,
                                 effective_from, note, updated_by)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id""",
                        (lvl, sku_val, cat_val, int(tid), int(mn), int(tg), int(mx), eff, note, _actor()))
            new_id = cur.fetchone()[0]
            cur.execute(NLOG, (new_id, "created", None, after, _actor(), note))
            conn.commit()
        finally:
            conn.close()
        st.cache_data.clear()
        st.success(_tr("norm_added"))
        st.rerun()
    except Exception as e:
        # пересечение периодов ловит триггер базы: показываем его текст, а не «ошибка сохранения»
        msg = str(e).strip().split("\n")[0]
        st.error(_trf("norm_overlap", e=msg) if "пересекается" in msg else _trf("err", e=msg))


def _revise_norm(cur_row, mn, tg, mx, n_from, note):
    """Новая версия норматива: прежняя закрывается днём раньше — обе операции в одной транзакции.
    Порядок важен: сначала закрыть, потом вставить, иначе запрет пересечения не пустит новую."""
    before = _norm_json(cur_row)
    col = "marketplace_id" if pd.notna(cur_row["marketplace_id"]) else "pool_id"
    tid = int(cur_row["marketplace_id"] if col == "marketplace_id" else cur_row["pool_id"])
    after = json.dumps({"level": cur_row["level"], "sku": cur_row["sku"], "category": cur_row["category"],
                        col: tid, "min_days": int(mn), "target_days": int(tg), "max_days": int(mx),
                        "effective_from": str(n_from), "note": note}, ensure_ascii=False)
    try:
        auth.demand("dict.edit", None, "coverage_norm_rules", int(cur_row["id"]))
        conn = get_connection()
        try:
            cur = conn.cursor()
            cur.execute("UPDATE kabinet_data.coverage_norm_rules SET effective_to = %s, updated_at = now() "
                        "WHERE id = %s", (n_from - timedelta(days=1), int(cur_row["id"])))
            cur.execute(f"""INSERT INTO kabinet_data.coverage_norm_rules
                                (level, sku, category, {col}, min_days, target_days, max_days,
                                 effective_from, note, updated_by)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s) RETURNING id""",
                        (cur_row["level"], cur_row["sku"], cur_row["category"], tid,
                         int(mn), int(tg), int(mx), n_from, note, _actor()))
            new_id = cur.fetchone()[0]
            cur.execute(NLOG, (int(cur_row["id"]), "closed", before, None, _actor(),
                               f"пересмотр: заменён правилом #{new_id}"))
            cur.execute(NLOG, (new_id, "created", before, after, _actor(),
                               f"пересмотр правила #{int(cur_row['id'])}"))
            conn.commit()
        finally:
            conn.close()
        st.cache_data.clear()
        st.success(_trf("norm_revised", d=f"{n_from:%d.%m.%Y}", mn=int(mn), tg=int(tg), mx=int(mx)))
        st.rerun()
    except Exception as e:
        msg = str(e).strip().split("\n")[0]
        st.error(_trf("norm_overlap", e=msg) if "пересекается" in msg else _trf("err", e=msg))


def _close_norm(c_row, c_date):
    try:
        exec_sql([
            ("UPDATE kabinet_data.coverage_norm_rules SET effective_to = %s, updated_at = now() WHERE id = %s",
             [c_date, int(c_row["id"])]),
            (NLOG, [int(c_row["id"]), "closed", _norm_json(c_row), None, _actor(),
                    f"закрыт {c_date}"]),
        ])
        st.cache_data.clear()
        st.success(_trf("norm_closed", d=f"{c_date:%d.%m.%Y}"))
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


# ---------------------------------------------------------- ассортимент ---
# ------------------------------------------------------------------ алерты ---
def _section_alerts():
    st.caption(_tr("al_hint"))
    st.caption(_tr("al_hint2"))

    # Справочник заполняет джоба синка (новые типы из журнала — пустой строкой) и этот
    # экран. Список ClickUp — единственный включатель: пусто значит «не отправляем».
    IT = "kabinet_data.incident_types"
    if not has_table(IT):
        st.info(_tr("no_data"))
    else:
        types = q(f"""
            SELECT t.incident_type, t.title, t.description, t.clickup_list_id, t.clickup_list_name,
                   t.mode, t.watch_close, t.risk, t.due_days, t.assignee_group_name, t.assignee_group_id,
                   t.enabled_since, t.last_check_note, t.last_check_at, t.note,
                   COALESCE(o.n_open, 0)  AS n_open,
                   COALESCE(c.n_tasks, 0) AS n_tasks
            FROM {IT} t
            LEFT JOIN (SELECT incident_type, count(*) AS n_open FROM kabinet_data.incidents
                       WHERE status IN ('open', 'acknowledged') GROUP BY 1) o USING (incident_type)
            LEFT JOIN (SELECT incident_type, count(*) AS n_tasks FROM kabinet_data.clickup_tasks
                       WHERE closed_at IS NULL GROUP BY 1) c USING (incident_type)
            ORDER BY (t.clickup_list_id IS NULL), t.incident_type
        """)
        c1, c2 = st.columns([1.2, 2])
        only_routed = c1.toggle(_tr("al_only_routed"), value=False, key="al_routed")
        search = c2.text_input(_tr("al_search"), key="al_search").strip()
        view = types.copy()
        if only_routed:
            view = view[view["clickup_list_id"].notna()]
        if search:
            view = view[view["incident_type"].str.contains(search, case=False, na=False)
                        | view["title"].fillna("").str.contains(search, case=False, na=False)]
        st.caption(_trf("al_summary", total=len(types), routed=int(types["clickup_list_id"].notna().sum()),
                        open=int(types["n_open"].sum())))

        _mode_lbl = {"task": _tr("al_mode_task"), "digest": _tr("al_mode_digest")}
        _mode_code = {v: k for k, v in _mode_lbl.items()}
        # Уровень в базе — английский код (его читают сторож и ClickUp), на экране — слово.
        # Тот же приём, что у «Режима»: показываем подпись, сохраняем код.
        _risk_lbl = {c: _tr("al_risk_" + c) for c in ("Low", "Medium", "High", "Critical")}
        _risk_code = {v: k for k, v in _risk_lbl.items()}
        RISKS = [""] + [_risk_lbl[c] for c in ("Low", "Medium", "High", "Critical")]
        view["mode"] = view["mode"].map(_mode_lbl)
        view["risk"] = view["risk"].fillna("").map(lambda v: _risk_lbl.get(v, v))
        # id списка — целое, а не float: иначе 901222107497 в редакторе превратится в 9.01e11
        view["clickup_list_id"] = view["clickup_list_id"].astype("Int64")
        view["enabled_since"] = pd.to_datetime(view["enabled_since"])
        for c in ("title", "description", "clickup_list_name", "assignee_group_name", "assignee_group_id",
                  "last_check_note", "note"):
            view[c] = view[c].fillna("")

        cols = ["incident_type", "title", "n_open", "clickup_list_id", "mode", "watch_close", "risk",
                "due_days", "assignee_group_name", "assignee_group_id", "enabled_since", "n_tasks",
                "clickup_list_name", "last_check_note", "last_check_at", "description", "note"]
        ed = st.data_editor(
            view[cols], key="ed_alerts", use_container_width=True, height=560, hide_index=True,
            num_rows="fixed",
            disabled=["incident_type", "n_open", "n_tasks", "clickup_list_name", "last_check_note", "last_check_at"],
            column_config={
                "incident_type": st.column_config.TextColumn(_tr("al_col_type"), width="medium"),
                "title": st.column_config.TextColumn(_tr("al_col_title"), width="medium"),
                "n_open": st.column_config.NumberColumn(_tr("al_col_open"), width="small"),
                "clickup_list_id": st.column_config.NumberColumn(_tr("al_col_list"), width="medium",
                                                                 format="%d", step=1),
                "mode": st.column_config.SelectboxColumn(_tr("al_col_mode"), options=list(_mode_lbl.values()),
                                                         width="small"),
                "watch_close": st.column_config.CheckboxColumn(_tr("al_col_watch"), width="small"),
                "risk": st.column_config.SelectboxColumn(_tr("al_col_risk"), options=RISKS, width="small"),
                "due_days": st.column_config.NumberColumn(_tr("al_col_due"), width="small", min_value=0, step=1),
                "assignee_group_name": st.column_config.TextColumn(_tr("al_col_role"), width="small"),
                "assignee_group_id": st.column_config.TextColumn(_tr("al_col_role_id"), width="small"),
                "enabled_since": st.column_config.DateColumn(_tr("al_col_since"), width="small",
                                                             format="DD.MM.YYYY"),
                "n_tasks": st.column_config.NumberColumn(_tr("al_col_tasks"), width="small"),
                "clickup_list_name": st.column_config.TextColumn(_tr("al_col_list_name"), width="medium"),
                "last_check_note": st.column_config.TextColumn(_tr("al_col_check"), width="large"),
                "last_check_at": st.column_config.DatetimeColumn(_tr("al_col_checked"), width="small",
                                                                 format="DD.MM HH:mm"),
                "description": st.column_config.TextColumn(_tr("al_col_descr"), width="large"),
                "note": st.column_config.TextColumn(_tr("col_note"), width="medium"),
            },
        )
        st.caption(_tr("al_sync_hint"))
        if st.button(_tr("save"), key="save_alerts", type="primary"):
            before = view.set_index("incident_type")
            stmts = []
            for _, r in ed.iterrows():
                it = r["incident_type"]
                new = {
                    "title": _py(r["title"]), "description": _py(r["description"]),
                    "clickup_list_id": None if pd.isna(r["clickup_list_id"]) else int(r["clickup_list_id"]),
                    "mode": _mode_code.get(r["mode"], "task"),
                    "watch_close": bool(r["watch_close"]),
                    # в базу — английский код уровня: его читают сторож и ClickUp,
                    # на экране он подписан словом (как и «Режим»)
                    "risk": _risk_code.get(_py(r["risk"]), _py(r["risk"])),
                    "due_days": _int0(r["due_days"]),
                    "assignee_group_name": _py(r["assignee_group_name"]),
                    "assignee_group_id": _py(r["assignee_group_id"]),
                    "enabled_since": _py(r["enabled_since"]), "note": _py(r["note"]),
                }
                old = {
                    "title": _py(before.at[it, "title"]), "description": _py(before.at[it, "description"]),
                    "clickup_list_id": None if pd.isna(before.at[it, "clickup_list_id"]) else int(before.at[it, "clickup_list_id"]),
                    "mode": _mode_code.get(before.at[it, "mode"], "task"),
                    "watch_close": bool(before.at[it, "watch_close"]),
                    "risk": _risk_code.get(_py(before.at[it, "risk"]), _py(before.at[it, "risk"])),
                    "due_days": _int0(before.at[it, "due_days"]),
                    "assignee_group_name": _py(before.at[it, "assignee_group_name"]),
                    "assignee_group_id": _py(before.at[it, "assignee_group_id"]),
                    "enabled_since": _py(before.at[it, "enabled_since"]), "note": _py(before.at[it, "note"]),
                }
                changed = {k: v for k, v in new.items() if not _same(v, old[k])}
                if not changed:
                    continue
                # список появился впервые — задачи только с сегодняшнего дня, висящее не переносим
                if changed.get("clickup_list_id") and old["clickup_list_id"] is None and not new["enabled_since"]:
                    changed["enabled_since"] = date.today()
                # список сняли — путь и результат проверки больше не про этот тип
                if "clickup_list_id" in changed and changed["clickup_list_id"] is None:
                    changed["clickup_list_name"] = None; changed["last_check_note"] = None
                sets = ", ".join(f"{k} = %s" for k in changed)
                stmts.append((f"UPDATE {IT} SET {sets}, updated_by = 'kabinet', updated_at = now() "
                              f"WHERE incident_type = %s", list(changed.values()) + [it]))
            if not stmts:
                st.info(_tr("nochange"))
            else:
                try:
                    exec_sql(stmts)
                    st.cache_data.clear()
                    st.success(_trf("saved", n=len(stmts)))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))


# --------------------------------------------------------------------- SKU ---
# Проблемы контроля словами: код проверки на экране ничего не говорил («no_dims ⛔»), и было непонятно,
# что именно заполнять (вопрос Ярослава 06.10.2026). Подпись — что не так, и что сделать.
_SKU_CHECKS = ("no_type", "no_dims", "no_weight", "no_ean", "intro_estimate", "exit_candidate", "composition_lt2")
# откуда пришло значение поля: код источника в базе → слово на экране
_SKU_SRC = {"odoo": "src_odoo", "erp": "src_erp", "amazon": "src_amazon", "amazon_listing": "src_amazon",
            "amazon_catalog": "src_amazon", "lm": "src_lm", "manual": "src_manual", "computed": "src_computed",
            "pattern": "src_pattern"}


def _sku_src(v) -> str:
    s_ = as_text(v)
    if not s_:
        return _tr("src_none")
    if s_.startswith("estimate"):
        return _tr("src_estimate")
    return _tr(_SKU_SRC.get(s_, "src_other")).replace("{v}", s_)


def _sku_fmt_date(v) -> str:
    return "" if v is None or bool(pd.isna(v)) else pd.Timestamp(v).strftime("%d.%m.%Y")


def _sku_stmts(sku: str, old: dict, new: dict):
    """Изменения одного SKU → SQL. Один путь записи для карточки и для массовой правки таблицей.

    Поле, поправленное вручную, помечается источником `manual` — загрузчик его больше не трогает."""
    MANUAL = {"sku_type": "type_source", "ean": "ean_source", "intro_date": "intro_source",
              "exit_date": "exit_source", "gross_weight_kg": "weight_source"}
    sets, params, log, n = [], [], [], 0
    for f in ("sku_type", "ean", "intro_date", "exit_date", "gross_weight_kg", "supplier_code", "passport_ref"):
        if _same(new.get(f), old.get(f)):
            continue
        sets.append(f"{f} = %s"); params.append(_py(new.get(f)))
        if f in MANUAL:
            sets.append(f"{MANUAL[f]} = 'manual'")
        log.append((f, old.get(f), new.get(f))); n += 1
    if tuple(new["dims"]) != tuple(old["dims"]):
        sets += ["height_mm = %s", "width_mm = %s", "length_mm = %s", "dims_source = 'manual'"]
        params += [None if v is None else int(v) for v in new["dims"]]
        if all(new["dims"]):
            sets.append("volume_m3 = %s"); params.append(round(new["dims"][0] * new["dims"][1] * new["dims"][2] / 1e9, 6))
        log.append(("dims", "×".join(str(x or "") for x in old["dims"]), "×".join(str(x or "") for x in new["dims"]))); n += 1
    if list(new["restrictions"]) != list(old["restrictions"]):
        sets.append("restrictions = %s::jsonb"); params.append(json.dumps(list(new["restrictions"])))
        log.append(("restrictions", ", ".join(old["restrictions"]), ", ".join(new["restrictions"]))); n += 1
    stmts = [("INSERT INTO kabinet_data.sku_change_log (sku, field, old_value, new_value, source, actor) "
              "VALUES (%s, %s, %s, %s, 'manual', %s)", (sku, f, str(_py(o)), str(_py(v)), _actor())) for f, o, v in log]
    if sets:
        stmts.append((f"UPDATE kabinet_data.sku_master SET {', '.join(sets)}, updated_at = now(), updated_by = %s "
                      f"WHERE sku = %s", params + [_actor(), sku]))
    return stmts, n


def _sku_restr(v) -> list:
    return [x.strip().upper() for x in str(v or "").split(",") if x.strip()]


def _sku_fields(_types) -> list:
    """Поля справочника SKU — одно описание на форму добавления, шаблон Excel и проверку загрузки."""
    F = dict_kit.Field
    return [
        F("sku", _tr("sku_col_sku"), _tr("sku_fh_sku"), "text", True, example="41324000, 99601000-B, S2_41473000"),
        F("sku_type", _tr("sku_col_type"), _tr("sku_fh_type"), "choice", False, choices=_types),
        F("name", _tr("sku_col_name"), _tr("sku_fh_name"), "text", example="Dnipro-M CSD-36X"),
        F("ean", _tr("sku_col_ean"), _tr("sku_fh_ean"), "ean", example="4823102359007"),
        F("supplier_code", _tr("sku_col_supplier"), _tr("sku_fh_supplier"), "text"),
        F("intro_date", _tr("sku_col_intro"), _tr("sku_fh_intro"), "date", example="15.10.2026"),
        F("exit_date", _tr("sku_col_exit"), _tr("sku_fh_exit"), "date", example="31.12.2026"),
        F("height_mm", _tr("sku_col_h"), _tr("sku_fh_dims"), "int", example="120"),
        F("width_mm", _tr("sku_col_w"), _tr("sku_fh_dims"), "int", example="300"),
        F("length_mm", _tr("sku_col_l"), _tr("sku_fh_dims"), "int", example="450"),
        F("gross_weight_kg", _tr("sku_col_weight"), _tr("sku_fh_weight"), "float", example="2,35"),
        F("restrictions", _tr("sku_col_restr"), _tr("sku_restr_help"), "text", example="AMZ-GB, PL"),
        F("passport_ref", _tr("sku_col_passport"), _tr("sku_passport_help"), "text"),
    ]


_SKU_CODE_RE = re.compile(r"^(S\d*_)?\d{5,8}(-[A-Z0-9]{1,2})?$")


def _sku_refs(sku: str) -> list:
    """Где SKU используется. Непустой список — удалять нельзя, только в архив: удалённый код оставил бы
    допуски, прогнозы и продажи без товара, а загрузчик к тому же вернул бы его утром, если код есть в Odoo."""
    refs = []
    for key, sql in (
        ("sku_ref_matrix", "SELECT count(*) FROM kabinet_data.assortment_admissions WHERE sku = %s"),
        ("sku_ref_forecast", "SELECT count(*) FROM kabinet_data.forecast_register WHERE sku = %s"),
        ("sku_ref_sales", "SELECT count(*) FROM kabinet_data.economics_summary WHERE norm_sku = %s"),
        ("sku_ref_comp", "SELECT count(*) FROM kabinet_data.sku_composition WHERE composite_sku = %s OR base_sku = %s"),
        ("sku_ref_norms", "SELECT count(*) FROM kabinet_data.coverage_norm_rules WHERE sku = %s"),
        ("sku_ref_listings", "SELECT count(*) FROM kabinet_data.product_entity_listings WHERE sku = %s"),
    ):
        try:
            n = int(q_now(sql, (sku,) * sql.count("%s")).iloc[0, 0])
        except Exception:
            n = 0
        if n:
            refs.append((_tr(key), n))
    return refs


def _section_sku():
    SM = "kabinet_data.sku_master"
    dict_kit.instruction(_tr("sku_about"), _tr("sku_hint2"))
    if not has_table(SM):
        st.info(_tr("no_data"))
        return
    _lab = {"ru": "label_ru", "uk": "label_uk"}.get(get_lang(), "label_en")
    sm = q(f"""
        SELECT m.sku, m.sku_type, m.type_source, m.name, m.name_source, m.ean, m.ean_source, m.supplier_code,
               m.intro_date, m.intro_source, m.exit_date, m.exit_source,
               m.height_mm, m.width_mm, m.length_mm, m.volume_m3, m.dims_source, m.gross_weight_kg, m.weight_source,
               array_to_string(ARRAY(SELECT jsonb_array_elements_text(m.restrictions)), ', ') AS restrictions,
               m.passport_ref, array_to_string(m.in_scope, ', ') AS in_scope, m.is_active,
               c.codes, c.n_err,
               t1.{_lab} AS cat1, t.{_lab} AS cat,
               EXISTS (SELECT 1 FROM kabinet_data.assortment_admissions a
                       WHERE a.sku = m.sku AND a.removed_on IS NULL) AS in_matrix,
               (SELECT string_agg(DISTINCT l.status, ',') FROM kabinet_data.v_sku_lifecycle_current l
                 WHERE l.sku = m.sku) AS life
        FROM {SM} m
        LEFT JOIN (SELECT sku, string_agg(check_code, ',' ORDER BY severity, check_code) AS codes,
                          count(*) FILTER (WHERE severity = 'error') AS n_err
                   FROM kabinet_data.sku_checks GROUP BY sku) c USING (sku)
        LEFT JOIN kabinet_data.sku_category_links k ON k.sku = m.sku
        LEFT JOIN kabinet_data.v_sku_category_tree t ON t.category_key = k.category_key
        LEFT JOIN kabinet_data.v_sku_category_tree t1 ON t1.depth = 1 AND t1.level1 = t.level1
        ORDER BY (c.n_err IS NULL), c.n_err DESC, m.sku
    """)
    _types = {"base": _tr("sku_t_base"), "composite": _tr("sku_t_composite")}
    sm["codes"] = sm["codes"].fillna("")
    sm["life"] = sm["life"].fillna("")
    sm["todo"] = [", ".join(_tr(f"sku_chk_{c}") for c in dict.fromkeys(v.split(",")) if c) for v in sm["codes"]]
    _life_codes = ["active", "not_launched", "phasing_out", "seasonal_pause", "discontinued"]

    # ── фильтры ──
    f1, f2, f3, f4 = st.columns([1.6, 1, 1.4, 1])
    search = dict_kit.search_input(_tr("sku_search"), "sku_search", _tr, "41324000, Amoladora…", where=f1)
    type_sel = f2.multiselect(_tr("sku_type_f"), ["base", "composite", "none"], placeholder=_tr("ph_any"),
                              format_func=lambda x: _types.get(x, _tr("sku_t_none")), key="sku_type_f")
    cat_sel = f3.multiselect(_tr("sku_cat_f"), sorted(sm["cat1"].dropna().unique()), placeholder=_tr("ph_any"),
                             key="sku_cat_f")
    state_sel = f4.selectbox(_tr("sku_state_f"), ["active", "archived", "all"], key="sku_state_f",
                             format_func=lambda x: _tr(f"sku_state_{x}"))
    g1, g2, g3, g4 = st.columns([1.6, 1, 1.4, 1])
    life_sel = g1.multiselect(_tr("sku_life_f"), _life_codes, placeholder=_tr("ph_any"), key="sku_life_f",
                              format_func=lambda x: i18n_t(f"cat.life.{x}"))
    # «Все» — отдельный вариант, а повторный клик по выбранному снимает выбор: пусто тоже значит «все»
    mx_sel = g2.segmented_control(_tr("sku_mx_f"), ["all", "yes", "no"], default="all", key="sku_mx_f2",
                                  format_func=lambda x: _tr(f"sku_mx_{x}")) or "all"
    check_sel = g3.multiselect(_tr("sku_check_f2"), list(_SKU_CHECKS), key="sku_check_f2", placeholder=_tr("ph_any"),
                               format_func=lambda c: _tr(f"sku_chk_{c}"),
                               help="\n".join(f"- **{_tr(f'sku_chk_{c}')}** — {_tr(f'sku_chkh_{c}')}" for c in _SKU_CHECKS))
    # тумблер и счётчик над таблицей считают ОДНО И ТО ЖЕ — SKU с ошибками проверок. Раньше тумблер брал
    # любые замечания (566), а счётчик — только ошибки (282), и два числа про «проблемы» не сходились
    only_issues = g4.toggle(_tr("sku_only_err"), value=False, key="sku_only_err", help=_tr("sku_only_err_help"))

    view = sm.copy()
    if search:
        view = view[view["sku"].str.contains(search, case=False, na=False, regex=False)
                    | view["name"].fillna("").str.contains(search, case=False, na=False, regex=False)]
    if type_sel:
        view = view[view["sku_type"].fillna("none").isin(type_sel)]
    if cat_sel:
        view = view[view["cat1"].isin(cat_sel)]
    if state_sel != "all":
        view = view[view["is_active"].fillna(True).astype(bool) == (state_sel == "active")]
    if life_sel:
        view = view[view["life"].apply(lambda v: any(x in v.split(",") for x in life_sel))]
    if mx_sel != "all":
        view = view[view["in_matrix"].astype(bool) == (mx_sel == "yes")]
    if check_sel:
        view = view[view["codes"].apply(lambda v: any(c in v.split(",") for c in check_sel))]
    if only_issues:
        view = view[view["n_err"].fillna(0) > 0]
    _has_err = sm["n_err"].fillna(0) > 0
    st.caption(_trf("sku_summary3", shown=len(view), total=len(sm),
                    arch=int((~sm["is_active"].fillna(True).astype(bool)).sum()),
                    err=int(_has_err.sum()), warn=int(((sm["codes"] != "") & ~_has_err).sum())))

    # ── таблица (только просмотр; правка — в карточке под ней) ──
    lst = pd.DataFrame({
        "sku": view["sku"],
        "type": view["sku_type"].map(_types).fillna(_tr("sku_t_none")),
        "name": view["name"].fillna(""),
        "cat": view["cat"].fillna(""),
        "state": [_tr("sku_state_active") if bool(a) else _tr("sku_state_archived")
                  for a in view["is_active"].fillna(True)],
        "matrix": ["✓" if bool(x) else "" for x in view["in_matrix"]],
        "life": [", ".join(i18n_t(f"cat.life.{x}") for x in v.split(",") if x) for v in view["life"]],
        "todo": view["todo"],
        "ean": view["ean"].fillna(""),
        "dims": ["×".join(num_text(x) for x in (h, w, l_)) if any(num_text(x) for x in (h, w, l_)) else ""
                 for h, w, l_ in zip(view["height_mm"], view["width_mm"], view["length_mm"])],
        "weight": [num_text(v, 3) for v in view["gross_weight_kg"]],
    })
    fsig = (search, tuple(type_sel), tuple(cat_sel), state_sel, tuple(life_sel), mx_sel, tuple(check_sel), only_issues)
    options = list(lst["sku"])
    picked = dict_kit.table_pick(lst, options, "sku_list", fsig, height=420, column_config={
        "sku": st.column_config.TextColumn(_tr("sku_col_sku"), width="small"),
        "type": st.column_config.TextColumn(_tr("sku_col_type"), width="small"),
        "name": st.column_config.TextColumn(_tr("sku_col_name"), width="large"),
        "cat": st.column_config.TextColumn(_tr("sku_col_cat"), width="medium"),
        "state": st.column_config.TextColumn(_tr("sku_col_state"), width=90),
        "matrix": st.column_config.TextColumn(_tr("sku_col_matrix"), width="small", help=_tr("sku_col_matrix_help")),
        "life": st.column_config.TextColumn(_tr("sku_col_life"), width=150, help=_tr("sku_col_life_help")),
        "todo": st.column_config.TextColumn(_tr("sku_col_todo"), width=300, help=_tr("sku_col_todo_help")),
        "ean": st.column_config.TextColumn(_tr("sku_col_ean"), width="small"),
        "dims": st.column_config.TextColumn(_tr("sku_col_dims"), width="small"),
        "weight": st.column_config.TextColumn(_tr("sku_col_weight"), width="small"),
    })
    st.caption(_tr("sku_list_hint"))

    # ── выбранная строка: изменить / в архив / удалить ──
    if options:
        _names = dict(zip(sm["sku"], sm["name"].fillna("")))
        st.markdown("#### " + _tr("sku_card_h"))
        sku = dict_kit.card_pick(_tr("sku_card_pick"), options,
                                 {s_: f"{s_} — {_names.get(s_, '')}"[:110] for s_ in options}, "sku_card", picked)
        r = sm[sm["sku"] == sku].iloc[0]
        _sku_card(r, _types)
        _sku_row_actions(r)

    _sku_add_form(sm, _types)
    _sku_excel(sm, view, _types)
    _sku_kits(sm)


def _sku_row_actions(r):
    """В архив / вернуть из архива / удалить. Удалить можно только SKU без связей и без источника (заведённый
    вручную и нигде не использованный): иначе удаление оставит допуски, прогнозы и продажи без товара, а код
    из Odoo загрузчик вернул бы на следующее утро. Архив — флаг is_active: загрузчик его не трогает."""
    sku = r["sku"]
    active = bool(r["is_active"]) if not pd.isna(r["is_active"]) else True
    if not auth.can("dict.edit"):
        return    # только просмотр: кнопок архива и удаления нет вовсе (запись всё равно закрыта в exec_sql)
    box = st.container(border=True)
    box.markdown("**" + _tr("sku_act_h") + "**")
    refs = _sku_refs(sku)
    in_src = bool(as_text(r["in_scope"]))
    c1, c2 = box.columns([1, 2])
    if active:
        if c1.button(_tr("sku_act_archive"), key=f"sku_arch_{sku}"):
            _sku_set_active(sku, False)
    else:
        box.info(_tr("sku_is_archived"))
        if c1.button(_tr("sku_act_restore"), key=f"sku_rest_{sku}"):
            _sku_set_active(sku, True)
    with c2:
        if refs or in_src:
            why = [f"{lbl}: {n}" for lbl, n in refs] + ([_trf("sku_ref_src", where=as_text(r["in_scope"]))] if in_src else [])
            st.caption(_tr("sku_del_blocked") + " " + "; ".join(why) + ". " + _tr("sku_del_use_archive"))
        elif confirm_delete(f"sku_{sku}", _trf("sku_del_what", sku=sku)):
            try:
                exec_sql([("DELETE FROM kabinet_data.sku_category_links WHERE sku = %s", (sku,)),
                          ("INSERT INTO kabinet_data.sku_change_log (sku, field, old_value, new_value, source, actor) "
                           "VALUES (%s, 'deleted', %s, NULL, 'manual', %s)", (sku, as_text(r["name"]), _actor())),
                          ("DELETE FROM kabinet_data.sku_master WHERE sku = %s", (sku,))])
                st.cache_data.clear()
                st.success(_trf("sku_deleted", sku=sku))
                st.rerun()
            except Exception as e:
                st.error(_trf("err", e=e))


def _sku_set_active(sku: str, active: bool):
    try:
        exec_sql([("UPDATE kabinet_data.sku_master SET is_active = %s, updated_at = now(), updated_by = %s WHERE sku = %s",
                   (active, _actor(), sku)),
                  ("INSERT INTO kabinet_data.sku_change_log (sku, field, old_value, new_value, source, actor) "
                   "VALUES (%s, 'is_active', %s, %s, 'manual', %s)", (sku, str(not active), str(active), _actor()))])
        st.cache_data.clear()
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _sku_new_row_errors(vals: dict, existing: set, kits_ok: bool = True) -> list:
    """Проверки нового SKU — общие для формы и для загрузки: код, дубль, тип, даты, габариты у набора."""
    errs = []
    code = vals.get("sku") or ""
    if not code:
        errs.append(("sku", "", _tr("sku_err_code_empty")))
    elif not _SKU_CODE_RE.match(code):
        errs.append(("sku", code, _tr("sku_err_code_fmt")))
    elif code in existing:
        errs.append(("sku", code, _tr("sku_err_code_dup")))
    if not vals.get("name"):
        errs.append(("name", "", _tr("sku_err_name_empty")))
    if vals.get("exit_date") and vals.get("intro_date") and vals["exit_date"] < vals["intro_date"]:
        errs.append(("exit_date", str(vals["exit_date"]), _tr("sku_exit_before_intro")))
    if vals.get("sku_type") == "composite" and any(vals.get(c) is not None for c in
                                                   ("height_mm", "width_mm", "length_mm", "gross_weight_kg")):
        errs.append(("height_mm", "", _tr("sku_err_kit_phys")))
    return errs


def _sku_insert_stmts(vals: dict) -> list:
    dims = [vals.get("height_mm"), vals.get("width_mm"), vals.get("length_mm")]
    vol = round(dims[0] * dims[1] * dims[2] / 1e9, 6) if all(dims) else None
    m = lambda f: "manual" if vals.get(f) is not None else None
    return [
        ("""INSERT INTO kabinet_data.sku_master
              (sku, sku_type, type_source, name, name_source, ean, ean_source, supplier_code,
               intro_date, intro_source, exit_date, exit_source, height_mm, width_mm, length_mm, dims_source, volume_m3,
               gross_weight_kg, weight_source, restrictions, passport_ref, in_scope, is_active, note, updated_by)
            VALUES (%s,%s,%s,%s,'manual',%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s::jsonb,%s,'{}',true,%s,%s)""",
         (vals["sku"], vals.get("sku_type"), m("sku_type"), vals.get("name"), vals.get("ean"), m("ean"),
          vals.get("supplier_code"), vals.get("intro_date"), m("intro_date"), vals.get("exit_date"), m("exit_date"),
          dims[0], dims[1], dims[2], "manual" if any(dims) else None, vol,
          vals.get("gross_weight_kg"), m("gross_weight_kg"), json.dumps(vals.get("restrictions") or []),
          vals.get("passport_ref"), _tr("sku_note_manual"), _actor())),
        ("INSERT INTO kabinet_data.sku_change_log (sku, field, old_value, new_value, source, actor) "
         "VALUES (%s, 'created', NULL, %s, 'manual', %s)", (vals["sku"], vals.get("name"), _actor())),
    ]


def _sku_add_form(sm, _types):
    """Форма добавления — под таблицей, с подсказкой к каждому полю: что вводить и откуда брать."""
    st.markdown("#### " + _tr("sku_add_h"))
    if not auth.can("dict.edit"):
        st.caption(_tr("sku_ro_add"))
        return
    st.caption(_tr("sku_add_note"))
    fields = {f.code: f for f in _sku_fields(_types)}
    with st.form("sku_add_form", clear_on_submit=False):
        a1, a2, a3 = st.columns([1, 1, 2])
        code = a1.text_input(fields["sku"].label + " *", help=fields["sku"].hint, key="sku_add_code").strip().upper()
        typ = a2.selectbox(fields["sku_type"].label, ["base", "composite"], help=fields["sku_type"].hint,
                           format_func=lambda x: _types[x], key="sku_add_type")
        name = a3.text_input(fields["name"].label + " *", help=fields["name"].hint, key="sku_add_name").strip()
        b1, b2, b3, b4 = st.columns(4)
        ean = b1.text_input(fields["ean"].label, help=fields["ean"].hint, key="sku_add_ean").strip()
        sup = b2.text_input(fields["supplier_code"].label, help=fields["supplier_code"].hint, key="sku_add_sup").strip()
        intro = b3.date_input(fields["intro_date"].label, value=None, format="DD.MM.YYYY",
                              help=fields["intro_date"].hint, key="sku_add_intro")
        exit_ = b4.date_input(fields["exit_date"].label, value=None, format="DD.MM.YYYY",
                              help=fields["exit_date"].hint, key="sku_add_exit")
        c1, c2, c3, c4 = st.columns(4)
        h = c1.text_input(fields["height_mm"].label, help=fields["height_mm"].hint, key="sku_add_h")
        w = c2.text_input(fields["width_mm"].label, help=fields["width_mm"].hint, key="sku_add_w")
        l_ = c3.text_input(fields["length_mm"].label, help=fields["length_mm"].hint, key="sku_add_l")
        kg = c4.text_input(fields["gross_weight_kg"].label, help=fields["gross_weight_kg"].hint, key="sku_add_kg")
        d1, d2 = st.columns(2)
        restr = d1.text_input(fields["restrictions"].label, help=fields["restrictions"].hint, key="sku_add_r")
        pas = d2.text_input(fields["passport_ref"].label, help=fields["passport_ref"].hint, key="sku_add_p")
        go = st.form_submit_button(_tr("sku_add_btn"), type="primary")
    if not go:
        return
    errs = []
    vals = {"sku": code, "sku_type": typ, "name": name or None, "supplier_code": sup or None,
            "intro_date": intro, "exit_date": exit_, "passport_ref": pas.strip() or None,
            "restrictions": _sku_restr(restr)}
    for fcode, raw in (("ean", ean), ("height_mm", h), ("width_mm", w), ("length_mm", l_), ("gross_weight_kg", kg)):
        v, e = dict_kit.parse_value(fields[fcode], raw)
        if e:
            errs.append((fcode, raw, _tr(f"kit_why_{e}")))
        vals[fcode] = v
    errs += _sku_new_row_errors(vals, set(sm["sku"]))
    if errs:
        for f, v, why in errs:
            st.error(f"{fields[f].label}: {why}" + (f" («{v}»)" if v else ""))
        return
    try:
        exec_sql(_sku_insert_stmts(vals))
        st.cache_data.clear()
        st.success(_trf("sku_added", sku=code))
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _sku_excel(sm, view, _types):
    """Массовая загрузка из Excel: шаблон → загрузка → проверка ДО сохранения → сохранить.
    Пустая ячейка ничего не меняет; ошибка хотя бы в одной строке блокирует сохранение целиком."""
    st.markdown("#### " + _tr("sku_xl_h"))
    st.caption(_tr("sku_xl_note"))
    fields = _sku_fields(_types)
    fmap = {f.code: f for f in fields}
    x1, x2 = st.columns(2)
    x1.download_button(_tr("sku_xl_tpl_empty"), key="sku_xl_tpl_empty",
                       data=dict_kit.template_bytes(fields, "SKU", _tr("kit_howto_sheet"),
                                                    (_tr("kit_hc_field"), _tr("kit_hc_req"), _tr("kit_hc_what"), _tr("kit_hc_ex"))),
                       file_name="sku_template.xlsx",
                       mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    cur_rows = [{
        "sku": r.sku, "sku_type": _types.get(r.sku_type, ""), "name": as_text(r.name), "ean": as_text(r.ean),
        "supplier_code": as_text(r.supplier_code), "intro_date": _sku_fmt_date(r.intro_date),
        "exit_date": _sku_fmt_date(r.exit_date), "height_mm": num_text(r.height_mm), "width_mm": num_text(r.width_mm),
        "length_mm": num_text(r.length_mm), "gross_weight_kg": num_text(r.gross_weight_kg, 3),
        "restrictions": as_text(r.restrictions), "passport_ref": as_text(r.passport_ref)} for r in view.itertuples()]
    x2.download_button(_tr("sku_xl_tpl_cur2"), key="sku_xl_tpl_cur",
                       data=dict_kit.template_bytes(fields, "SKU", _tr("kit_howto_sheet"),
                                                    (_tr("kit_hc_field"), _tr("kit_hc_req"), _tr("kit_hc_what"), _tr("kit_hc_ex")),
                                                    rows=cur_rows),
                       file_name="sku_current.xlsx",
                       mime="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
    if not auth.can("dict.edit"):
        st.caption(_tr("sku_ro_upload"))
        return
    up = st.file_uploader(_tr("sku_xl_upload"), type=["xlsx", "csv"], key="sku_xl_file")
    if up is None:
        return
    try:
        df, unknown, missing = dict_kit.read_upload(up, fields)
    except Exception as e:
        st.error(_trf("err", e=e))
        return
    if unknown:
        st.warning(_trf("kit_unknown_cols", cols=", ".join(unknown)))
    if missing:
        st.error(_trf("kit_missing_cols", cols=", ".join(missing)))
        return
    by_sku = {r.sku: r for r in sm.itertuples()}
    errors, changes, stmts = [], [], []
    n_new = n_upd = n_same = 0
    seen = set()
    for i, row in df.iterrows():
        line = i + 2                               # номер строки в Excel: первая — заголовки
        code = str(row.get("sku", "")).strip().upper()
        code = re.sub(r"\.0$", "", code)
        _m = re.match(r"^(S\d*_)?(\d{5,7})(-[A-Z0-9]{1,2})?$", code)
        if _m:                                     # Excel съедает ведущий ноль: 8455000 → 08455000, 8453000-84 → 08453000-84
            code = (_m.group(1) or "") + _m.group(2).zfill(8) + (_m.group(3) or "")
        if code in seen:
            errors.append((line, code, fmap["sku"].label, code, _tr("sku_err_dup_in_file")))
            continue
        seen.add(code)
        vals, row_err = {"sku": code}, []
        for f in fields[1:]:
            if f.code not in df.columns:
                continue
            raw = row.get(f.code, "")
            if f.code == "restrictions":
                vals[f.code] = _sku_restr(raw) if str(raw).strip() else None
                continue
            v, e = dict_kit.parse_value(f, raw)
            if e:
                row_err.append((line, code, f.label, raw, _tr(f"kit_why_{e}")))
            vals[f.code] = v
        if row_err:
            errors += row_err
            continue
        old = by_sku.get(code)
        if old is None:                            # новый SKU
            new_vals = {k: v for k, v in vals.items() if v is not None}
            errs = _sku_new_row_errors(dict(new_vals, sku=code), set(by_sku))
            if errs:
                errors += [(line, code, fmap[f].label, v, why) for f, v, why in errs]
                continue
            stmts += _sku_insert_stmts(new_vals)
            changes.append((code, _tr("kit_created"), "", as_text(new_vals.get("name"))))
            n_new += 1
            continue
        # существующий: меняются только непустые ячейки
        if vals.get("name") and vals["name"] != as_text(old.name) and as_text(old.name_source) in ("odoo", "erp", "amazon"):
            errors.append((line, code, fmap["name"].label, vals["name"], _tr("sku_err_name_src")))
            continue
        is_kit = old.sku_type == "composite"
        if is_kit and any(vals.get(c) is not None for c in ("height_mm", "width_mm", "length_mm", "gross_weight_kg")):
            errors.append((line, code, fmap["height_mm"].label, "", _tr("sku_err_kit_phys")))
            continue
        o = {"sku_type": old.sku_type if old.sku_type in ("base", "composite") else None,
             "ean": as_text(old.ean) or None, "supplier_code": as_text(old.supplier_code) or None,
             "passport_ref": as_text(old.passport_ref) or None,
             "intro_date": None if pd.isna(old.intro_date) else pd.Timestamp(old.intro_date).date(),
             "exit_date": None if pd.isna(old.exit_date) else pd.Timestamp(old.exit_date).date(),
             "gross_weight_kg": None if pd.isna(old.gross_weight_kg) else float(old.gross_weight_kg),
             "dims": tuple(None if pd.isna(x) else int(x) for x in (old.height_mm, old.width_mm, old.length_mm)),
             "restrictions": _sku_restr(old.restrictions)}
        n = dict(o)
        for k in ("sku_type", "ean", "supplier_code", "passport_ref", "intro_date", "exit_date", "gross_weight_kg"):
            if vals.get(k) is not None:
                n[k] = vals[k]
        if any(vals.get(c) is not None for c in ("height_mm", "width_mm", "length_mm")):
            n["dims"] = tuple(vals.get(c) if vals.get(c) is not None else o["dims"][j]
                              for j, c in enumerate(("height_mm", "width_mm", "length_mm")))
        if vals.get("restrictions") is not None:
            n["restrictions"] = vals["restrictions"]
        if n.get("exit_date") and n.get("intro_date") and n["exit_date"] < n["intro_date"]:
            errors.append((line, code, fmap["exit_date"].label, str(n["exit_date"]), _tr("sku_exit_before_intro")))
            continue
        s_, cnt = _sku_stmts(code, o, n)
        if not cnt:
            n_same += 1
            continue
        _lbl = lambda k: _tr("sku_col_dims") if k == "dims" else (fmap[k].label if k in fmap else k)
        _txt = lambda v: "×".join("" if x is None else str(x) for x in v) if isinstance(v, tuple) else \
            (", ".join(v) if isinstance(v, list) else ("" if v is None else str(v)))
        for k in o:
            if _txt(o[k]) != _txt(n[k]):
                changes.append((code, _lbl(k), _txt(o[k]), _txt(n[k])))
        stmts += s_
        n_upd += 1
    ok = dict_kit.check_view(errors, changes, n_new, n_upd, n_same, _tr)
    if ok and st.button(_trf("sku_xl_save", n=n_new + n_upd), type="primary", key="sku_xl_save"):
        try:
            exec_sql(stmts)
            st.cache_data.clear()
            st.success(_trf("sku_xl_saved", new=n_new, upd=n_upd))
            st.rerun()
        except Exception as e:
            st.error(_trf("err", e=e))


def _sku_card(r, _types):
    sku = r["sku"]
    is_kit = r["sku_type"] == "composite"
    box = st.container(border=True)
    box.markdown(f"**{sku}**" + (f" · {as_text(r['name'])}" if as_text(r["name"]) else "") + "  \n"
                 + (_trf("sku_card_name_src", src=_sku_src(r["name_source"])) if as_text(r["name"])
                    else _tr("sku_card_no_name")))
    codes = [c for c in dict.fromkeys(str(r["codes"] or "").split(",")) if c]
    if codes:
        box.warning("\n".join(f"- {_tr(f'sku_chk_{c}')} — {_tr(f'sku_do_{c}')}" for c in codes))
    else:
        box.success(_tr("sku_card_ok"))

    with box.form(key=f"sku_form_{sku}"):
        st.markdown("**" + _tr("sku_grp_ident") + "**")
        a1, a2, a3 = st.columns(3)
        type_opts = ["base", "composite", "none"]
        cur_type = r["sku_type"] if r["sku_type"] in ("base", "composite") else "none"
        new_type = a1.selectbox(_tr("sku_col_type"), type_opts, index=type_opts.index(cur_type),
                                format_func=lambda x: _types.get(x, _tr("sku_t_none")), key=f"sku_t_{sku}")
        a1.caption(_trf("sku_src", src=_sku_src(r["type_source"])))
        new_ean = a2.text_input(_tr("sku_col_ean"), value=as_text(r["ean"]), key=f"sku_ean_{sku}")
        a2.caption(_trf("sku_src", src=_sku_src(r["ean_source"])))
        new_sup = a3.text_input(_tr("sku_col_supplier"), value=as_text(r["supplier_code"]), key=f"sku_sup_{sku}")
        a3.caption(_tr("sku_supplier_help"))

        st.markdown("**" + _tr("sku_grp_dates") + "**")
        d1, d2, d3 = st.columns(3)
        intro_old = None if pd.isna(r["intro_date"]) else pd.Timestamp(r["intro_date"]).date()
        new_intro = d1.date_input(_tr("sku_col_intro"), value=intro_old, format="DD.MM.YYYY", key=f"sku_in_{sku}")
        d1.caption(_trf("sku_src", src=_sku_src(r["intro_source"]))
                   + (" · " + _tr("sku_intro_confirm") if str(r["intro_source"] or "").startswith("estimate") else ""))
        exit_old = None if pd.isna(r["exit_date"]) else pd.Timestamp(r["exit_date"]).date()
        has_exit = d2.checkbox(_tr("sku_exit_set"), value=exit_old is not None, key=f"sku_hx_{sku}")
        # пустое поле — «не выводится»: подставленная сегодняшняя дата читалась как уже заданная
        new_exit = d3.date_input(_tr("sku_col_exit"), value=exit_old, format="DD.MM.YYYY", key=f"sku_ex_{sku}")
        d2.caption(_tr("sku_exit_help"))

        st.markdown("**" + _tr("sku_grp_phys") + "**")
        if is_kit:
            st.caption(_trf("sku_kit_phys", w=num_text(r["gross_weight_kg"], 3) or "—",
                            v=num_text(r["volume_m3"], 6) or "—"))
            dims_new = tuple(None if pd.isna(x) else int(x) for x in (r["height_mm"], r["width_mm"], r["length_mm"]))
            w_text = num_text(r["gross_weight_kg"], 3)
        else:
            p1, p2, p3, p4 = st.columns(4)
            h_t = p1.text_input(_tr("sku_col_h"), value=num_text(r["height_mm"]), key=f"sku_h_{sku}")
            w_t = p2.text_input(_tr("sku_col_w"), value=num_text(r["width_mm"]), key=f"sku_w_{sku}")
            l_t = p3.text_input(_tr("sku_col_l"), value=num_text(r["length_mm"]), key=f"sku_l_{sku}")
            w_text = p4.text_input(_tr("sku_col_weight"), value=num_text(r["gross_weight_kg"], 3), key=f"sku_kg_{sku}")
            st.caption(_trf("sku_phys_src", dims=_sku_src(r["dims_source"]), w=_sku_src(r["weight_source"]))
                       + " · " + _tr("sku_num_help"))
            dims_new = tuple(text_num(x, as_int=True) for x in (h_t, w_t, l_t))

        st.markdown("**" + _tr("sku_grp_other") + "**")
        o1, o2 = st.columns(2)
        new_restr = o1.text_input(_tr("sku_col_restr"), value=as_text(r["restrictions"]), key=f"sku_r_{sku}",
                                  help=_tr("sku_restr_help"))
        new_pass = o2.text_input(_tr("sku_col_passport"), value=as_text(r["passport_ref"]), key=f"sku_p_{sku}",
                                 help=_tr("sku_passport_help"))
        st.caption(_trf("sku_scope_line", where=as_text(r["in_scope"]) or "—"))
        _ro = not auth.can("dict.edit")
        submitted = st.form_submit_button(_tr("save"), type="primary", disabled=_ro,
                                          help=_tr("sku_ro_help") if _ro else None)

    if not submitted:
        return
    bad = []
    if not is_kit:
        for lbl, raw_v, as_int in ((_tr("sku_col_h"), h_t, True), (_tr("sku_col_w"), w_t, True),
                                   (_tr("sku_col_l"), l_t, True), (_tr("sku_col_weight"), w_text, False)):
            if str(raw_v or "").strip() and text_num(raw_v, as_int=as_int) is None:
                bad.append(_trf("sku_num_bad", sku=sku, f=lbl, v=raw_v))
    if has_exit and new_exit is None:
        bad.append(_tr("sku_exit_need_date"))
    elif has_exit and new_intro and new_exit < new_intro:
        bad.append(_tr("sku_exit_before_intro"))
    for b in bad:
        st.error(b)
    if bad:
        return                                   # половина правок хуже отказа — не сохраняем ничего
    old = {"sku_type": r["sku_type"] if r["sku_type"] in ("base", "composite") else None,
           "ean": as_text(r["ean"]) or None, "supplier_code": as_text(r["supplier_code"]) or None,
           "passport_ref": as_text(r["passport_ref"]) or None, "intro_date": intro_old, "exit_date": exit_old,
           "gross_weight_kg": None if pd.isna(r["gross_weight_kg"]) else float(r["gross_weight_kg"]),
           "dims": tuple(None if pd.isna(x) else int(x) for x in (r["height_mm"], r["width_mm"], r["length_mm"])),
           "restrictions": _sku_restr(r["restrictions"])}
    new = {"sku_type": None if new_type == "none" else new_type,
           "ean": new_ean.strip() or None, "supplier_code": new_sup.strip() or None,
           "passport_ref": new_pass.strip() or None, "intro_date": new_intro,
           "exit_date": new_exit if has_exit else None,
           "gross_weight_kg": old["gross_weight_kg"] if is_kit else text_num(w_text),
           "dims": old["dims"] if is_kit else dims_new, "restrictions": _sku_restr(new_restr)}
    stmts, n = _sku_stmts(sku, old, new)
    if not stmts:
        st.info(_tr("nochange"))
        return
    try:
        exec_sql(stmts)
        st.cache_data.clear()
        st.success(_trf("sku_saved_manual", n=n))
        st.rerun()
    except Exception as e:
        st.error(_trf("err", e=e))


def _sku_kits(sm):
    # состав выбранного набора. Блок стоит под таблицей SKU и терялся на длинной странице —
    # даём заголовок и рамку, чтобы его было видно, не пролистывая (замечание 24.09.2026)
    _kits = sm.loc[sm["sku_type"] == "composite", "sku"].tolist()
    if not _kits:
        return
    st.markdown("#### " + _tr("sku_comp_h"))
    _comp_box = st.container(border=True)
    kit = _comp_box.selectbox(_tr("sku_comp_pick"), _kits, key="sku_kit")
    comp = q1("""SELECT c.base_sku, c.quantity, m.name, m.gross_weight_kg, m.volume_m3
                 FROM kabinet_data.sku_composition c LEFT JOIN kabinet_data.sku_master m ON m.sku = c.base_sku
                 WHERE c.composite_sku = %s ORDER BY c.base_sku""", (kit,))
    if comp.empty:
        _comp_box.caption(_tr("sku_comp_none"))
        return
    comp = comp.copy()
    for _c, _nd in (("quantity", 0), ("gross_weight_kg", 3), ("volume_m3", 6)):
        comp[_c] = [num_text(v, _nd) for v in comp[_c]]
    comp["name"] = comp["name"].fillna("")
    _comp_box.dataframe(comp, hide_index=True, use_container_width=True, column_config={
        "base_sku": st.column_config.TextColumn(_tr("sku_comp_col_base")),
        "quantity": st.column_config.TextColumn(_tr("sku_comp_col_qty")),
        "name": st.column_config.TextColumn(_tr("sku_comp_col_name"), width="large"),
        "gross_weight_kg": st.column_config.TextColumn(_tr("sku_col_weight")),
        "volume_m3": st.column_config.TextColumn(_tr("sku_col_vol")),
    })
    _comp_box.caption(_tr("sku_comp_note"))


# -------------------------------------------------------------------- PeID ---
def _section_peid():
    st.caption(_tr("pe_hint"))
    PE = "kabinet_data.product_entities"
    AR_PE = "kabinet_data.assortment_representations"   # роль живёт здесь, а не в справочнике PeID
    if not has_table(PE):
        st.info(_tr("no_data"))
    else:
        # джойны l и c — явным ON: после присоединения variation_groups (у неё тоже marketplace_id) USING давал
        # «common column name marketplace_id appears more than once», и вкладка падала на живой базе (20.09.2026)
        pe = q(f"""
            SELECT e.id, m.code AS mp, e.peid, e.title, e.url, e.is_parent, e.is_active, e.active_source,
                   e.variation_group_id, g.name AS group_name,
                   array_to_string(e.seen_in, ', ') AS seen, e.last_seen, e.comment,
                   l.skus, l.statuses, c.issues, c.n_err
            FROM {PE} e
            JOIN kabinet_data.marketplaces_new m ON m.id = e.marketplace_id
            LEFT JOIN kabinet_data.variation_groups g ON g.id = e.variation_group_id
            LEFT JOIN (SELECT marketplace_id, peid, string_agg(DISTINCT sku, ', ') AS skus,
                              string_agg(DISTINCT listing_status, ', ') AS statuses
                       FROM kabinet_data.product_entity_listings GROUP BY 1, 2) l ON l.marketplace_id = e.marketplace_id AND l.peid = e.peid
            LEFT JOIN (SELECT marketplace_id, peid,
                              string_agg(check_code || CASE severity WHEN 'error' THEN ' ⛔' WHEN 'warning' THEN ' ⚠' ELSE '' END,
                                         ', ' ORDER BY severity, check_code) AS issues,
                              count(*) FILTER (WHERE severity = 'error') AS n_err
                       FROM kabinet_data.product_entity_checks GROUP BY 1, 2) c ON c.marketplace_id = e.marketplace_id AND c.peid = e.peid
            ORDER BY m.code, (c.n_err IS NULL), c.n_err DESC, e.peid
        """) if has_table("kabinet_data.variation_groups") else q(f"""
            SELECT e.id, m.code AS mp, e.peid, e.title, e.url, e.is_parent, e.is_active, e.active_source,
                   e.variation_group_id, NULL::text AS group_name,
                   array_to_string(e.seen_in, ', ') AS seen, e.last_seen, e.comment,
                   l.skus, l.statuses, c.issues, c.n_err
            FROM {PE} e
            JOIN kabinet_data.marketplaces_new m ON m.id = e.marketplace_id
            LEFT JOIN (SELECT marketplace_id, peid, string_agg(DISTINCT sku, ', ') AS skus,
                              string_agg(DISTINCT listing_status, ', ') AS statuses
                       FROM kabinet_data.product_entity_listings GROUP BY 1, 2) l ON l.marketplace_id = e.marketplace_id AND l.peid = e.peid
            LEFT JOIN (SELECT marketplace_id, peid,
                              string_agg(check_code || CASE severity WHEN 'error' THEN ' ⛔' WHEN 'warning' THEN ' ⚠' ELSE '' END,
                                         ', ' ORDER BY severity, check_code) AS issues,
                              count(*) FILTER (WHERE severity = 'error') AS n_err
                       FROM kabinet_data.product_entity_checks GROUP BY 1, 2) c ON c.marketplace_id = e.marketplace_id AND c.peid = e.peid
            ORDER BY m.code, (c.n_err IS NULL), c.n_err DESC, e.peid
        """)
        f1, f2, f3, f4, f5 = st.columns([1.2, 1.8, 1, 1, 1])
        _mps = sorted(pe["mp"].unique())
        mp_sel = f1.multiselect(_tr("pe_mp"), _mps, default=[m for m in ("AMZ-ES",) if m in _mps], placeholder=_tr("ph_any"), key="pe_mp")
        search = f2.text_input(_tr("pe_search"), key="pe_search").strip()
        only_issues = f3.toggle(_tr("pe_only_issues"), value=False, key="pe_issues")
        hide_parents = f4.toggle(_tr("pe_hide_parents"), value=False, key="pe_parents")
        hide_inactive = f5.toggle(_tr("pe_hide_inactive"), value=True, key="pe_inactive")
        view = pe.copy()
        if mp_sel:
            view = view[view["mp"].isin(mp_sel)]
        if search:
            m = (view["peid"].str.contains(search, case=False, na=False)
                 | view["title"].fillna("").str.contains(search, case=False, na=False)
                 | view["skus"].fillna("").str.contains(search, case=False, na=False))
            view = view[m]
        if only_issues:
            view = view[view["issues"].notna()]
        if hide_parents:
            view = view[~view["is_parent"]]
        if hide_inactive:
            view = view[view["is_active"]]
        st.caption(_trf("pe_summary", total=len(pe), active=int(pe["is_active"].sum()), parents=int(pe["is_parent"].sum()),
                        err=int((pe["n_err"].fillna(0) > 0).sum())))
        for c in ("title", "skus", "statuses", "group_name", "issues", "comment", "seen"):
            view[c] = view[c].fillna("")
        # дата только для чтения: NaT редактор пишет словом «None», текстовая метка — пусто
        view["last_seen"] = ["" if pd.isna(d) else pd.Timestamp(d).strftime("%d.%m.%Y") for d in view["last_seen"]]
        view["url"] = view["url"].fillna("")
        cols = ["mp", "peid", "title", "skus", "statuses", "is_parent", "group_name", "is_active", "issues", "last_seen", "seen", "comment", "url"]
        # группа правится только при одном выбранном маркетплейсе: варианты списка — группы этого рынка (ТЗ 006 §8)
        _one_mp = mp_sel[0] if len(mp_sel) == 1 else None
        _grp_opts = []
        if _one_mp and has_table("kabinet_data.variation_groups"):
            _g = q1("""SELECT g.id, g.name FROM kabinet_data.variation_groups g JOIN kabinet_data.marketplaces_new m ON m.id = g.marketplace_id
                       WHERE m.code = %s AND g.is_active ORDER BY g.name""", (_one_mp,))
            _grp_opts = _g["name"].tolist(); _grp_id = dict(zip(_g["name"], _g["id"]))
            st.caption(_tr("pe_group_edit_hint"))
        # пустой вариант в SelectboxColumn Streamlit рисует словом «None» — берём прочерк, как в приоритетах склада
        _no_group = _tr("prio_empty")
        if _one_mp:
            view["group_name"] = view["group_name"].replace("", _no_group)
        _group_col = (st.column_config.SelectboxColumn(_tr("pe_col_group"), options=[_no_group] + _grp_opts, width="medium") if _one_mp
                      else st.column_config.TextColumn(_tr("pe_col_group"), width="medium"))
        ed = st.data_editor(
            view[cols], key="ed_peid", use_container_width=True, height=560, hide_index=True, num_rows="fixed",
            disabled=["mp", "peid", "title", "skus", "statuses", "is_parent", "issues", "last_seen", "seen", "url"] + ([] if _one_mp else ["group_name"]),
            column_config={
                "mp": st.column_config.TextColumn(_tr("pe_col_mp"), width="small"),
                "peid": st.column_config.TextColumn(_tr("pe_col_peid"), width="small"),
                "title": st.column_config.TextColumn(_tr("pe_col_title"), width="large"),
                "skus": st.column_config.TextColumn(_tr("pe_col_skus"), width="small"),
                "statuses": st.column_config.TextColumn(_tr("pe_col_status"), width="small"),
                "is_parent": st.column_config.CheckboxColumn(_tr("pe_col_parent"), width="small"),
                "group_name": _group_col,
                "is_active": st.column_config.CheckboxColumn(_tr("pe_col_active"), width="small"),
                "issues": st.column_config.TextColumn(_tr("pe_col_issues"), width="medium"),
                "last_seen": st.column_config.TextColumn(_tr("pe_col_last"), width="small"),
                "seen": st.column_config.TextColumn(_tr("pe_col_seen"), width="small"),
                "comment": st.column_config.TextColumn(_tr("pe_col_comment"), width="medium"),
                "url": st.column_config.LinkColumn("URL", width="small", display_text="↗"),
            },
        )
        if st.button(_tr("save"), key="save_peid", type="primary"):
            before = view.set_index(["mp", "peid"])
            ids = view.set_index(["mp", "peid"])["id"]
            stmts = []
            for _, r in ed.iterrows():
                key = (r["mp"], r["peid"]); sets, params = [], []
                if bool(r["is_active"]) != bool(before.at[key, "is_active"]):
                    sets += ["is_active = %s", "active_source = 'manual'"]; params.append(bool(r["is_active"]))
                if (r["comment"] or "") != (before.at[key, "comment"] or ""):
                    sets.append("comment = %s"); params.append(r["comment"] or None)
                _grp_new = "" if r["group_name"] in ("", _no_group) else r["group_name"]
                _grp_old = "" if before.at[key, "group_name"] in ("", _no_group) else before.at[key, "group_name"]
                if _one_mp and _grp_new != _grp_old:
                    new_gid = _grp_id.get(_grp_new) if _grp_new else None
                    sets += ["variation_group_id = %s", "group_source = 'manual'"]; params.append(new_gid)
                    stmts.append(("INSERT INTO kabinet_data.product_entity_change_log (marketplace_id, peid, field, old_value, new_value, source, actor) "
                                  "SELECT marketplace_id, peid, 'variation_group_id', %s, %s, 'manual', 'kabinet' FROM kabinet_data.product_entities WHERE id = %s",
                                  (_grp_old or None, _grp_new or None, int(ids.at[key]))))
                    # ТЗ 008 §11 и 009 §9: роль принадлежит паре «PeID + группа». Сменили группу —
                    # прежняя роль закрывается и НЕ переносится; для новой группы её назначают заново.
                    # Раньше это делалось только при деактивации группы, а при обычной смене роль
                    # молча оставалась от прежней группы.
                    stmts.append(("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) "
                                  "SELECT 'representation', r.id, 'commercial_role', r.commercial_role, NULL, 'group_changed', 'kabinet' "
                                  f"FROM {AR_PE} r JOIN kabinet_data.product_entities e "
                                  "  ON e.marketplace_id = r.marketplace_id AND e.peid = r.peid "
                                  "WHERE e.id = %s AND r.commercial_role IS NOT NULL AND r.valid_to IS NULL",
                                  (int(ids.at[key]),)))
                    stmts.append((f"UPDATE {AR_PE} r SET commercial_role = NULL, role_since = NULL, updated_at = now() "
                                  "FROM kabinet_data.product_entities e "
                                  "WHERE e.marketplace_id = r.marketplace_id AND e.peid = r.peid "
                                  "  AND e.id = %s AND r.commercial_role IS NOT NULL AND r.valid_to IS NULL",
                                  (int(ids.at[key]),)))
                if sets:
                    stmts.append((f"UPDATE {PE} SET {', '.join(sets)}, updated_at = now(), updated_by = 'kabinet' WHERE id = %s",
                                  params + [int(ids.at[key])]))
            if not stmts:
                st.info(_tr("nochange"))
            else:
                try:
                    exec_sql(stmts)
                    st.cache_data.clear()
                    st.success(_trf("pe_saved", n=len(stmts)))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

        # ── создание записи (ТЗ 008 §8): в контексте одного маркетплейса, уникальность и против групповых PeID (§11)
        if _one_mp:
            with st.expander(_tr("pe_add_title")):
                st.caption(_tr("pe_add_hint"))
                a1, a2 = st.columns([1, 2])
                _np = a1.text_input(_tr("pe_add_peid"), key="pe_add_peid").strip()
                _nt = a2.text_input(_tr("pe_add_name"), key="pe_add_name").strip()
                a3, a4 = st.columns(2)
                _ng = a3.selectbox(_tr("pe_add_group"), [""] + _grp_opts, key="pe_add_group")
                _nc = a4.text_input(_tr("pe_add_comment"), key="pe_add_comment").strip()
                if st.button(_tr("pe_add_btn"), key="pe_add_btn"):
                    if not _np:
                        st.error(_tr("pe_add_empty"))
                    else:
                        _mpid = int(q1("SELECT id FROM kabinet_data.marketplaces_new WHERE code = %s", (_one_mp,))["id"].iloc[0])
                        _dup = q1("SELECT 1 FROM kabinet_data.product_entities WHERE marketplace_id = %s AND upper(peid) = upper(%s)", (_mpid, _np))
                        _dupg = q1("SELECT name FROM kabinet_data.variation_groups WHERE marketplace_id = %s AND upper(group_peid) = upper(%s)", (_mpid, _np)) \
                            if has_table("kabinet_data.variation_groups") else pd.DataFrame()
                        if len(_dup):
                            st.error(_trf("pe_add_dup", p=_np, mp=_one_mp))
                        elif len(_dupg):
                            st.error(_trf("pe_add_dup_group", p=_np, g=_dupg["name"].iloc[0], mp=_one_mp))
                        else:
                            try:
                                _gid = _grp_id.get(_ng) if _ng else None
                                exec_sql([
                                    (f"INSERT INTO {PE} (marketplace_id, peid, variation_group_id, group_source, title, is_parent, is_active, active_source, seen_in, comment, updated_by) "
                                     f"VALUES (%s, %s, %s, %s, %s, FALSE, TRUE, 'manual', ARRAY['manual'], %s, 'kabinet')",
                                     (_mpid, _np, _gid, "manual" if _gid else None, _nt or None, _nc or None)),
                                    ("INSERT INTO kabinet_data.product_entity_change_log (marketplace_id, peid, field, old_value, new_value, source, actor) VALUES (%s, %s, 'created', NULL, %s, 'manual', 'kabinet')",
                                     (_mpid, _np, _ng or None)),
                                ])
                                st.cache_data.clear()
                                st.success(_trf("pe_add_ok", p=_np, mp=_one_mp))
                                st.rerun()
                            except Exception as e:
                                st.error(_trf("err", e=e))

        # ── связи в матрице (ТЗ 008 §5, §8): PeID ↔ SKU только через регистр представления, история видна
        if _one_mp and has_table("kabinet_data.assortment_representations") and len(view):
            with st.expander(_tr("pe_links_title")):
                _lp = st.selectbox(_tr("pe_links_pick"), sorted(view["peid"].astype(str)), key="pe_links_pick")
                _lk = q1("""SELECT a.sku, r.valid_from, r.valid_to, r.commercial_role, a.added_on, a.removed_on
                            FROM kabinet_data.assortment_representations r
                            JOIN kabinet_data.assortment_admissions a ON a.id = r.admission_id
                            JOIN kabinet_data.marketplaces_new m ON m.id = r.marketplace_id
                            WHERE m.code = %s AND r.peid = %s ORDER BY r.valid_to IS NULL DESC, r.valid_from DESC""", (_one_mp, _lp))
                if _lk.empty:
                    st.caption(_tr("pe_links_none"))
                else:
                    _vt = pd.to_datetime(_lk.get("valid_to"), errors="coerce")
                    _lk["state"] = [(_tr("pe_links_active") if (pd.isna(v) or v.date() > date.today()) else _tr("pe_links_hist")) for v in _vt]
                    for c in ("sku", "valid_from", "valid_to", "commercial_role", "added_on", "removed_on"):
                        if c not in _lk.columns:
                            _lk[c] = None
                    _lk = _lk[["sku", "state", "valid_from", "valid_to", "commercial_role", "added_on", "removed_on"]]
                    _lk.columns = [_tr("pe_links_col_sku"), _tr("pe_links_col_state"), _tr("pe_links_col_from"), _tr("pe_links_col_to"),
                                   _tr("pe_links_col_role"), _tr("pe_links_col_adm"), _tr("pe_links_col_adm_to")]
                    st.dataframe(_lk, hide_index=True, use_container_width=True, height=min(300, 38 + 35 * len(_lk)))


# ---------------------------------------------------------------- вариации ---
def _section_vg():
    st.caption(_tr("vg_hint"))
    VG = "kabinet_data.variation_groups"
    if not has_table(VG):
        st.info(_tr("no_data"))
    else:
        vg = q(f"""
            SELECT g.id, m.code AS mp, g.name, g.name_source, g.group_peid, g.url, g.is_family, g.is_active, g.source, g.comment,
                   COALESCE(e.members, 0) AS members, c.issues
            FROM {VG} g
            JOIN kabinet_data.marketplaces_new m ON m.id = g.marketplace_id
            LEFT JOIN (SELECT variation_group_id, count(*) AS members FROM kabinet_data.product_entities
                       WHERE variation_group_id IS NOT NULL GROUP BY 1) e ON e.variation_group_id = g.id
            LEFT JOIN (SELECT group_id, string_agg(check_code || CASE severity WHEN 'error' THEN ' ⛔' WHEN 'warning' THEN ' ⚠' ELSE '' END,
                                                    ', ' ORDER BY severity, check_code) AS issues
                       FROM kabinet_data.variation_group_checks GROUP BY 1) c ON c.group_id = g.id
            ORDER BY m.code, g.name
        """)
        g1, g2, g3 = st.columns([1.2, 2, 1])
        _mps = sorted(vg["mp"].unique())
        mp_sel = g1.multiselect(_tr("vg_col_mp"), _mps, default=[m for m in ("AMZ-ES",) if m in _mps], placeholder=_tr("ph_any"), key="vg_mp")
        search = g2.text_input(_tr("pe_search"), key="vg_search").strip()
        only_issues = g3.toggle(_tr("pe_only_issues"), value=False, key="vg_issues")
        view = vg.copy()
        if mp_sel:
            view = view[view["mp"].isin(mp_sel)]
        if search:
            view = view[view["name"].str.contains(search, case=False, na=False) | view["group_peid"].fillna("").str.contains(search, case=False, na=False)]
        if only_issues:
            view = view[view["issues"].notna()]
        st.caption(_trf("vg_summary", total=len(vg), active=int(vg["is_active"].sum()), members=int(vg["members"].sum()),
                        issues=int(vg["issues"].notna().sum())))
        for c in ("group_peid", "comment", "issues", "url"):
            view[c] = view[c].fillna("")
        cols = ["id", "mp", "name", "group_peid", "members", "is_family", "is_active", "issues", "source", "comment", "url"]
        # ключ строки — id: у групп, заведённых руками, группового PeID может не быть (ТЗ 006 §3 «условно»)
        ed = st.data_editor(
            view[cols], key="ed_vg", use_container_width=True, height=480, hide_index=True, num_rows="fixed",
            disabled=["id", "mp", "group_peid", "members", "issues", "source"],
            column_config={
                "id": None,
                "mp": st.column_config.TextColumn(_tr("vg_col_mp"), width="small"),
                "name": st.column_config.TextColumn(_tr("vg_col_name"), width="large"),
                "group_peid": st.column_config.TextColumn(_tr("vg_col_peid"), width="small"),
                "members": st.column_config.NumberColumn(_tr("vg_col_members"), format="%d", width="small"),
                "is_family": st.column_config.CheckboxColumn(_tr("vg_col_family"), width="small"),
                "is_active": st.column_config.CheckboxColumn(_tr("vg_col_active"), width="small"),
                "issues": st.column_config.TextColumn(_tr("vg_col_issues"), width="medium"),
                "source": st.column_config.TextColumn(_tr("vg_col_src"), width="small"),
                "comment": st.column_config.TextColumn(_tr("vg_col_comment"), width="medium"),
                "url": st.column_config.TextColumn("URL", width="medium", help=_tr("vg_url_help")),
            },
        )
        if st.button(_tr("save"), key="save_vg", type="primary"):
            before = view.set_index("id")
            stmts, closed, bad_url = [], [], []
            VGL = "INSERT INTO kabinet_data.variation_group_change_log (group_id, field, old_value, new_value, source, actor) VALUES (%s, %s, %s, %s, 'manual', 'kabinet')"
            for _, r in ed.iterrows():
                gid = int(r["id"]); sets, params = [], []
                if (r["name"] or "") != (before.at[gid, "name"] or ""):
                    if not (r["name"] or "").strip():
                        continue                                            # название обязательно (§8) — пустое не записываем
                    sets += ["name = %s", "name_source = 'manual'"]; params.append(r["name"]); stmts.append((VGL, (gid, "name", before.at[gid, "name"], r["name"])))
                if (r["url"] or "") != (before.at[gid, "url"] or ""):
                    if r["url"] and not str(r["url"]).lower().startswith(("http://", "https://")):
                        bad_url.append(r["name"]); continue                 # §8: URL проверяется как URL
                    sets.append("url = %s"); params.append(r["url"] or None); stmts.append((VGL, (gid, "url", before.at[gid, "url"] or None, r["url"] or None)))
                if bool(r["is_family"]) != bool(before.at[gid, "is_family"]):
                    sets.append("is_family = %s"); params.append(bool(r["is_family"])); stmts.append((VGL, (gid, "is_family", str(bool(before.at[gid, "is_family"])), str(bool(r["is_family"])))))
                if bool(r["is_active"]) != bool(before.at[gid, "is_active"]):
                    sets += ["is_active = %s", "active_source = 'manual'"]; params.append(bool(r["is_active"])); stmts.append((VGL, (gid, "is_active", str(bool(before.at[gid, "is_active"])), str(bool(r["is_active"])))))
                    if not bool(r["is_active"]):
                        # §11: деактивированная группа недоступна вариантам и ролям — действующие связи закрываем и оставляем в истории
                        stmts.append(("INSERT INTO kabinet_data.product_entity_change_log (marketplace_id, peid, field, old_value, new_value, source, actor) "
                                      "SELECT marketplace_id, peid, 'variation_group_id', %s, NULL, 'group_deactivated', 'kabinet' FROM kabinet_data.product_entities WHERE variation_group_id = %s", (str(gid), gid)))
                        stmts.append(("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) "
                                      "SELECT 'representation', r.id, 'commercial_role', r.commercial_role, NULL, 'group_deactivated', 'kabinet' "
                                      "FROM kabinet_data.assortment_representations r JOIN kabinet_data.product_entities e ON e.marketplace_id = r.marketplace_id AND e.peid = r.peid "
                                      "WHERE e.variation_group_id = %s AND r.commercial_role IS NOT NULL AND (r.valid_to IS NULL OR r.valid_to > current_date)", (gid,)))
                        stmts.append(("UPDATE kabinet_data.assortment_representations r SET commercial_role = NULL, role_since = NULL, updated_at = now() "
                                      "FROM kabinet_data.product_entities e WHERE e.marketplace_id = r.marketplace_id AND e.peid = r.peid AND e.variation_group_id = %s "
                                      "AND r.commercial_role IS NOT NULL AND (r.valid_to IS NULL OR r.valid_to > current_date)", (gid,)))
                        stmts.append(("UPDATE kabinet_data.product_entities SET variation_group_id = NULL, group_source = 'manual', updated_at = now(), updated_by = 'kabinet' WHERE variation_group_id = %s", (gid,)))
                        closed.append(f"{r['name']} ({int(before.at[gid, 'members'] or 0)})")
                if (r["comment"] or "") != (before.at[gid, "comment"] or ""):
                    sets.append("comment = %s"); params.append(r["comment"] or None); stmts.append((VGL, (gid, "comment", before.at[gid, "comment"] or None, r["comment"] or None)))
                if sets:
                    stmts.append((f"UPDATE {VG} SET {', '.join(sets)}, updated_at = now(), updated_by = 'kabinet' WHERE id = %s", params + [gid]))
            if bad_url:
                st.error(_trf("vg_bad_url", names=", ".join(bad_url[:10])))
            if not stmts:
                if not bad_url:
                    st.info(_tr("nochange"))
            else:
                try:
                    exec_sql(stmts)
                    st.cache_data.clear()
                    st.success(_trf("vg_saved", n=len(stmts)))
                    if closed:
                        st.warning(_trf("vg_deactivated", groups="; ".join(closed)))
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

        # ── создание группы (ТЗ 006 §2, §8): только на маркетплейсах с вариационными семьями, групповой PeID уникален
        #    внутри маркетплейса и против вариантных PeID (§11)
        with st.expander(_tr("vg_add_title")):
            st.caption(_tr("vg_add_hint"))
            # обозначения теперь на площадке (ТЗ 003 §3), а выбор — только у активной площадки (§7)
            _fam = q("SELECT id, code FROM kabinet_data.v_marketplaces_selectable WHERE variation_group_label IS NOT NULL ORDER BY code")
            if _fam.empty or "code" not in _fam.columns:
                _fam = pd.DataFrame(columns=["id", "code"])
            c1, c2 = st.columns([1, 2])
            _vmp = c1.selectbox(_tr("vg_col_mp"), _fam["code"].tolist(), key="vg_add_mp")
            _vname = c2.text_input(_tr("vg_col_name"), key="vg_add_name").strip()
            c3, c4 = st.columns(2)
            _vpeid = c3.text_input(_tr("vg_add_peid"), key="vg_add_peid").strip()
            _vurl = c4.text_input("URL", key="vg_add_url").strip()
            _vcom = st.text_input(_tr("vg_col_comment"), key="vg_add_comment").strip()
            if st.button(_tr("vg_add_btn"), key="vg_add_btn", disabled=_vmp is None):
                _vmid = int(_fam.loc[_fam["code"] == _vmp, "id"].iloc[0])
                if not _vname:
                    st.error(_tr("vg_add_no_name"))
                elif _vurl and not _vurl.lower().startswith(("http://", "https://")):
                    st.error(_trf("vg_bad_url", names=_vname))
                else:
                    _dup = q1("SELECT name FROM kabinet_data.variation_groups WHERE marketplace_id = %s AND upper(group_peid) = upper(%s)", (_vmid, _vpeid)) if _vpeid else pd.DataFrame()
                    _var = q1("SELECT peid, is_parent FROM kabinet_data.product_entities WHERE marketplace_id = %s AND upper(peid) = upper(%s)", (_vmid, _vpeid)) if _vpeid else pd.DataFrame()
                    if len(_dup):
                        st.error(_trf("vg_add_dup", p=_vpeid, g=_dup["name"].iloc[0], mp=_vmp))
                    elif len(_var) and not bool(_var["is_parent"].iloc[0]):
                        st.error(_trf("vg_add_is_variant", p=_vpeid, mp=_vmp))
                    else:
                        try:
                            exec_sql([
                                (f"INSERT INTO {VG} (marketplace_id, name, name_source, group_peid, url, is_family, is_active, active_source, source, comment, updated_by) "
                                 f"VALUES (%s, %s, 'manual', %s, %s, TRUE, TRUE, 'manual', 'manual', %s, 'kabinet')", (_vmid, _vname, _vpeid or None, _vurl or None, _vcom or None)),
                                ("INSERT INTO kabinet_data.variation_group_change_log (group_id, field, old_value, new_value, source, actor) "
                                 "SELECT id, 'created', NULL, %s, 'manual', 'kabinet' FROM kabinet_data.variation_groups WHERE marketplace_id = %s AND name = %s ORDER BY id DESC LIMIT 1",
                                 (_vpeid or _vname, _vmid, _vname)),
                            ])
                            st.cache_data.clear()
                            st.success(_trf("vg_add_ok", g=_vname, mp=_vmp))
                            st.rerun()
                        except Exception as e:
                            st.error(_trf("err", e=e))
        if not view.empty:
            pick = st.selectbox(_tr("vg_members_pick"), view["name"].tolist(), key="vg_pick")
            gid = int(view.loc[view["name"] == pick, "id"].iloc[0])
            mem = q1("""SELECT e.peid, e.title, l.skus, e.is_active, e.group_source
                        FROM kabinet_data.product_entities e
                        LEFT JOIN (SELECT marketplace_id, peid, string_agg(DISTINCT sku, ', ') AS skus
                                   FROM kabinet_data.product_entity_listings GROUP BY 1, 2) l ON l.marketplace_id = e.marketplace_id AND l.peid = e.peid
                        WHERE e.variation_group_id = %s ORDER BY e.peid""", (gid,))
            if mem.empty:
                st.caption(_tr("vg_members_none"))
            else:
                st.dataframe(mem, hide_index=True, use_container_width=True, column_config={
                    "peid": st.column_config.TextColumn(_tr("pe_col_peid")), "title": st.column_config.TextColumn(_tr("pe_col_title"), width="large"),
                    "skus": st.column_config.TextColumn(_tr("pe_col_skus")), "is_active": st.column_config.CheckboxColumn(_tr("pe_col_active")),
                    "group_source": st.column_config.TextColumn(_tr("vg_col_src"))})
            if has_table("kabinet_data.variation_group_change_log"):
                _gl = q1("SELECT changed_at, actor, field, old_value, new_value, source FROM kabinet_data.variation_group_change_log WHERE group_id = %s ORDER BY changed_at DESC LIMIT 200", (gid,))
                with st.expander(_trf("vg_log_title", n=len(_gl))):
                    if _gl.empty:
                        st.caption(_tr("vg_log_none"))
                    else:
                        _gl["changed_at"] = pd.to_datetime(_gl["changed_at"]).dt.strftime("%d.%m.%Y %H:%M")
                        st.dataframe(_gl, hide_index=True, use_container_width=True, height=min(300, 38 + 35 * len(_gl)))


# ----------------------------------------------------------------- матрица ---
def _section_matrix():
    st.caption(_tr("am_hint"))
    AA, AR = "kabinet_data.assortment_admissions", "kabinet_data.assortment_representations"
    HINT_WINDOW_DAYS = 90            # окно для подсказки роли: сессии и маржа за квартал
    if not has_table(AA):
        st.info(_tr("no_data"))
    else:
        am = q(f"""
            SELECT a.id, a.level, a.platform, m.code AS mp, a.marketplace_id, a.sku, s.name, s.sku_type, a.added_on, a.removed_on,
                   a.in_listing, a.complementary, a.reason, a.source, c.issues, c.n_err
            FROM {AA} a
            LEFT JOIN kabinet_data.marketplaces_new m ON m.id = a.marketplace_id
            LEFT JOIN kabinet_data.sku_master s ON s.sku = a.sku
            LEFT JOIN (SELECT record_id, string_agg(check_code || CASE severity WHEN 'error' THEN ' ⛔' WHEN 'warning' THEN ' ⚠' ELSE '' END,
                                                      ', ' ORDER BY severity, check_code) AS issues,
                              count(*) FILTER (WHERE severity = 'error') AS n_err
                       FROM kabinet_data.assortment_checks WHERE register = 'admission' GROUP BY 1) c ON c.record_id = a.id
            ORDER BY a.platform, m.code NULLS FIRST, a.sku, a.added_on DESC
        """)
        mps_all = q("SELECT id, code, platform_short, country_alpha2, variation_group_label FROM kabinet_data.v_marketplaces_selectable ORDER BY code")
        skus_all = q("SELECT sku, sku_type, intro_date, exit_date, restrictions, is_active FROM kabinet_data.sku_master ORDER BY sku")
        _sku_by = skus_all.set_index("sku")
        _mp_by_id = mps_all.set_index("id")
        _active_pl = set(zip(am.loc[(am["level"] == "platform") & am["removed_on"].isna(), "platform"],
                             am.loc[(am["level"] == "platform") & am["removed_on"].isna(), "sku"]))

        def _restricted(sku, platform, mid) -> bool:
            # ограничение применения SKU (ТЗ 005 §6): код площадки, код marketplace или страна покрытия
            if sku not in _sku_by.index: return False
            codes = set(_sku_by.at[sku, "restrictions"] or [])
            if platform in codes: return True
            if mid is not None and mid in _mp_by_id.index:
                return _mp_by_id.at[mid, "code"] in codes or _mp_by_id.at[mid, "country_alpha2"] in codes
            return False

        def _status(r) -> str:
            """Состояние записи не хранится, а вычисляется (ТЗ 007 §7): исключённая — история; действующая без
            рамочного допуска или под ограничением — расчётно недоступна; SKU выведен — только распродажа (ТЗ 010)."""
            if pd.notna(r["removed_on"]): return "history"
            mid = None if pd.isna(r["marketplace_id"]) else int(r["marketplace_id"])
            if r["level"] == "marketplace" and (r["platform"], r["sku"]) not in _active_pl: return "blocked_platform"
            if _restricted(r["sku"], r["platform"], mid): return "blocked_restricted"
            if r["sku"] in _sku_by.index and not bool(_sku_by.at[r["sku"], "is_active"]): return "blocked_inactive"
            if r["sku"] in _sku_by.index and pd.notna(_sku_by.at[r["sku"], "exit_date"]) and _sku_by.at[r["sku"], "exit_date"] <= date.today(): return "selloff"
            return "active"
        am["status"] = am.apply(_status, axis=1)
        _st_lbl = {k: _tr(f"am_st_{k}") for k in ("active", "selloff", "blocked_platform", "blocked_restricted", "blocked_inactive", "history")}

        _saved_msg = st.session_state.pop("am_saved_msg", None)
        if _saved_msg:
            st.success(_saved_msg)
        for _m in st.session_state.pop("am_rejected_msgs", []):
            st.error(_m)
        f1, f2, f3, f4, f5, f6 = st.columns([1, 1, 1.2, 1.4, 1.3, 1])
        _lvl = {"marketplace": _tr("am_level_marketplace"), "platform": _tr("am_level_platform")}
        lvl_sel = f1.selectbox(_tr("am_level"), list(_lvl), format_func=_lvl.get, key="am_level")
        pl_sel = f2.multiselect(_tr("am_platform"), sorted(am["platform"].unique()), key="am_platform", placeholder=_tr("ph_any"))
        mp_sel = f3.multiselect(_tr("am_mp"), sorted(am["mp"].dropna().unique()), key="am_mp", placeholder=_tr("ph_any"))
        search = f4.text_input(_tr("am_search"), key="am_search").strip()
        # текущий срез и история — раздельно (ТЗ 007 §11); расчётно недоступные — отдельным видом (§6)
        _views = {"current": _tr("am_view_current"), "selloff": _tr("am_view_selloff"), "blocked": _tr("am_view_blocked"),
                  "history": _tr("am_view_history"), "all": _tr("am_view_all")}
        view_sel = f5.selectbox(_tr("am_view"), list(_views), format_func=_views.get, key="am_view")
        show_hist = view_sel in ("history", "all")
        only_issues = f6.toggle(_tr("am_only_issues"), value=False, key="am_issues")

        view = am[am["level"] == lvl_sel].copy()
        if pl_sel: view = view[view["platform"].isin(pl_sel)]
        if mp_sel: view = view[view["mp"].isin(mp_sel)]
        if search: view = view[view["sku"].str.contains(search, case=False, na=False) | view["name"].fillna("").str.contains(search, case=False, na=False)]
        if view_sel == "current": view = view[view["removed_on"].isna()]
        elif view_sel == "selloff": view = view[view["status"] == "selloff"]
        elif view_sel == "blocked": view = view[view["status"].str.startswith("blocked")]
        elif view_sel == "history": view = view[view["removed_on"].notna()]
        if only_issues: view = view[view["issues"].notna()]
        act = am[am["removed_on"].isna() & (am["level"] == "marketplace")]
        st.caption(_trf("am_summary", n=len(act), listing=int(act["in_listing"].sum()), comp=int(act["complementary"].sum()),
                        selloff=int((act["status"] == "selloff").sum()),
                        blocked=int(act["status"].str.startswith("blocked").sum()), err=int((act["n_err"].fillna(0) > 0).sum())))
        for c in ("mp", "name", "reason", "issues", "sku_type"): view[c] = view[c].fillna("")
        view["added_on"] = pd.to_datetime(view["added_on"])
        # Пустую ячейку любого типа st.data_editor рисует словом «None» (проверено на 1.64: NaT, date/None,
        # arrow date, "" в selectbox). Поэтому дата исключения в сетке — текст только для чтения, а исключение
        # делается операцией ниже с датой и причиной, как в ТЗ 007 §6.
        view["removed_lbl"] = ["" if pd.isna(d) else pd.Timestamp(d).strftime("%d.%m.%Y") for d in view["removed_on"]]
        view["status_lbl"] = view["status"].map(_st_lbl)
        cols = ["platform", "mp", "sku", "name", "sku_type", "status_lbl", "added_on", "removed_lbl", "in_listing", "complementary", "reason", "source", "issues"]
        if view.empty:
            # пустая таблица рисуется словом «empty»; человеку нужно знать, что это фильтры, а не поломка
            st.info(_tr("am_view_empty"))
        ed = st.data_editor(
            view[cols], key=f"ed_am_{lvl_sel}_{view_sel}", use_container_width=True,
            height=440 if not view.empty else 80, hide_index=True, num_rows="fixed",
            disabled=["platform", "mp", "sku", "name", "sku_type", "status_lbl", "added_on", "removed_lbl", "source", "issues"],
            column_config={
                "status_lbl": st.column_config.TextColumn(_tr("am_col_status"), width="small"),
                "platform": st.column_config.TextColumn(_tr("am_col_platform"), width="small"),
                "mp": st.column_config.TextColumn(_tr("am_col_mp"), width="small"),
                "sku": st.column_config.TextColumn(_tr("am_col_sku"), width="small"),
                "name": st.column_config.TextColumn(_tr("am_col_name"), width="large"),
                "sku_type": st.column_config.TextColumn(_tr("am_col_type"), width="small"),
                "added_on": st.column_config.DateColumn(_tr("am_col_added"), format="DD.MM.YYYY", width="small"),
                "removed_lbl": st.column_config.TextColumn(_tr("am_col_removed"), width="small", help=_tr("am_col_removed_help")),
                "in_listing": st.column_config.CheckboxColumn(_tr("am_col_listing"), width="small"),
                "complementary": st.column_config.CheckboxColumn(_tr("am_col_comp"), width="small"),
                "reason": st.column_config.TextColumn(_tr("am_col_reason"), width="medium"),
                "source": st.column_config.TextColumn(_tr("am_col_source"), width="small"),
                "issues": st.column_config.TextColumn(_tr("am_col_issues"), width="medium"),
            },
        )

        # ── представления по выбранному маркетплейсу ──
        st.markdown(f"**{_tr('am_repr_title')}**")
        _mp_codes = sorted(am.loc[am["level"] == "marketplace", "mp"].dropna().unique())
        rp_mp = st.selectbox(_tr("am_repr_pick_mp"), _mp_codes, index=(_mp_codes.index("AMZ-ES") if "AMZ-ES" in _mp_codes else 0) if _mp_codes else None, key="am_repr_mp")
        roles = q("SELECT code, name FROM kabinet_data.commercial_roles WHERE is_active ORDER BY sort_order")
        rp = q1(f"""
            SELECT r.id, r.peid, a.sku, g.name AS group_name, e.variation_group_id, r.commercial_role, r.valid_from, r.valid_to, r.source, c.issues
            FROM {AR} r
            JOIN {AA} a ON a.id = r.admission_id
            JOIN kabinet_data.marketplaces_new m ON m.id = r.marketplace_id
            LEFT JOIN kabinet_data.product_entities e ON e.marketplace_id = r.marketplace_id AND e.peid = r.peid
            LEFT JOIN kabinet_data.variation_groups g ON g.id = e.variation_group_id
            LEFT JOIN (SELECT record_id, string_agg(check_code || CASE severity WHEN 'error' THEN ' ⛔' ELSE ' ⚠' END, ', ') AS issues
                       FROM kabinet_data.assortment_checks WHERE register = 'representation' GROUP BY 1) c ON c.record_id = r.id
            WHERE m.code = %s AND (r.valid_to IS NULL OR %s) ORDER BY a.sku, r.peid""", (rp_mp, bool(show_hist))) if rp_mp else pd.DataFrame()
        # ── подсказка роли по данным (ТЗ 009): считаем, показываем, но не проставляем ──
        # Роль — управленческое решение, поэтому колонка «Подсказка» только для чтения, рядом
        # написано, из чего она вышла. Автоматически роль не назначается нигде.
        def role_hints(mp_code: str, reps: pd.DataFrame) -> dict:
            if reps.empty:
                return {}
            row_mp = mps_all[mps_all["code"] == mp_code]
            if row_mp.empty or row_mp["platform_short"].iloc[0] != "AMZ":
                return {}                     # сессии по ASIN есть только у Amazon
            country = row_mp["country_alpha2"].iloc[0]
            tr = q1("""SELECT asin, sum(sessions)::int AS sessions, sum(ordered_sales)::numeric AS sales
                       FROM kabinet_data.sales_traffic_asin
                       WHERE marketplace = %s AND snapshot_date > current_date - %s GROUP BY 1""",
                    (country, HINT_WINDOW_DAYS))
            mg = q1("""SELECT e.norm_sku,
                              sum(e.net_proceeds_total - e.cogs * e.net_units_sold
                                  - coalesce(l.packing_cost, 0) - coalesce(l.shipping_cost, 0))
                                / nullif(sum(e.net_product_sales), 0) * 100 AS margin_pct
                       FROM kabinet_data.v_economics_summary_eur e
                       LEFT JOIN kabinet_data.economics_logistics l
                              ON l.sales_date = e.sales_date AND l.marketplace = e.marketplace
                             AND l.norm_sku = e.norm_sku
                       WHERE e.marketplace = %s AND e.sales_date > current_date - %s AND e.cogs IS NOT NULL
                       GROUP BY 1""", (country, HINT_WINDOW_DAYS))
            t = dict(zip(tr["asin"], zip(tr["sessions"], tr["sales"]))) if not tr.empty else {}
            m = dict(zip(mg["norm_sku"], mg["margin_pct"])) if not mg.empty else {}
            out = {}
            for gid, grp in reps[reps["variation_group_id"].notna()].groupby("variation_group_id"):
                rows_g = []
                for r in grp.itertuples():
                    sess, sales = t.get(r.peid, (None, None))
                    rows_g.append({"id": r.id, "peid": r.peid,
                                   "sessions": float(sess) if sess is not None else None,
                                   "sales": float(sales) if sales is not None else None,
                                   "margin": float(m[r.sku]) if r.sku in m and pd.notna(m.get(r.sku)) else None})
                known = [x for x in rows_g if x["sales"] is not None or x["margin"] is not None]
                if not known:
                    for x in rows_g:
                        out[x["id"]] = ("", _tr("am_hint_nodata"))
                    continue
                sales_vals = [x["sales"] for x in rows_g if x["sales"]]
                sess_vals = [x["sessions"] for x in rows_g if x["sessions"]]
                marg_vals = [x["margin"] for x in rows_g if x["margin"] is not None]
                leader = max(sales_vals) if sales_vals else None
                med_sess = float(pd.Series(sess_vals).median()) if sess_vals else None
                med_marg = float(pd.Series(marg_vals).median()) if marg_vals else None
                for x in rows_g:
                    if x["sales"] is None and x["margin"] is None:
                        out[x["id"]] = ("", _tr("am_hint_nodata")); continue
                    if leader and x["sales"] == leader and len(rows_g) > 1:
                        out[x["id"]] = ("HERO", _trf("am_hint_hero", s=f"{x['sales']:,.0f}".replace(",", " ")))
                    elif (x["sessions"] is not None and med_sess is not None and x["sessions"] >= med_sess
                          and x["margin"] is not None and med_marg is not None and x["margin"] < med_marg):
                        out[x["id"]] = ("TRAFFIC", _trf("am_hint_traffic", v=f"{x['sessions']:,.0f}".replace(",", " "),
                                                        m=f"{x['margin']:.0f}", g=f"{med_marg:.0f}"))
                    elif x["margin"] is not None and med_marg is not None and x["margin"] >= med_marg:
                        out[x["id"]] = ("MARGIN", _trf("am_hint_margin", m=f"{x['margin']:.0f}", g=f"{med_marg:.0f}"))
                    else:
                        out[x["id"]] = ("SUPPORT", _tr("am_hint_support"))
            return out

        if rp.empty:
            st.caption(_tr("am_repr_none")); ed_r = rp
        else:
            _role_none = _tr("am_role_none")
            for c in ("group_name", "issues"): rp[c] = rp[c].fillna("")
            rp["commercial_role"] = rp["commercial_role"].fillna("").replace("", _role_none)   # "" в selectbox рисуется как None
            rp["valid_from"] = pd.to_datetime(rp["valid_from"])
            rp["valid_to_lbl"] = ["" if pd.isna(d) else pd.Timestamp(d).strftime("%d.%m.%Y") for d in rp["valid_to"]]
            _hints = role_hints(rp_mp, rp)
            rp["hint"] = [(_hints.get(i, ("", ""))[0] or "") for i in rp["id"]]
            rp["hint_why"] = [(_hints.get(i, ("", ""))[1] or "") for i in rp["id"]]
            st.caption(_tr("am_role_help"))
            st.caption(_trf("am_hint_help", n=HINT_WINDOW_DAYS))
            ed_r = st.data_editor(
                rp[["sku", "peid", "group_name", "commercial_role", "hint", "hint_why",
                    "valid_from", "valid_to_lbl", "source", "issues"]],
                key=f"ed_am_repr_{rp_mp}", use_container_width=True, height=360, hide_index=True, num_rows="fixed",
                disabled=["sku", "peid", "group_name", "hint", "hint_why", "valid_from", "valid_to_lbl", "source", "issues"],
                column_config={
                    "sku": st.column_config.TextColumn(_tr("am_col_sku"), width="small"),
                    "peid": st.column_config.TextColumn(_tr("am_repr_col_peid"), width="small"),
                    "group_name": st.column_config.TextColumn(_tr("am_repr_col_group"), width="medium"),
                    "commercial_role": st.column_config.SelectboxColumn(_tr("am_repr_col_role"), options=[_role_none] + roles["code"].tolist(), width="small"),
                    "hint": st.column_config.TextColumn(_tr("am_hint_col"), width="small"),
                    "hint_why": st.column_config.TextColumn(_tr("am_hint_why_col"), width="large"),
                    "valid_from": st.column_config.DateColumn(_tr("am_repr_col_from"), format="DD.MM.YYYY", width="small"),
                    "valid_to_lbl": st.column_config.TextColumn(_tr("am_repr_col_to"), width="small"),
                    "source": st.column_config.TextColumn(_tr("am_col_source"), width="small"),
                    "issues": st.column_config.TextColumn(_tr("am_col_issues"), width="medium"),
                })

        if st.button(_tr("save"), key="save_am", type="primary"):
            stmts, n_a, n_r = [], 0, 0
            before = view.set_index("id"); ed_i = ed.copy(); ed_i.index = view.index
            rejected = []
            for idx, r in ed_i.iterrows():
                rid = int(view.at[idx, "id"]); sets, params = [], []
                if _py(before.at[rid, "removed_on"]) is not None:
                    # историческая запись не переоткрывается и не правится (ТЗ 007 §7) — только причина
                    if bool(r["in_listing"]) != bool(before.at[rid, "in_listing"]) or bool(r["complementary"]) != bool(before.at[rid, "complementary"]):
                        rejected.append(_trf("am_rej_history", sku=r["sku"])); continue
                if bool(r["complementary"]) and not bool(before.at[rid, "complementary"]):
                    if (r["sku_type"] or "") == "composite":
                        rejected.append(_trf("am_rej_comp_composite", sku=r["sku"])); continue
                    if lvl_sel == "platform":
                        rejected.append(_trf("am_rej_comp_platform", sku=r["sku"])); continue
                for f in ("in_listing", "complementary"):
                    if bool(r[f]) != bool(before.at[rid, f]):
                        sets.append(f"{f} = %s"); params.append(bool(r[f]))
                        stmts.append(("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) VALUES ('admission', %s, %s, %s, %s, 'manual', 'kabinet')",
                                      (rid, f, str(bool(before.at[rid, f])), str(bool(r[f])))))
                if (r["reason"] or "") != (before.at[rid, "reason"] or ""):
                    sets.append("reason = %s"); params.append(r["reason"] or None)
                if sets:
                    sets.append("source = CASE WHEN source LIKE 'seed%%' THEN 'manual' ELSE source END")
                    stmts.append((f"UPDATE {AA} SET {', '.join(sets)}, updated_at = now() WHERE id = %s", params + [rid])); n_a += 1
            if not rp.empty:
                rb = rp.set_index("id"); ed_ri = ed_r.copy(); ed_ri.index = rp.index
                for idx, r in ed_ri.iterrows():
                    rid = int(rp.at[idx, "id"]); sets, params = [], []
                    new_role = None if r["commercial_role"] in ("", _role_none) else r["commercial_role"]
                    old_role = None if rb.at[rid, "commercial_role"] in ("", _role_none) else rb.at[rid, "commercial_role"]
                    if new_role != old_role:
                        if new_role and pd.isna(rb.at[rid, "variation_group_id"]):
                            st.warning(_trf("am_role_no_group", peid=r["peid"]))
                        else:
                            sets += ["commercial_role = %s", "role_since = %s"]; params += [new_role, date.today()]
                            stmts.append(("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) VALUES ('representation', %s, 'commercial_role', %s, %s, 'manual', 'kabinet')",
                                          (rid, old_role, new_role)))
                    if sets:
                        stmts.append((f"UPDATE {AR} SET {', '.join(sets)}, source = CASE WHEN source LIKE 'seed%%' THEN 'manual' ELSE source END, updated_at = now() WHERE id = %s", params + [rid])); n_r += 1
            for msg in rejected: st.error(msg)
            if not stmts:
                if not rejected: st.info(_tr("nochange"))
            else:
                try:
                    exec_sql(stmts); st.cache_data.clear()
                    # отказы уже показаны выше; без rerun таблица осталась бы с несохранёнными значениями
                    st.session_state["am_saved_msg"] = _trf("am_saved", a=n_a, r=n_r)
                    st.session_state["am_rejected_msgs"] = rejected   # иначе rerun сотрёт отказы, показанные выше
                    st.rerun()
                except Exception as e:
                    st.error(_trf("err", e=e))

        # ── проверки ТЗ 007 §7–§8 и план записи: одни и те же для одиночного и массового добавления ──
        def _target_parts(level, target):
            if level == "platform":
                return target.split(":", 1)[1].strip() if ":" in target else target, None
            mrow = mps_all[mps_all["code"] == target]
            if mrow.empty: return None, None
            return mrow["platform_short"].iloc[0], int(mrow["id"].iloc[0])

        def admission_checks(level, target, sku, added_on, in_listing, comp):
            errs, warns = [], []
            platform, mid = _target_parts(level, target)
            if platform is None: errs.append(_tr("am_add_bad_target")); return errs, warns
            if level == "marketplace" and mid is None: errs.append(_tr("am_add_bad_target")); return errs, warns
            if level == "platform" and mid is not None: errs.append(_tr("am_add_bad_target")); return errs, warns
            srow = _sku_by.loc[sku]
            if pd.isna(srow["intro_date"]): errs.append(_tr("am_add_no_intro"))
            if pd.notna(srow["exit_date"]): errs.append(_tr("am_add_exited"))
            if not bool(srow["is_active"]): errs.append(_tr("am_add_sku_inactive"))
            if _restricted(sku, platform, mid): errs.append(_tr("am_add_restricted"))
            if comp and srow["sku_type"] == "composite": errs.append(_tr("am_add_comp_composite"))
            if comp and level == "platform": errs.append(_tr("am_rej_comp_platform_short"))
            if not in_listing and not comp: errs.append(_tr("am_add_no_flags"))
            if level == "marketplace" and (platform, sku) not in _active_pl: errs.append(_tr("am_add_no_platform"))
            same = am[(am["level"] == level) & (am["platform"] == platform) & (am["sku"] == sku)
                      & ((am["marketplace_id"] == mid) if mid is not None else am["marketplace_id"].isna())]
            if not same[same["removed_on"].isna()].empty: errs.append(_tr("am_add_dup"))
            last_closed = same["removed_on"].dropna().max() if not same.empty else pd.NaT
            if pd.notna(last_closed) and pd.Timestamp(added_on) <= pd.Timestamp(last_closed):
                errs.append(_trf("am_add_overlap", d=pd.Timestamp(last_closed).strftime("%d.%m.%Y")))   # периоды не пересекаются (§7)
            return errs, warns

        def admission_insert(level, target, sku, added_on, in_listing, comp, reason):
            platform, mid = _target_parts(level, target)
            return (f"""INSERT INTO {AA} (level, platform, marketplace_id, sku, added_on, in_listing, complementary, reason, source, created_by)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, 'manual', 'kabinet')""",
                    (level, platform, mid, sku, added_on, bool(in_listing), bool(comp), reason or None))

        def exclusion_plan(level, target, sku, removed_on, reason):
            """Исключение: закрыть действующую запись датой и её представления той же датой (§5, §7). Историю не трогаем."""
            platform, mid = _target_parts(level, target)
            if platform is None: return [_tr("am_add_bad_target")], []
            cur = am[(am["level"] == level) & (am["platform"] == platform) & (am["sku"] == sku) & am["removed_on"].isna()
                     & ((am["marketplace_id"] == mid) if mid is not None else am["marketplace_id"].isna())]
            if cur.empty: return [_tr("am_bulk_no_active")], []
            rid = int(cur["id"].iloc[0])
            if pd.Timestamp(removed_on) < pd.Timestamp(cur["added_on"].iloc[0]): return [_trf("am_rej_removed_before_added", sku=sku)], []
            stmts = [(f"UPDATE {AA} SET removed_on = %s, reason = COALESCE(%s, reason), source = CASE WHEN source LIKE 'seed%%' THEN 'manual' ELSE source END, updated_at = now() WHERE id = %s", (removed_on, reason or None, rid)),
                     ("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) VALUES ('admission', %s, 'removed_on', NULL, %s, 'manual', 'kabinet')", (rid, str(removed_on))),
                     (f"UPDATE {AR} SET valid_to = %s, updated_at = now() WHERE admission_id = %s AND valid_to IS NULL", (removed_on, rid))]
            return [], stmts

        # ── добавить SKU в матрицу — с проверками ТЗ 007 §8 ──
        with st.form("am_add", clear_on_submit=True):
            st.markdown(f"**{_tr('am_add_title')}**")
            st.caption(_tr("am_add_hint"))
            c1, c2, c3, c4 = st.columns([1, 1.2, 1.4, 1])
            a_level = c1.selectbox(_tr("am_level"), list(_lvl), format_func=_lvl.get)
            _pl_opts = sorted(mps_all["platform_short"].dropna().unique())
            a_target = c2.selectbox(_tr("am_add_target"), [f"{_tr('am_level_platform')}: {p_}" for p_ in _pl_opts] + mps_all["code"].tolist())
            a_sku = c3.selectbox(_tr("am_add_sku"), skus_all["sku"].tolist())
            a_date = c4.date_input(_tr("am_add_date"), value=date.today())
            c5, c6, c7 = st.columns([1, 1, 3])
            a_listing = c5.checkbox(_tr("am_col_listing"), value=True)
            a_comp = c6.checkbox(_tr("am_col_comp"), value=False)
            a_reason = c7.text_input(_tr("am_col_reason"))
            if st.form_submit_button(_tr("am_add_btn")):
                errs, warns = admission_checks(a_level, a_target, a_sku, a_date, bool(a_listing), bool(a_comp))
                for w_ in warns: st.warning(w_)
                if errs:
                    for e in errs: st.error(e)
                else:
                    try:
                        exec_sql([admission_insert(a_level, a_target, a_sku, a_date, bool(a_listing), bool(a_comp), a_reason)])
                        st.cache_data.clear(); st.success(_tr("am_add_ok")); st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))

        # ── массовые операции: список SKU → проверка каждой строки → подтверждение (ТЗ 007 §6) ──
        with st.expander(_tr("am_bulk_title")):
            st.caption(_tr("am_bulk_hint"))
            b1, b2, b3 = st.columns([1, 1.4, 1])
            _ops = {"add": _tr("am_bulk_add"), "remove": _tr("am_bulk_remove")}
            b_op = b1.selectbox(_tr("am_bulk_op"), list(_ops), format_func=_ops.get, key="am_bulk_op")
            b_target = b2.selectbox(_tr("am_add_target"), [f"{_tr('am_level_platform')}: {p_}" for p_ in _pl_opts] + mps_all["code"].tolist(), key="am_bulk_target")
            b_date = b3.date_input(_tr("am_bulk_date"), value=date.today(), key="am_bulk_date")
            b_level = "platform" if b_target.startswith(_tr("am_level_platform") + ":") else "marketplace"
            b4, b5, b6 = st.columns([1, 1, 3])
            b_listing = b4.checkbox(_tr("am_col_listing"), value=True, key="am_bulk_listing", disabled=(b_op == "remove"))
            b_comp = b5.checkbox(_tr("am_col_comp"), value=False, key="am_bulk_comp", disabled=(b_op == "remove"))
            b_reason = b6.text_input(_tr("am_col_reason"), key="am_bulk_reason")
            b_text = st.text_area(_tr("am_bulk_skus"), key="am_bulk_skus", height=120, placeholder="41324000\n58616000\n…")
            b_skus = []
            for tok in re.split(r"[\s,;]+", b_text or ""):
                tok = tok.strip()
                if tok and tok not in b_skus: b_skus.append(tok)
            if st.button(_tr("am_bulk_check"), key="am_bulk_check_btn", disabled=not b_skus):
                rows, plan = [], []
                for sku_ in b_skus:
                    if sku_ not in _sku_by.index:
                        rows.append({"sku": sku_, "ok": False, "result": _tr("am_bulk_unknown_sku")}); continue
                    if b_op == "add":
                        errs, warns = admission_checks(b_level, b_target, sku_, b_date, bool(b_listing), bool(b_comp))
                        rows.append({"sku": sku_, "ok": not errs, "result": "; ".join(errs + warns) or _tr("am_bulk_ok")})
                        if not errs: plan.append(admission_insert(b_level, b_target, sku_, b_date, bool(b_listing), bool(b_comp), b_reason))
                    else:
                        errs, stmts_ = exclusion_plan(b_level, b_target, sku_, b_date, b_reason)
                        rows.append({"sku": sku_, "ok": not errs, "result": "; ".join(errs) or _tr("am_bulk_ok")})
                        if not errs: plan += stmts_
                st.session_state["am_bulk_preview"] = {"rows": rows, "plan": plan, "sig": (b_op, b_target, str(b_date), bool(b_listing), bool(b_comp), b_reason, tuple(b_skus))}
            prev = st.session_state.get("am_bulk_preview")
            if prev and prev["sig"] == (b_op, b_target, str(b_date), bool(b_listing), bool(b_comp), b_reason, tuple(b_skus)):
                pv = pd.DataFrame(prev["rows"])
                st.dataframe(pv, use_container_width=True, hide_index=True,
                             column_config={"sku": st.column_config.TextColumn(_tr("am_col_sku"), width="small"),
                                            "ok": st.column_config.CheckboxColumn("OK", width="small"),
                                            "result": st.column_config.TextColumn(_tr("am_bulk_result"), width="large")})
                n_ok = int(pv["ok"].sum()); n_bad = len(pv) - n_ok
                st.caption(_trf("am_bulk_summary", ok=n_ok, bad=n_bad))
                if n_ok and st.button(_trf("am_bulk_apply", n=n_ok), key="am_bulk_apply_btn", type="primary"):
                    try:
                        exec_sql(prev["plan"]); st.session_state.pop("am_bulk_preview", None); st.cache_data.clear()
                        st.success(_trf("am_bulk_done", n=n_ok)); st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))
            elif prev:
                st.session_state.pop("am_bulk_preview", None)

        # ── новое представление: PeID под допущенным SKU (ТЗ 007 §5) ──
        with st.form("am_repr_add", clear_on_submit=True):
            st.markdown(f"**{_tr('am_repr_add_title')}**")
            st.caption(_tr("am_repr_add_hint"))
            r1, r2, r3, r4, r5 = st.columns([1, 1.2, 1.4, 1.1, 1.4])
            ra_mp = r1.selectbox(_tr("am_mp"), mps_all["code"].tolist(), index=(mps_all["code"].tolist().index(rp_mp) if rp_mp in mps_all["code"].tolist() else 0))
            _adm_sku = sorted(am.loc[(am["level"] == "marketplace") & (am["mp"] == ra_mp) & am["removed_on"].isna() & am["in_listing"], "sku"].unique())
            ra_sku = r2.selectbox(_tr("am_add_sku"), _adm_sku) if _adm_sku else r2.selectbox(_tr("am_add_sku"), [], disabled=True)
            ra_peid = r3.text_input(_tr("am_repr_col_peid")).strip()
            ra_from = r4.date_input(_tr("am_repr_col_from"), value=date.today())
            _role_none = _tr("am_role_none")
            ra_role = r5.selectbox(_tr("am_repr_col_role"), [_role_none] + roles["code"].tolist())
            ra_role = "" if ra_role == _role_none else ra_role
            if st.form_submit_button(_tr("am_repr_add_btn")):
                errs = []
                mid_ = int(mps_all.loc[mps_all["code"] == ra_mp, "id"].iloc[0])
                if not ra_sku: errs.append(_tr("am_repr_no_admitted_sku"))
                if not ra_peid: errs.append(_tr("am_repr_peid_required"))
                ent = q1("SELECT peid, is_parent, is_active, variation_group_id FROM kabinet_data.product_entities WHERE marketplace_id = %s AND peid = %s", (mid_, ra_peid)) if ra_peid else pd.DataFrame()
                if ra_peid and ent.empty: errs.append(_trf("am_repr_peid_not_on_mp", peid=ra_peid, mp=ra_mp))     # PeID должен относиться к этому marketplace (§8)
                elif not ent.empty and bool(ent.at[0, "is_parent"]): errs.append(_tr("am_repr_peid_parent"))
                elif not ent.empty and not bool(ent.at[0, "is_active"]): errs.append(_tr("am_repr_peid_inactive"))
                if ra_peid:
                    # один PeID одновременно представляет один SKU в marketplace (§5) — блокируем с указанием SKU A
                    busy = q1(f"SELECT a.sku FROM {AR} r JOIN {AA} a ON a.id = r.admission_id WHERE r.marketplace_id = %s AND r.peid = %s AND r.valid_to IS NULL", (mid_, ra_peid))
                    if not busy.empty:
                        if busy.at[0, "sku"] == ra_sku: errs.append(_tr("am_repr_dup_same"))
                        else: errs.append(_trf("am_repr_peid_busy", sku=busy.at[0, "sku"]))
                if ra_role and (ent.empty or pd.isna(ent.at[0, "variation_group_id"])): errs.append(_trf("am_role_no_group", peid=ra_peid))
                if ra_role and pd.isna(mps_all.loc[mps_all["code"] == ra_mp, "variation_group_label"].iloc[0]): errs.append(_tr("am_repr_mp_no_variations"))
                if errs:
                    for e in errs: st.error(e)
                else:
                    adm_id = int(am.loc[(am["level"] == "marketplace") & (am["mp"] == ra_mp) & am["removed_on"].isna() & (am["sku"] == ra_sku), "id"].iloc[0])
                    try:
                        exec_sql([(f"""INSERT INTO {AR} (admission_id, marketplace_id, peid, commercial_role, role_since, valid_from, source, created_by)
                                       VALUES (%s, %s, %s, %s, %s, %s, 'manual', 'kabinet')""",
                                   (adm_id, mid_, ra_peid, ra_role or None, date.today() if ra_role else None, ra_from)),
                                  ("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) VALUES ('representation', currval('kabinet_data.assortment_representations_id_seq'), 'created', NULL, %s, 'manual', 'kabinet')",
                                   (f"{ra_mp} {ra_sku} → {ra_peid}",))])
                        st.cache_data.clear(); st.success(_tr("am_repr_add_ok")); st.rerun()
                    except Exception as e:
                        st.error(_trf("err", e=e))

        # ── закрыть представление датой (§5): в сетке дата только для чтения ──
        if not rp.empty and (rp["valid_to"].isna()).any():
            with st.form("am_repr_close", clear_on_submit=True):
                st.markdown(f"**{_tr('am_repr_close_title')}**")
                c1, c2, c3 = st.columns([2, 1, 1])
                _open = rp[rp["valid_to"].isna()]
                _lbl = {int(r.id): f"{r.sku} → {r.peid}" for r in _open.itertuples()}
                rc_id = c1.selectbox(_tr("am_repr_close_pick"), list(_lbl), format_func=_lbl.get)
                rc_date = c2.date_input(_tr("am_repr_col_to"), value=date.today())
                if c3.form_submit_button(_tr("am_repr_close_btn")):
                    vf = _py(rp.set_index("id").at[rc_id, "valid_from"])
                    if vf is not None and rc_date < vf:
                        st.error(_tr("am_repr_close_before_from"))
                    else:
                        try:
                            exec_sql([(f"UPDATE {AR} SET valid_to = %s, source = CASE WHEN source LIKE 'seed%%' THEN 'manual' ELSE source END, updated_at = now() WHERE id = %s AND valid_to IS NULL", (rc_date, rc_id)),
                                      ("INSERT INTO kabinet_data.assortment_change_log (register, record_id, field, old_value, new_value, source, actor) VALUES ('representation', %s, 'valid_to', NULL, %s, 'manual', 'kabinet')", (rc_id, str(rc_date)))])
                            st.cache_data.clear(); st.success(_tr("am_repr_close_ok")); st.rerun()
                        except Exception as e:
                            st.error(_trf("err", e=e))


{"wh": _section_wh, "ch": _section_ch, "ctry": _section_ctry, "plat": _section_plat, "mp": _section_mp, "pool": _section_pool, "norm": _section_norm, "alerts": _section_alerts, "sku": _section_sku, "cat": _section_cat, "peid": _section_peid, "vg": _section_vg, "matrix": _section_matrix}[_sec]()

passport.footer("dictionaries")
